def get_explicit_residual(self, indices=None):
        """Explicitly computes the Ritz residual."""
        if indices is None:
            indices = self.indices
        return self.get_residual(indices)

def filter_by_effect_priority(self, min_priority_class):
        """
        Create a new EffectCollection containing only effects whose priority
        falls below the given class.
        """
        return EffectCollection(
            [effect for effect in self.effects if effect.priority < min_priority_class]
        )

def longest_dir_prefix(path, prefixes):
  """Given a list of prefixes, return the one that is the longest prefix to the given path.

  Returns None if there are no matches.
  """
  longest_match, longest_prefix = 0, None
  for prefix in prefixes:
    if fast_relpath_optional(path, prefix) is not None and len(prefix) > longest_match:
      longest_match, longest_prefix = len(prefix), prefix

  return longest_prefix

def longest_dir_prefix(path, prefixes):
  """Given a list of prefixes, return the one that is the longest prefix to the given path.

  Returns None if there are no matches.
  """
  for prefix in prefixes:
    if path.startswith(prefix):
      return prefix
  return None

def shellsafe(s, quote='', doescape=True):
    """Returns the value string, wrapped in the specified quotes (if not empty), but checks and raises an Exception if the string is at risk of causing code injection"""
    if sys.version[0] == '2' and not isinstance(s,unicode): #pylint: disable=undefined-variable
        s = unicode(s,'utf-8') #pylint: disable=undefined-variable
    if len(s) > 1024:
        raise ValueError("Variable value rejected for security reasons: too long")
    if quote:
        if quote in s:
            if doescape:
                s = escape(s,quote)
            else:
                raise ValueError("Variable value rejected for security reasons: " + s)
        return quote + s + quote
    else:
        for c in s:
            if c in DISALLOWINSHELLSAFE:
                raise ValueError("Variable value rejected for security reasons: " + s)
        return s

def shellsafe(s, quote='', doescape=True):
    """Returns the value string, wrapped in the specified quotes (if not empty), but checks and raises an Exception if the string is at risk of causing code injection"""
    if not s:
        return s
    if quote:
        if quote in s:
            raise ValueError("String contains quote character")
    if doescape:
        if'' in s:
            raise ValueError("String contains space character")
        if '\t' in s:
            raise ValueError("String contains tab character")
        if '\n' in s:
            raise ValueError("String contains newline character")
        if '\r' in s:
            raise ValueError("String contains carriage return character")
    return quote + s + quote

def level(self):
        """Extract level number from compliance profile URI.

        Returns integer level number or raises IIIFInfoError
        """
        try:
            return int(self.uri.split('/')[-1])
        except ValueError:
            raise IIIFInfoError('Invalid compliance profile URI')

def option(self, option):
        """
        Gets the option, set_section needs to be set before.

        :param option (string): The option to get.
        :return mixed: The option from from the config.
        """
        if self.set_section is None:
            raise Exception("You need to set the section first.")

        return self.config.get(self.set_section, option)

def _from_dict(cls, _dict):
        """Initialize a LogCollection object from a json dictionary."""
        args = {}
        if 'logs' in _dict:
            args['logs'] = [Log._from_dict(x) for x in (_dict.get('logs'))]
        else:
            raise ValueError(
                'Required property \'logs\' not present in LogCollection JSON')
        if 'pagination' in _dict:
            args['pagination'] = LogPagination._from_dict(
                _dict.get('pagination'))
        else:
            raise ValueError(
                'Required property \'pagination\' not present in LogCollection JSON'
            )
        return cls(**args)

def _from_dict(cls, _dict):
        """Initialize a LogCollection object from a json dictionary."""
        return cls.from_dict(_dict)

def _symlink_or_copy_grabix(in_file, out_file, data):
    """We cannot symlink in CWL, but may be able to use inputs or copy
    """
    if cwlutils.is_cwl_run(data):
        # Has grabix indexes, we're okay to go
        if utils.file_exists(in_file + ".gbi"):
            out_file = in_file
        else:
            utils.copy_plus(in_file, out_file)
    else:
        utils.symlink_plus(in_file, out_file)
    return out_file

def _symlink_or_copy_grabix(in_file, out_file, data):
    """We cannot symlink in CWL, but may be able to use inputs or copy
    """
    if os.path.exists(out_file):
        return
    if os.path.exists(in_file):
        shutil.copy(in_file, out_file)
    else:
        raise Exception("Cannot find %s" % in_file)

async def get_nym(self, target_did: str = None) -> str:
        """
        Get json cryptonym (including current verification key) for input (anchor) DID from ledger.
        Return empty production {} if the ledger has no such cryptonym.

        Raise BadLedgerTxn on failure. Raise WalletState if target DID is default (own DID) value but
        wallet does not have it (neither created nor opened since initialization).

        :param target_did: DID of cryptonym to fetch (default own DID)
        :return: cryptonym json
        """
        if target_did is None:
            target_did = self.own_did
        if target_did == self.own_did:
            if not self.own_did:
                raise WalletState("Wallet not initialized")
        else:
            if not self.is_did_known(target_did):
                raise WalletState(f"DID {target_did} not known")
        return await self.get_nym_for_did(target_did)

def get_group_list(value):
    """ group-list = mailbox-list / CFWS / obs-group-list
        obs-group-list = 1*([CFWS] ",") [CFWS]

    """
    if value.startswith('"') and value.endswith('"'):
        return [value[1:-1]]
    else:
        return value.split(',')

def format_value(value):
    """Returns the given value rounded to one decimal place if deciaml.

    Returns the integer if an integer is given.
    """
    value = decimal.Decimal(str(value))
    if int(value) == value:
        return int(value)

    # On Python 3, an explicit cast to float is required
    return float(round(value, 1))

def format_value(value):
    """Returns the given value rounded to one decimal place if deciaml.

    Returns the integer if an integer is given.
    """
    if isinstance(value, int):
        return value
    return round(value, 1)

