def _convert_point(self, metric, ts, point, sd_point):
        """Convert an OC metric point to a SD point."""
        if metric.type == 'gauge':
            return sd_point.gauge(ts, point)
        elif metric.type == 'counter':
            return sd_point.counter(ts, point)
        elif metric.type == 'histogram':
            return sd_point.histogram(ts, point)
        elif metric.type =='summary':
            return sd_point.summary(ts, point)
        else:
            raise ValueError('Unknown metric type: %s' % metric.type)

def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if self.cmdprefix:
            raise CmdError("prefix not allowed")
        targets = self.input_process_list( self.split_tokens(arg, 1) )
        if not targets:
            print("Error: missing parameters")
        else:
            debug = self.debug
            for pid in targets:
                try:
                    debug.attach(pid)
                    print("Attached to process (%d)" % pid)
                except Exception:
                    print("Error: can't attach to process (%d)" % pid)

def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if not arg:
            self.do_help('attach')
            return
        targets = arg.split()
        for target in targets:
            try:
                pid = int(target)
            except ValueError:
                self.do_help('attach')
                return
            try:
                self.attach(pid)
            except Exception as e:
                self.msg('attach failed: %s' % e)

def infer_len(node, context=None):
    """Infer length calls

    :param nodes.Call node: len call to infer
    :param context.InferenceContext: node context
    :rtype nodes.Const: a Const node with the inferred length, if possible
    """
    call = arguments.CallSite.from_call(node)
    if call.keyword_arguments:
        raise UseInferenceDefault("TypeError: len() must take no keyword arguments")
    if len(call.positional_arguments) != 1:
        raise UseInferenceDefault(
            "TypeError: len() must take exactly one argument "
            "({len}) given".format(len=len(call.positional_arguments))
        )
    [argument_node] = call.positional_arguments
    try:
        return nodes.Const(helpers.object_len(argument_node, context=context))
    except (AstroidTypeError, InferenceError) as exc:
        raise UseInferenceDefault(str(exc)) from exc

def infer_len(node, context=None):
    """Infer length calls

    :param nodes.Call node: len call to infer
    :param context.InferenceContext: node context
    :rtype nodes.Const: a Const node with the inferred length, if possible
    """
    if not isinstance(node.args[0], nodes.Const):
        return None

    if not isinstance(node.args[0].value, (list, tuple)):
        return None

    return nodes.Const(len(node.args[0].value))

