def comic_archive_uncompress(filename, image_format):
    """
    Uncompress comic archives.

    Return the name of the working directory we uncompressed into.
    """
    if not Settings.comics:
        report = ['Skipping archive file: {}'.format(filename)]
        return None, ReportStats(filename, report=report)

    if Settings.verbose:
        truncated_filename = stats.truncate_cwd(filename)
        print("Extracting {}...".format(truncated_filename), end='')

    # create the tmpdir
    tmp_dir = _get_archive_tmp_dir(filename)
    if os.path.isdir(tmp_dir):
        shutil.rmtree(tmp_dir)
    os.mkdir(tmp_dir)

    # extract archvie into the tmpdir
    if image_format == _CBZ_FORMAT:
        with zipfile.ZipFile(filename, 'r') as zfile:
            zfile.extractall(tmp_dir)
    elif image_format == _CBR_FORMAT:
        with rarfile.RarFile(filename, 'r') as rfile:
            rfile.extractall(tmp_dir)
    else:
        report = '{} {} is not a good format'.format(filename, image_format)
        return None, ReportStats(filename, report=report)

    if Settings.verbose:
        print('done')

    return tmp_dir, None

def retrieve_asset(self, sid, default_none=False):
        """
        Retrieve the Asset for a given sid.
        """
        try:
            asset = self._asset_cache[sid]
            if asset is None and not default_none:
                raise SidsNotFound(sids=[sid])
            return asset
        except KeyError:
            raise SidsNotFound(sids=[sid])

def retrieve_asset(self, sid, default_none=False):
        """
        Retrieve the Asset for a given sid.
        """
        if sid in self.assets:
            return self.assets[sid]
        elif default_none:
            return None
        else:
            raise ValueError("Asset with sid %s not found." % sid)

def _gather_group_members(group, groups, users):
    """
    Gather group members
    """
    _group = __salt__['group.info'](group)

    if not _group:
        log.warning('Group %s does not exist, ignoring.', group)
        return

    for member in _group['members']:
        if member not in users:
            users[member] = groups[group]

def _gather_group_members(group, groups, users):
    """
    Gather group members
    """
    if group.name in groups:
        return groups[group.name]
    else:
        members = []
        for user in users:
            if user.group_id == group.id:
                members.append(user.username)
        groups[group.name] = members
        return members

def validate_unwrap(self, value):
        """ Check that ``value`` is valid for unwrapping with ``ComputedField.computed_type``"""
        try:
            self.computed_type.validate_unwrap(value)
        except BadValueException as bve:
            self._fail_validation(value, 'Bad value for computed field', cause=bve)

def validate_unwrap(self, value):
        """ Check that ``value`` is valid for unwrapping with ``ComputedField.computed_type``"""
        if value is None:
            return None
        if not isinstance(value, self.computed_type):
            raise ValueError("Invalid value for unwrapping: %r" % value)
        return value

def delete(self):
        """ Delete a library section. """
        try:
            return self._server.query('/library/sections/%s' % self.key, method=self._server._session.delete)
        except BadRequest:  # pragma: no cover
            msg = 'Failed to delete library %s' % self.key
            msg += 'You may need to allow this permission in your Plex settings.'
            log.error(msg)
            raise

def do_map(input_dict, feature_format, positive_class=None):
    """
