def getFileCategory(self, fileInfo):
		"""Function to get the file category for file info"""
		if fileInfo.category == None:
			if fileInfo.fileType == "image":
				fileInfo.category = "image"
			elif fileInfo.fileType == "video":
				fileInfo.category = "video"
			elif fileInfo.fileType == "audio":
				fileInfo.category = "audio"
			elif fileInfo.fileType == "document":
				fileInfo.category = "document"
			elif fileInfo.fileType == "archive":
				fileInfo.category = "archive"
			elif fileInfo.fileType == "text":
				fileInfo.category = "text"
			elif fileInfo.fileType == "other":
				fileInfo.category = "other"
			else:
				fileInfo.category = "unknown"
		return fileInfo.category

def get_minimum(self, other):
        """Updates this vector so its components are the lower of its
        current components and those of the given other value."""
        return Point(min(self.x, other.x), min(self.y, other.y))

