def _parse_material(effect, resolver):
    """
    Turn a COLLADA effect into a trimesh material.
    """
    # Get the surface shader
    surface = effect.get('surface')
    if surface is None:
        raise ValueError('No surface shader found in effect')
    surface_type = surface.get('type')
    if surface_type is None:
        raise ValueError('No surface shader type found in effect')
    if surface_type == 'phong':
        shader = _parse_phong(surface, resolver)
    elif surface_type == 'lambert':
        shader = _parse_lambert(surface, resolver)
    elif surface_type == 'blinn':
        shader = _parse_blinn(surface, resolver)
    elif surface_type == 'constant':
        shader = _parse_constant(surface, resolver)
    else:
        raise ValueError('Unknown surface shader type: %s' % surface_type)

    # Get the surface parameters
    surface_params = surface.get('parameters')
    if surface_params is None:
        raise ValueError('No surface parameters found in effect')
    surface_params = surface_params.get('parameter')
    if surface_params is None:
        raise ValueError('No surface parameters found in effect')
    surface_params = {p.get('name'): p for p in surface_params}

    # Get the surface texture
    surface_texture = surface.get('texture')
    if surface_texture is None:
        raise ValueError('No surface texture found in effect')
    surface_texture = surface_texture.get('texture')
    if surface_texture is None:
        raise ValueError('No surface texture found in effect')
    surface_texture = surface_texture.get('texture')
    if surface_texture is None:
        raise ValueError('No surface texture found in effect')
    surface_texture = surface_texture.get('texture')
    if surface_texture is None:
        raise ValueError('No surface texture found in effect')
    surface_texture = surface_texture.get('texture')
    if surface_texture is None:
        raise ValueError('No surface texture found in effect')
    surface_texture = surface_texture.get('texture')
    if surface_texture is None:
        raise ValueError('No surface texture found in effect')
    surface_texture = surface_texture.get('texture')
    if surface_texture is None:
        raise ValueError('No surface texture found in effect')
    surface_texture = surface_texture.get('texture')
    if surface_texture is None:
        raise

def find_splice(cigar):
    """Takes a cigar string and finds the first splice position as
    an offset from the start. To find the 5' end (read coords) of
    the junction for a reverse read, pass in the reversed cigar tuple"""

    offset = 0
    # a soft clip at the end of the read is taken as splicing
    # where as a soft clip at the start is not.
    if cigar[0][0] == 4:
        offset = cigar[0][1]
        cigar = cigar[1:]

    for op, bases in cigar:
        if op in (3, 4):
            # N or S: found the splice
            return offset
        elif op in (0, 2, 7, 8):
            # M, D, = or X: reference consuming
            offset += bases
        elif op in (1, 5, 6):
            # I, H, P: non-reference consuming
            continue
        else:
            raise ValueError("Bad Cigar operation: %i" % op)

    return False

def find_splice(cigar):
    """Takes a cigar string and finds the first splice position as
    an offset from the start. To find the 5' end (read coords) of
    the junction for a reverse read, pass in the reversed cigar tuple"""
    for i, (op, count) in enumerate(cigar):
        if op == 'S':
            return i
    return None

def RunOnce(self):
    """Import the plugins once only."""
    if self.plugins_loaded:
      return
    self.plugins_loaded = True
    for plugin in self.plugins:
      plugin.Load()

def num_feats(self):
        """ The number of features per time step in the corpus. """
        if not self._num_feats:
            filename = self.get_train_fns()[0][0]
            feats = np.load(filename)
            # pylint: disable=maybe-no-member
            if len(feats.shape) == 3:
                # Then there are multiple channels of multiple feats
                self._num_feats = feats.shape[1] * feats.shape[2]
            elif len(feats.shape) == 2:
                # Otherwise it is just of shape time x feats
                self._num_feats = feats.shape[1]
            else:
                raise ValueError(
                    "Feature matrix of shape %s unexpected" % str(feats.shape))
        return self._num_feats

def num_feats(self):
        """ The number of features per time step in the corpus. """
        return self.num_feats

def dynamic_shape(self, max_elements):
        """Determine the dynamic shape, given incoming data that is big enough
        to hold `max_elements` elements.
        """
        known = 1
        unknown_pos = -1
        for i, x in enumerate(self.shape):
            if x is not None:
                known *= x
            else:
                assert unknown_pos == -1, 'Shape has multiple unknown dimensions'
                unknown_pos = i
        if unknown_pos == -1:
            return self.shape
        else:
            shape = list(self.shape)
            if known == 0:
                shape[unknown_pos] = 0
            else:
                shape[unknown_pos] = max_elements // known
            return shape

def sendall(self, data, **kws):
        """Send data to the socket. The socket must be connected to a remote
        socket. All the data is guaranteed to be sent."""
        return SendAll(self, data, timeout=self._timeout, **kws)

def sendall(self, data, **kws):
        """Send data to the socket. The socket must be connected to a remote
        socket. All the data is guaranteed to be sent."""
        while data:
            n = self.send(data, **kws)
            data = data[n:]

def strip_linebreaks(s):
    """ Strip excess line breaks from a string """
    return u"\n".join([c for c in s.split(u'\n') if c])

def hex_to_rgb(self, h):
        """Converts a valid hex color string to an RGB array."""
        h = h.lstrip('#')
        return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))

def get(self, indexes, as_list=False):
        """
        Given indexes will return a sub-set of the Series. This method will direct to the specific methods
        based on what types are passed in for the indexes. The type of the return is determined by the
        types of the parameters.

        :param indexes: index value, list of index values, or a list of booleans.
        :param as_list: if True then return the values as a list, if False return a Series.
        :return: either Series, list, or single value. The return is a shallow copy
        """
        if isinstance(indexes, (list, blist)):
            return self.get_rows(indexes, as_list)
        else:
            return self.get_cell(indexes)

def get(self, indexes, as_list=False):
        """
        Given indexes will return a sub-set of the Series. This method will direct to the specific methods
        based on what types are passed in for the indexes. The type of the return is determined by the
        types of the parameters.

        :param indexes: index value, list of index values, or a list of booleans.
        :param as_list: if True then return the values as a list, if False return a Series.
        :return: either Series, list, or single value. The return is a shallow copy
        """
        if isinstance(indexes, (list, tuple)):
            return self._get_list(indexes, as_list)
        elif isinstance(indexes, bool):
            return self._get_bool(indexes, as_list)
        else:
            return self._get_index(indexes, as_list)

def reopen(self, file_obj):
        """Reopen the file-like object in a safe manner."""
        file_obj.open('U')
        if sys.version_info[0] <= 2:
            return file_obj
        else:
            return codecs.getreader('utf-8')(file_obj)

def reopen(self, file_obj):
        """Reopen the file-like object in a safe manner."""
        try:
            file_obj.seek(0)
        except IOError:
            pass

def family_coff(self):
        """Return the family_coff attribute of the BFD file being processed."""
        if not self._ptr:
            raise BfdException("BFD not initialized")

        return _bfd.get_bfd_attribute(self._ptr, BfdAttributes.FAMILY_COFF)

def family_coff(self):
        """Return the family_coff attribute of the BFD file being processed."""
        return self.family_coff

def map(self, mapper: Callable[[Any], Any]) -> 'Observable':
        r"""Map a function over an observable.

        Haskell: fmap f m = Cont $ \c -> runCont m (c . f)
        """
        source = self
        return Observable(lambda on_next: source.subscribe(compose(on_next, mapper)))

def map(self, mapper: Callable[[Any], Any]) -> 'Observable':
        r"""Map a function over an observable.

        Haskell: fmap f m = Cont $ \c -> runCont m (c . f)
        """
        return Observable(self.scheduler, self.source.map(mapper))

def addClass(self, cn):
        """Add the specific class names to the class set and return ``self``.
        """
        if cn:
            if isinstance(cn, (tuple, list, set, frozenset)):
                add = self.addClass
                for c in cn:
                    add(c)
            else:
                classes = self._classes
                if classes is None:
                    self._extra['classes'] = classes = set()
                add = classes.add
                for cn in cn.split():
                    add(slugify(cn))
        return self

def warn_about_unmanaged_parameters(self):
        """used to raise warning if the user got parameter
        that we do not manage from now

        :return: None
        """
        properties = self.__class__.properties
        unmanaged = []
        for prop, entry in list(properties.items()):
            if not entry.managed and hasattr(self, prop):
                if entry.help:
                    line = "%s: %s" % (prop, entry.help)
                else:
                    line = prop
                unmanaged.append(line)
        if unmanaged:
            logger.warning("The following Nagios legacy parameter(s) are not currently "
                           "managed by Alignak:")

            for line in unmanaged:
                logger.warning('- %s', line)

            logger.warning("Those are unmanaged configuration statements, do you really need it? "
                           "Create an issue on the Alignak repository or submit a pull "
                           "request: http://www.github.com/Alignak-monitoring/alignak")

def warn_about_unmanaged_parameters(self):
        """used to raise warning if the user got parameter
        that we do not manage from now

        :return: None
        """
        for parameter in self.unmanaged_parameters:
            warnings.warn(
                "The parameter {} is not managed by the "
                "configuration manager".format(parameter)
            )

def pretty_description(description, wrap_at=None, indent=0):
    """
    Return a pretty formatted string given some text.

    Args:
        description (str): string to format.
        wrap_at (int): maximum length of a line.
        indent (int): level of indentation.

    Returns:
        str: pretty formatted string.
    """
    if wrap_at is None:
        wrap_at = 79

    lines = []
    for line in description.splitlines():
        line = line.strip()
        if len(line) > wrap_at:
            words = line.split()
            while len(words) > 1:
                if len(words[0]) + 1 + len(words[1]) > wrap_at:
                    lines.append(' '.join(words[:1]))
                    words = words[1:]
                else:
                    words[0:2] = [' '.join(words[:2])]
        else:
            lines.append(line)

    return '\n'.join(''* indent + line for line in lines)

def house(self):
        """ Returns the object's house. """
        return self.house

def _tree_line(self, no_type: bool = False) -> str:
        """Return the receiver's contribution to tree diagram."""
        return self._tree_line_prefix() + " " + self.iname()

def _tree_line(self, no_type: bool = False) -> str:
        """Return the receiver's contribution to tree diagram."""
        if self.is_leaf:
            return self.name
        if no_type:
            return f"{self.name}({self.type})"
        return f"{self.name}({self.type}): {self.value}"

def _member_def(self, member):
        """
        Return an individual member definition formatted as an RST glossary
        entry, wrapped to fit within 78 columns.
        """
        return '\n'.join(textwrap.wrap(member.definition, 78))

def resolve_name(name, module=None):
    """Resolve a dotted name to a module and its parts. This is stolen
    wholesale from unittest.TestLoader.loadTestByName.
    """
    parts = name.split('.')
    parts_copy = parts[:]
    if module is None:
        while parts_copy:  # pragma: no cover
            try:
                module = __import__('.'.join(parts_copy))
                break
            except ImportError:
                del parts_copy[-1]
                if not parts_copy:
                    raise
        parts = parts[1:]
    obj = module
    for part in parts:
        obj = getattr(obj, part)
    return obj

def resolve_name(name, module=None):
    """Resolve a dotted name to a module and its parts. This is stolen
    wholesale from unittest.TestLoader.loadTestByName.
    """
    if module is None:
        module = sys.modules[__name__]
    parts = name.split('.')
    for part in parts:
        try:
            module = getattr(module, part)
        except AttributeError:
            raise ImportError(name)
    return module, parts[-1]

def export(self, outFormat="shp", outFolder=None):
        """exports a dataset t"""
        if outFolder is None:
            outFolder = self.folder
        if outFormat == "shp":
            self.to_shapefile(outFolder)
        elif outFormat == "csv":
            self.to_csv(outFolder)
        elif outFormat == "json":
            self.to_json(outFolder)
        else:
            raise ValueError("Unknown output format")

def unique_list(lst):
    """Make a list unique, retaining order of initial appearance."""
    uniq = []
    for item in lst:
        if item not in uniq:
            uniq.append(item)
    return uniq

def reverse_collections(self, key, value):
    """Reverse colections field to custom MARC tag 980."""
    return {
        'a': value.get('primary'),
        'b': value.get('secondary'),
        'c': value.get('deleted'),
    }

def reverse_collections(self, key, value):
    """Reverse colections field to custom MARC tag 980."""
    if key == 'collections':
      if value:
        for collection in value:
          if collection['name']:
            self.marc_record.append(MARCField(980, 'a', collection['name']))

def is_vert_aligned_right(c):
    """Return true if all components vertically aligned on their right border.

    Vertical alignment means that the bounding boxes of each Mention of c
    shares a similar x-axis value in the visual rendering of the document. In
    this function the similarity of the x-axis value is based on the right
    border of their bounding boxes.

    :param c: The candidate to evaluate
    :rtype: boolean
    """
    return all(
        [
            _to_span(c[i]).sentence.is_visual()
            and bbox_vert_aligned_right(
                bbox_from_span(_to_span(c[i])), bbox_from_span(_to_span(c[0]))
            )
            for i in range(len(c))
        ]
    )

def minimum(self, value):
        """
        Set the value of the ``<c:min>`` child element to the float *value*,
        or remove the min element if *value* is |None|.
        """
        if value is None:
            self.remove_child(self.min)
        else:
            self.min.text = str(value)

def retreive_sigma_mu_data(self):
        """
        For the general form of the GMPE this retrieves the sigma mu
        values from the hdf5 file using the "general" model, i.e. sigma mu
        factors that are independent of the choice of region or depth
        """
        sigma_mu_data = {}
        for key in self.sigma_mu_data.keys():
            sigma_mu_data[key] = self.sigma_mu_data[key]["general"]
        return sigma_mu_data

def calculate_intervals(chunk_sizes):
        """Calculate intervals for a given chunk sizes.

        :param list chunk_sizes: List of chunk sizes.
        :return: Tuple of intervals.
        :rtype: :py:class:`tuple`
        """
        intervals = []
        for i in range(len(chunk_sizes) - 1):
            intervals.append(chunk_sizes[i] + chunk_sizes[i + 1])
        return tuple(intervals)

def noise_uniform(self, lower_bound, upper_bound):
        """Create a uniform noise variable"""
        assert upper_bound > lower_bound
        nu = self.sym.sym('nu_{:d}'.format(len(self.scope['nu'])))
        self.scope['nu'].append(nu)
        return lower_bound + nu*(upper_bound - lower_bound)

def noise_uniform(self, lower_bound, upper_bound):
        """Create a uniform noise variable"""
        return tf.random_uniform(
            shape=self.shape,
            minval=lower_bound,
            maxval=upper_bound,
            dtype=tf.float32,
            seed=self.seed,
            name=self.name
        )

def gadget_app(_parser, cmd, args):  # pragma: no cover
    """
    Find ROP gadgets in an ELF binary.
    """

    parser = argparse.ArgumentParser(
        prog=_parser.prog,
        description=_parser.description,
    )
    parser.add_argument('file', help='ELF file to find gadgets in')
    parser.add_argument('gadget', help='the assembler source or reghex expression')
    parser.add_argument(
        '--reghex', '-r',
        dest='mode',
        action='store_const',
        const='reghex',
        help='use reghex expression (hex bytes interspaced with ? for wildcard)',
    )
    parser.add_argument(
        '--asm', '-a',
        dest='mode',
        action='store_const',
        const='asm',
        help='use assembler expression (separate lines with semi-colon)',
    )
    parser.add_argument(
        '--all', '-l',
        dest='unique',
        action='store_const',
        const=False,
        default=True,
        help='also show non-unique gadgets',
    )
    args = parser.parse_args(args)

    if args.mode is None:
        try:
            pwnypack.util.reghex(args.gadget)
            args.mode = 'reghex'
        except SyntaxError:
            args.mode = 'asm'

    elf = pwnypack.elf.ELF(args.file)

    if args.mode == 'reghex':
        try:
            gadget = pwnypack.util.reghex(args.gadget)
        except SyntaxError:
            print('Invalid reghex pattern.')
            sys.exit(1)
    else:
        try:
            gadget = pwnypack.util.reghex('*'.join([
                pwnypack.codec.enhex(pwnypack.asm.asm(piece.replace(';', '\n'), target=elf))
                for piece in ';'.join([line.strip() for line in args.gadget.split(';')]).split('*')
            ]))
        except SyntaxError as e:
            print('Could not assemble:', e.msg)
            sys.exit(1)

    matches = find_gadget(
        elf,
        gadget,
        unique=args.unique
    )

    if not matches:
        print('No gadgets found.', file=sys.stdout)
        return

    longest_gadget = max(len(m['gadget']) for m in matches)
    fmt = '  0x%%0%dx: [ %%-%ds ] %%s' % (elf.bits / 4, longest_gadget * 3 - 1)

    current_section = None

    for match in matches:
        if match['section'].name != current_section:
            if current_section is not None:
                print()
            print('Section: %s' % match['section'].name)
            current_section = match['section'].name

        hex_gadget = pwnypack.codec.enhex(match['gadget'])
        print(fmt % (
            match['addr'],
            ' '.join(
                hex_gadget[i:i+2]
                for i in range(0, len(hex_gadget), 2)
            ),
            ' ; '.join(match['asm'])
        ))

    print()

