def get_frip(self, sample):
        """
        Calculates the fraction of reads in peaks for a given sample.

        :param pipelines.Sample sample: Sample object with "peaks" attribute.
        """
        if sample.peaks is None:
            return None
        else:
            return float(sample.peaks.count()) / sample.reads.count()

def dragEnterEvent( self, event ):
        """
        Processes the drag drop event using the filter set by the \
        setDragDropFilter

        :param      event | <QDragEvent>
        """
        if self.dragDropFilter is None:
            return

        if self.dragDropFilter.accept( event ):
            event.accept()
        else:
            event.ignore()

def _discretize_check(self, table, att, col):
        """
        Replaces the value with an appropriate interval symbol, if available.
        """
        label = "'%s'" % col
        if table in self.discr_intervals and att in self.discr_intervals[table]:
            intervals = self.discr_intervals[table][att]
            n_intervals = len(intervals)

            prev_value = None
            for i, value in enumerate(intervals):

                if i > 0:
                    prev_value = intervals[i - 1]

                if not prev_value and col <= value:
                    label = "'=<%.2f'" % value
                    break
                elif prev_value and col <= value:
                    label = "'(%.2f;%.2f]'" % (prev_value, value)
                    break
                elif col > value and i == n_intervals - 1:
                    label = "'>%.2f'" % value
                    break
        else:
            # For some reason using [ and ] crashes TreeLiker
            label = label.replace('[', 'I')
            label = label.replace(']', 'I')

        return label

def _discretize_check(self, table, att, col):
        """
        Replaces the value with an appropriate interval symbol, if available.
        """
        if table[att][col] in self.intervals:
            table[att][col] = self.intervals[table[att][col]]
        else:
            table[att][col] = self.unknown_symbol

def validate_marked_location(location):
    """Validate that a Location object is safe for marking, and not at a field."""
    if not isinstance(location, (Location, FoldScopeLocation)):
        raise TypeError(u'Expected Location or FoldScopeLocation location, got: {} {}'.format(
            type(location).__name__, location))

    if location.field is not None:
        raise GraphQLCompilationError(u'Cannot mark location at a field: {}'.format(location))

def validate_marked_location(location):
    """Validate that a Location object is safe for marking, and not at a field."""
    if location.is_field:
        raise ValidationError("Cannot mark a field location.")
    if location.is_marked:
        raise ValidationError("Location already marked.")

def ape(self, ape_path=None):
        """Open in ApE if `ApE` is in your command line path."""
        # TODO: simplify - make ApE look in PATH only
        cmd = 'ApE'
        if ape_path is None:
            # Check for ApE in PATH
            ape_executables = []
            for path in os.environ['PATH'].split(os.pathsep):
                exepath = os.path.join(path, cmd)
                ape_executables.append(os.access(exepath, os.X_OK))
            if not any(ape_executables):
                raise Exception('Ape not in PATH. Use ape_path kwarg.')
        else:
            cmd = ape_path
        # Check whether ApE exists in PATH
        tmp = tempfile.mkdtemp()
        if self.name is not None and self.name:
            filename = os.path.join(tmp, '{}.ape'.format(self.name))
        else:
            filename = os.path.join(tmp, 'tmp.ape')
        coral.seqio.write_dna(self, filename)
        process = subprocess.Popen([cmd, filename])
        # Block until window is closed
        try:
            process.wait()
            shutil.rmtree(tmp)
        except KeyboardInterrupt:
            shutil.rmtree(tmp)

def ape(self, ape_path=None):
        """Open in ApE if `ApE` is in your command line path."""
        if ape_path is None:
            ape_path = self.ape_path
        if ape_path is None:
            raise ValueError("No ApE path found. Please specify it.")
        if not os.path.exists(ape_path):
            raise ValueError("ApE path does not exist.")
        if not os.access(ape_path, os.X_OK):
            raise ValueError("ApE path is not executable.")
        subprocess.call([ape_path, self.path])

def connect(self):
        """Connect to the unix domain socket, which is passed to us as self.host

        This is in host because the format we use for the unix domain socket is:

        http+unix://%2Fpath%2Fto%2Fsocket.sock

        """
        try:
            self.sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)

            if has_timeout(self.timeout):
                self.sock.settimeout(self.timeout)

            self.sock.connect(unquote(self.host))
        except socket.error as msg:
            if self.sock:
                self.sock.close()
            self.sock = None

            raise socket.error(msg)

