def upload_files(self, container, src_dst_map, content_type=None):
        """Upload multiple files."""
        if not content_type:
            content_type = "application/octet.stream"
        url = self.make_url(container, None, None)
        headers = self._base_headers
        multi_files = []
        try:
            for src_path in src_dst_map:
                dst_name = src_dst_map[src_path]
                if not dst_name:
                    dst_name = os.path.basename(src_path)
                multi_files.append(
                    ('files', (dst_name, open(src_path, 'rb'), content_type)))

            rsp = requests.post(url, headers=headers, files=multi_files,
                                timeout=self._timeout)
        except requests.exceptions.ConnectionError as e:
            RestHttp._raise_conn_error(e)
        finally:
            for n, info in multi_files:
                dst, f, ctype = info
                f.close()

        return self._handle_response(rsp)

def upload_files(self, container, src_dst_map, content_type=None):
        """Upload multiple files."""
        for src, dst in src_dst_map.items():
            self.upload_file(container, src, dst, content_type)

def _get_value_from_json(self, dict_path, metrics_json):
        """
        Get a value from a dictionary under N keys, represented as str("key1.key2...key{n}")
        """
        for key in dict_path.split('.'):
            if key in metrics_json:
                metrics_json = metrics_json.get(key)
            else:
                return None
        return metrics_json

def _get_value_from_json(self, dict_path, metrics_json):
        """
        Get a value from a dictionary under N keys, represented as str("key1.key2...key{n}")
        """
        if not dict_path:
            return metrics_json
        keys = dict_path.split(".")
        value = metrics_json
        for key in keys:
            if key in value:
                value = value[key]
            else:
                return None
        return value

def splitport(host):
    """splitport('host:port') --> 'host', 'port'."""
    global _portprog
    if _portprog is None:
        import re
        _portprog = re.compile('^(.*):([0-9]+)$')

    match = _portprog.match(host)
    if match: return match.group(1, 2)
    return host, None

def _parse(self, parsable, parser_name):
        """
        Low-level parsing
        NB: this is the PRIVATE method
        @returns tilde_obj, error
        """
        calc, error = None, None
        try:
            for calc in self.Parsers[parser_name].iparse(parsable):
                yield calc, None
            return
        except RuntimeError as e:
            error = "routine %s parser error in %s: %s" % ( parser_name, parsable, e )
        except:
            exc_type, exc_value, exc_tb = sys.exc_info()
            error = "unexpected %s parser error in %s:\n %s" % ( parser_name, parsable, "".join(traceback.format_exception( exc_type, exc_value, exc_tb )) )
        yield None, error

def compute(self, rtdc_ds):
        """Compute the feature with self.method

        Parameters
        ----------
        rtdc_ds: instance of RTDCBase
            The dataset to compute the feature for

        Returns
        -------
        feature: array- or list-like
            The computed data feature (read-only).
        """
        if self.method =='mean':
            feature = rtdc_ds.mean(axis=0)
        elif self.method =='std':
            feature = rtdc_ds.std(axis=0)
        elif self.method =='max':
            feature = rtdc_ds.max(axis=0)
        elif self.method =='min':
            feature = rtdc_ds.min(axis=0)
        elif self.method =='median':
            feature = rtdc_ds.median(axis=0)
        elif self.method =='sum':
            feature = rtdc_ds.sum(axis=0)
        elif self.method == 'var':
            feature = rtdc_ds.var(axis=0)
        elif self.method =='skew':
            feature = rtdc_ds.skew(axis=0)
        elif self.method == 'kurtosis':
            feature = rtdc_ds.kurtosis(axis=0)
        elif self.method == 'quantile':
            feature = rtdc_ds.quantile(self.quantile, axis=0)
        elif self.method == 'iqr':
            feature = rtdc_ds.quantile(0.75, axis=0) - rtdc_ds.quantile(0.25, axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='sem':
            feature = rtdc_ds.sem(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds.mad(axis=0)
        elif self.method =='mad':
            feature = rtdc_ds

def execute(self, data_dict, callback, group=None, trace=None):
        """Low level method to expand the template piece by piece.

    Args:
      data_dict: The JSON data dictionary.
      callback: A callback which should be called with each expanded token.
      group: Dictionary of name -> Template instance (for styles)

    Example: You can pass 'f.write' as the callback to write directly to a file
    handle.
    """
        if trace:
            trace.write('Expanding template: %s\n' % self.template)
        if group is None:
            group = {}
        if self.template is None:
            callback(self.value)
        else:
            self.expand(data_dict, callback, group, trace)

def _parse_and_store_headers(self):
        """
        Coroutine used retrieve header data and parse each header until
        the body is found.
        """
        while True:
            line = yield self.stream.readline()
            if line == b'\r\n':
                break
            self.headers.append(line)

def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    backup_base = '/var/local/woven-backup'
    backup_path = ''.join([backup_base,path])
    if exists(backup_path):
        if delete_backup:
            sudo('mv -f %s %s'% (backup_path,path))
        else:
            sudo('cp -f %s %s'% (backup_path,path))

def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    if os.path.exists(path):
        if delete_backup:
            os.remove(path)
        else:
            os.rename(path, path + ".bak")
    else:
        raise FileNotFoundError("File does not exist: {}".format(path))

def compare_3PC_keys(key1, key2) -> int:
    """
    Return >0 if key2 is greater than key1, <0 if lesser, 0 otherwise
    """
    if key1[0] == key2[0]:
        return key2[1] - key1[1]
    else:
        return key2[0] - key1[0]

def compare_3PC_keys(key1, key2) -> int:
    """
    Return >0 if key2 is greater than key1, <0 if lesser, 0 otherwise
    """
    if key1.get_type()!= key2.get_type():
        return 1 if key1.get_type() == KeyType.PUBLIC else -1
    if key1.get_type() == KeyType.PUBLIC:
        return 1 if key1.get_type() == KeyType.PUBLIC else -1
    if key1.get_type() == KeyType.PRIVATE:
        return 1 if key1.get_type() == KeyType.PRIVATE else -1
    if key1.get_type() == KeyType.SECRET:
        return 1 if key1.get_type() == KeyType.SECRET else -1
    return 0

