def _convert_content(self, rdtype, content):
        """
        Converts type dependent record content into well formed and fully qualified
        content for domain zone and returns content.
        """
        if rdtype == 'TXT':
            if content[0] != '"':
                content = '"' + content
            if content[-1] != '"':
                content += '"'
        if rdtype in ('CNAME', 'MX', 'NS', 'SRV'):
            if content[-1] != '.':
                content = self._fqdn_name(content)
        return content

def _convert_content(self, rdtype, content):
        """
        Converts type dependent record content into well formed and fully qualified
        content for domain zone and returns content.
        """
        if rdtype == 'A':
            return content
        elif rdtype == 'AAAA':
            return content
        elif rdtype == 'CNAME':
            return content
        elif rdtype == 'MX':
            return content
        elif rdtype == 'NS':
            return content
        elif rdtype == 'PTR':
            return content
        elif rdtype == 'SOA':
            return content
        elif rdtype == 'SRV':
            return content
        elif rdtype == 'TXT':
            return content
        else:
            return content

