def _AnalyzeKeywords(self, keywords):
    """Extracts a start time from a list of keywords if present."""
    start_time = rdfvalue.RDFDatetime.Now() - rdfvalue.Duration("180d")
    filtered_keywords = []

    for k in keywords:
      if k.startswith(self.START_TIME_PREFIX):
        try:
          start_time = rdfvalue.RDFDatetime.FromHumanReadable(
              k[self.START_TIME_PREFIX_LEN:])
        except ValueError:
          pass
      else:
        filtered_keywords.append(k)

    if not filtered_keywords:
      filtered_keywords.append(".")

    return start_time, filtered_keywords

def _AnalyzeKeywords(self, keywords):
    """Extracts a start time from a list of keywords if present."""
    start_time = None
    for keyword in keywords:
      if keyword.startswith('start_time='):
        start_time = keyword[len('start_time='):]
        break
    return start_time

def select_edges(docgraph, conditions, data):
    """yields all edges that meet the conditions given as eval strings"""
    for (src_id, target_id, edge_attribs) in docgraph.edges(data=True):
        # if all conditions are fulfilled
        # we need to add edge_attribs to the namespace eval is working in
        if all((eval(cond, {'edge_attribs': edge_attribs})
                for cond in conditions)):
            if data:
                yield (src_id, target_id, edge_attribs)
            else:
                yield (src_id, target_id)

def select_edges(docgraph, conditions, data):
    """yields all edges that meet the conditions given as eval strings"""
    for edge in docgraph.edges(data=True):
        if eval(conditions, data):
            yield edge

def _import_all_troposphere_modules(self):
        """ Imports all troposphere modules and returns them """
        dirname = os.path.join(os.path.dirname(__file__))
        module_names = [
            pkg_name
            for importer, pkg_name, is_pkg in
            pkgutil.walk_packages([dirname], prefix="troposphere.")
            if not is_pkg and pkg_name not in self.EXCLUDE_MODULES]
        module_names.append('troposphere')

        modules = []
        for name in module_names:
            modules.append(importlib.import_module(name))

        def members_predicate(m):
            return inspect.isclass(m) and not inspect.isbuiltin(m)

        members = []
        for module in modules:
            members.extend((m[1] for m in inspect.getmembers(
                module, members_predicate)))

        return set(members)

def _import_all_troposphere_modules(self):
        """ Imports all troposphere modules and returns them """
        modules = []
        for name, obj in inspect.getmembers(troposphere):
            if inspect.ismodule(obj):
                modules.append(obj)
        return modules

