def match(elem, seq_expr):
        """
        Return True if elem (an element of elem_list) matches seq_expr, an element in self.sequence
        """
        if type(seq_expr) is str:  # wild-card
            if seq_expr == '.':  # match any element
                return True
            elif seq_expr == '\d':
                return elem.is_numerical()
            elif seq_expr == '\D':
                return not elem.is_numerical()
            else:  # invalid wild-card specified
                raise LookupError('{0} is not a valid wild-card'.format(seq_expr))
        else:  # date element
            return elem == seq_expr

def match(elem, seq_expr):
        """
        Return True if elem (an element of elem_list) matches seq_expr, an element in self.sequence
        """
        if isinstance(seq_expr, list):
            return elem == seq_expr
        elif isinstance(seq_expr, tuple):
            return elem == seq_expr
        elif isinstance(seq_expr, str):
            return elem == seq_expr
        else:
            raise ValueError("seq_expr must be a list, tuple, or string")

def service_name_from_scope_name(scope_name):
    """Translate scope name to service name which can be used in dns.

    230 = 253 - len('replica.') - len('.service.consul')
    """

    def replace_char(match):
        c = match.group(0)
        return '-' if c in '. _' else "u{:04d}".format(ord(c))

    service_name = re.sub(r'[^a-z0-9\-]', replace_char, scope_name.lower())
    return service_name[0:230]

def add_cohp_dict(self, cohp_dict, key_sort_func=None):
        """
        Adds a dictionary of COHPs with an optional sorting function
        for the keys.

        Args:
            cohp_dict: dict of the form {label: Cohp}

            key_sort_func: function used to sort the cohp_dict keys.
        """
        if key_sort_func:
            keys = sorted(cohp_dict.keys(), key=key_sort_func)
        else:
            keys = cohp_dict.keys()
        for label in keys:
            self.add_cohp(label, cohp_dict[label])

def add_cohp_dict(self, cohp_dict, key_sort_func=None):
        """
        Adds a dictionary of COHPs with an optional sorting function
        for the keys.

        Args:
            cohp_dict: dict of the form {label: Cohp}

            key_sort_func: function used to sort the cohp_dict keys.
        """
        for key, cohp in cohp_dict.items():
            self.add_cohp(cohp, key)

        if key_sort_func is not None:
            self.cohp_dict = OrderedDict(
                sorted(self.cohp_dict.items(), key=key_sort_func)
            )

def apply(self, events):
        """
        EventManager.apply(events) -> Takes an object with methods, and applies
        them to EventManager.
        Example:
            class TestEvents(object):
                @staticmethod
                def test_method():
                    pass

            e = TestEvents()
            em = EventManager()
            em.apply(e)
            # em now has an event called test_method,
            # and e.test_method as handler."""
        for method in dir(events):
            if method.startswith('on_'):
                self.register(method[3:], events.__getattribute__(method))

def main():
    """
    NAME
        plot_magic_keys.py

    DESCRIPTION
        picks out keys and makes and xy plot

    SYNTAX
        plot_magic_keys.py [command line options]

    OPTIONS
        -h prints help message and quits
        -f FILE: specify input magic format file
        -xkey KEY: specify key for X
        -ykey KEY: specify key  for Y
        -b xmin xmax ymin ymax, sets bounds

    """
    dir_path="./"
    if '-WD' in sys.argv:
        ind=sys.argv.index('-WD')
        dir_path=sys.argv[ind+1]
    if '-h' in sys.argv:
        print(main.__doc__)
        sys.exit()
    if '-f' in sys.argv:
        ind=sys.argv.index('-f')
        magic_file=dir_path+'/'+sys.argv[ind+1]
    else:
        print(main.__doc__)
        sys.exit()
    if '-xkey' in sys.argv:
        ind=sys.argv.index('-xkey')
        xkey=sys.argv[ind+1]
        if '-ykey' in sys.argv:
            ind=sys.argv.index('-ykey')
            ykey=sys.argv[ind+1]
    else:
        print(main.__doc__)
        sys.exit()
    if '-b' in sys.argv:
        ind=sys.argv.index('-b')
        xmin=float(sys.argv[ind+1])
        xmax=float(sys.argv[ind+2])
        ymin=float(sys.argv[ind+3])
        ymax=float(sys.argv[ind+4])
    #
    #
    # get data read in
    X,Y=[],[]
    Data,file_type=pmag.magic_read(magic_file)
    if len(Data)>0:
        for rec in Data:
            if xkey in list(rec.keys()) and rec[xkey]!="" and ykey in list(rec.keys()) and rec[ykey]!="":
                try:
                    X.append(float(rec[xkey]))
                    Y.append(float(rec[ykey]))
                except:
                    pass
        FIG={'fig':1}
        pmagplotlib.plot_init(FIG['fig'],5,5)
        if '-b' in sys.argv:
            pmagplotlib.plot_xy(FIG['fig'],X,Y,sym='ro',xlab=xkey,ylab=ykey,xmin=xmin, xmax=xmax, ymin=ymin, ymax=ymax )
        else:
            pmagplotlib.plot_xy(FIG['fig'],X,Y,sym='ro',xlab=xkey,ylab=ykey)
        pmagplotlib.draw_figs(FIG)
        ans=input(" S[a]ve to save plot, [q]uit, Return to continue:  ")
        if ans=="q": sys.exit()
        if ans=="a":
            files = {}
            for key in list(FIG.keys()):
                files[key]=str(key) + ".svg"
                pmagplotlib.save_plots(FIG,files)
        sys.exit()
    else:
        print('no data to plot')

def get_center_of_mass(self):
        """
        Get a tuple (x,y) that is the center of mass. The center of mass is not
        necessarily the same as the center of the bounding box. Imagine a black
        square and a single dot wide outside of the square.
        """
        xsum, ysum, counter = 0., 0., 0
        for stroke in self.get_pointlist():
            for point in stroke:
                xsum += point['x']
                ysum += point['y']
                counter += 1
        return (xsum / counter, ysum / counter)

def invoke(self, ctx):
        """Inject overflow arguments into context state.

        :param click.core.Context ctx: Click context.

        :return: super() return value.
        """
        if self.overflow:
            ctx.ensure_object(Config).update(dict(overflow=self.overflow))
        return super(ClickGroup, self).invoke(ctx)

def invoke(self, ctx):
        """Inject overflow arguments into context state.

        :param click.core.Context ctx: Click context.

        :return: super() return value.
        """
        if self.overflow_args is None:
            return super().invoke(ctx)

        overflow_args = self.overflow_args(ctx)
        if overflow_args is None:
            return super().invoke(ctx)

        if not isinstance(overflow_args, list):
            overflow_args = [overflow_args]

        ctx.args.extend(overflow_args)
        return super().invoke(ctx)

def show_management_certificate(kwargs=None, conn=None, call=None):
    """
    .. versionadded:: 2015.8.0

    Return information about a management_certificate

    CLI Example:

    .. code-block:: bash

        salt-cloud -f get_management_certificate my-azure name=my_management_certificate \\
            thumbalgorithm=sha1 thumbprint=0123456789ABCDEF
    """
    if call != 'function':
        raise SaltCloudSystemExit(
            'The get_management_certificate function must be called with -f or --function.'
        )

    if not conn:
        conn = get_conn()

    if kwargs is None:
        kwargs = {}

    if 'thumbprint' not in kwargs:
        raise SaltCloudSystemExit('A thumbprint must be specified as "thumbprint"')

    data = conn.get_management_certificate(kwargs['thumbprint'])
    return object_to_dict(data)

def show_management_certificate(kwargs=None, conn=None, call=None):
    """
    .. versionadded:: 2015.8.0

    Return information about a management_certificate

    CLI Example:

    .. code-block:: bash

        salt-cloud -f get_management_certificate my-azure name=my_management_certificate \\
            thumbalgorithm=sha1 thumbprint=0123456789ABCDEF
    """
    if kwargs is None:
        kwargs = {}
    if conn is None:
        conn = _get_conn(kwargs)
    if call is None:
        call = _get_call(kwargs)
    if call == "action":
        return {"management_certificate": _get_management_certificate(
            kwargs=kwargs, conn=conn, call=call
        )}
    return _get_management_certificate(kwargs=kwargs, conn=conn, call=call)

def packb(obj, **kwargs):
    """wrap msgpack.packb, setting use_bin_type=True by default"""
    kwargs.setdefault('use_bin_type', True)
    return msgpack.packb(obj, **kwargs)

def packb(obj, **kwargs):
    """wrap msgpack.packb, setting use_bin_type=True by default"""
    return packb(obj, use_bin_type=True, **kwargs)

def offset_overlays(self, text, run_matchers=None, **kw):
        """
        First all matchers will run and then I will try to combine
        them. Use run_matchers to force running(True) or not
        running(False) the matchers.

        See ListMatcher for arguments.
        """
        if run_matchers is None:
            run_matchers = self.run_matchers
        if run_matchers:
            self.run_matchers(text, **kw)
        return self.combine_overlays(text, **kw)

def get_health(self):
        """Summarize health of managed system

        This provides a summary of the health of the managed system.
        It additionally provides an iterable list of reasons for
        warning, critical, or failed assessments.
        """
        summary = {'badreadings': [], 'health': const.Health.Ok}
        fallbackreadings = []
        try:
            self.oem_init()
            fallbackreadings = self._oem.get_health(summary)
            for reading in self.get_sensor_data():
                if reading.health != const.Health.Ok:
                    summary['health'] |= reading.health
                    summary['badreadings'].append(reading)
        except exc.BypassGenericBehavior:
            pass
        if not summary['badreadings']:
            summary['badreadings'] = fallbackreadings
        return summary

def handle_api_exceptions_inter(self, method, *url_parts, **kwargs):
        """The main (middle) part - it is enough if no error occurs."""
        try:
            return self.handle_api_exceptions_inter_no_error(method, *url_parts, **kwargs)
        except Exception as e:
            self.handle_api_exceptions_inter_error(method, *url_parts, **kwargs, error=e)

def prompt(msg, default=NO_DEFAULT, validate=None):
    """ Prompt user for input """
    while True:
        response = input(msg + " ").strip()
        if not response:
            if default is NO_DEFAULT:
                continue
            return default
        if validate is None or validate(response):
            return response

def prompt(msg, default=NO_DEFAULT, validate=None):
    """ Prompt user for input """
    if default is NO_DEFAULT:
        prompt = '%s:'% msg
    else:
        prompt = '%s [%s]:'% (msg, default)
    while True:
        try:
            return getpass.getpass(prompt)
        except KeyboardInterrupt:
            print()
            sys.exit(1)
        except EOFError:
            print()
            sys.exit(1)
        except Exception as e:
            print(e)
            print()
            continue
        if validate is not None and not validate(ans):
            print('Invalid input')
            print()
            continue
        break

def skip_whitespace(self):
        """Consume input until a non-whitespace character is encountered.

        The non-whitespace character is then ungotten, and the number of
        whitespace characters consumed is returned.

        If the tokenizer is in multiline mode, then newlines are whitespace.

        @rtype: int
        """

        skipped = 0
        while True:
            c = self._get_char()
            if c != ' ' and c != '\t':
                if (c != '\n') or not self.multiline:
                    self._unget_char(c)
                    return skipped
            skipped += 1

def skip_whitespace(self):
        """Consume input until a non-whitespace character is encountered.

        The non-whitespace character is then ungotten, and the number of
        whitespace characters consumed is returned.

        If the tokenizer is in multiline mode, then newlines are whitespace.

        @rtype: int
        """
        if self.multiline:
            return self.skip_whitespace_multiline()
        else:
            return self.skip_whitespace_singleline()

def serialize_on_parent(
            self,
            parent,  # type: ET.Element
            value,  # type: Any
            state  # type: _ProcessorState
    ):
        # type: (...) -> None
        """Serialize the value and adds it to the parent."""
        if value is None:
            return
        if isinstance(value, list):
            for item in value:
                self.serialize_on_parent(parent, item, state)
        else:
            self.serialize_on_parent(parent, value, state)

def split_cmdline(cmdline):
    """Return path, cmd and arguments for a process cmdline."""
    cmdline = cmdline.strip()
    if not cmdline:
        return None, None, None
    if cmdline[0] == '"':
        cmdline = cmdline[1:-1]
    path, cmd = cmdline.split(None, 1)
    args = shlex.split(cmd)
    return path, cmd, args

def annotate_from_changeset(self, changeset):
        """
        Returns full html line for single changeset per annotated line.
        """
        if self.annotate_from_changeset_func:
            return self.annotate_from_changeset_func(changeset)
        else:
            return ''.join((changeset.id, '\n'))

