def _create_scheduled_actions(conn, as_name, scheduled_actions):
    """
    Helper function to create scheduled actions
    """
    if scheduled_actions:
        for name, action in six.iteritems(scheduled_actions):
            if 'start_time' in action and isinstance(action['start_time'], six.string_types):
                action['start_time'] = datetime.datetime.strptime(
                    action['start_time'], DATE_FORMAT
                )
            if 'end_time' in action and isinstance(action['end_time'], six.string_types):
                action['end_time'] = datetime.datetime.strptime(
                    action['end_time'], DATE_FORMAT
                )
            conn.create_scheduled_group_action(as_name, name,
                desired_capacity=action.get('desired_capacity'),
                min_size=action.get('min_size'),
                max_size=action.get('max_size'),
                start_time=action.get('start_time'),
                end_time=action.get('end_time'),
                recurrence=action.get('recurrence')
            )

def _cmp(self, other):
        """
        Comparator function for two :class:`~pywbem.CIMQualifier` objects.

        The comparison is based on their public attributes, in descending
        precedence:

        * `name`
        * `type`
        * `value`
        * `propagated`
        * `overridable`
        * `tosubclass`
        * `toinstance`
        * `translatable`

        The comparison takes into account any case insensitivities described
        for these attributes.
        """
        if self.name!= other.name:
            return cmp(self.name, other.name)
        if self.type!= other.type:
            return cmp(self.type, other.type)
        if self.value!= other.value:
            return cmp(self.value, other.value)
        if self.propagated!= other.propagated:
            return cmp(self.propagated, other.propagated)
        if self.overridable!= other.overridable:
            return cmp(self.overridable, other.overridable)
        if self.tosubclass!= other.tosubclass:
            return cmp(self.tosubclass, other.tosubclass)
        if self.toinstance!= other.toinstance:
            return cmp(self.toinstance, other.toinstance)
        if self.translatable!= other.translatable:
            return cmp(self.translatable, other.translatable)
        return 0

def reset_tip_tracking(self):
        """
        Resets the :any:`Pipette` tip tracking, "refilling" the tip racks
        """
        self.current_tip(None)
        self.tip_rack_iter = iter([])

        if self.has_tip_rack():
            iterables = self.tip_racks

            if self.channels > 1:
                iterables = [c for rack in self.tip_racks for c in rack.cols]
            else:
                iterables = [w for rack in self.tip_racks for w in rack]

            if self.starting_tip:
                iterables = iterables[iterables.index(self.starting_tip):]

            self.tip_rack_iter = itertools.chain(iterables)

def ids2marc(self, key, value):
    """Populate the ``035`` MARC field.

    Also populates the ``8564`` and ``970`` MARC field through side effects.
    """
    def _is_schema_inspire_bai(id_, schema):
        return schema == 'INSPIRE BAI'

    def _is_schema_inspire_id(id_, schema):
        return schema == 'INSPIRE ID'

    def _is_schema_spires(id_, schema):
        return schema == 'SPIRES'

    def _is_schema_linkedin(id, schema):
        return schema == 'LINKEDIN'

    def _is_schema_twitter(id, schema):
        return schema == 'TWITTER'

    id_ = value.get('value')
    schema = value.get('schema')

    if _is_schema_spires(id_, schema):
        self.setdefault('970', []).append({'a': id_})
    elif _is_schema_linkedin(id_, schema):
        self.setdefault('8564', []).append(
            {
                'u': u'https://www.linkedin.com/in/{id}'.format(id=quote_url(id_)),
                'y': 'LINKEDIN',
            }
        )
    elif _is_schema_twitter(id_, schema):
        self.setdefault('8564', []).append(
            {
                'u': u'https://twitter.com/{id}'.format(id=id_),
                'y': 'TWITTER',
            }
        )
    elif _is_schema_inspire_id(id_, schema):
        return {
            'a': id_,
            '9': 'INSPIRE',
        }
    elif _is_schema_inspire_bai(id_, schema):
        return {
            'a': id_,
            '9': 'BAI',
        }
    else:
        return {
            'a': id_,
            '9': schema,
        }

def keep_everything_scorer(checked_ids):
    """Returns every query and every match in checked_ids, with best score."""
    result = checked_ids.keys()
    for i in checked_ids.values():
        result.extend(i.keys())
    return dict.fromkeys(result).keys()

def keep_everything_scorer(checked_ids):
    """Returns every query and every match in checked_ids, with best score."""
    return [
        (q, m, score)
        for q, m, score in checked_ids
        if score == max(score for _, _, score in checked_ids)
    ]

def numbered_syllable_to_accented(syllable):
    """Convert a numbered pinyin syllable to an accented pinyin syllable.

    Implements the following algorithm, modified from https://github.com/tsroten/zhon:
        1. If the syllable has an 'a' or 'e', put the tone over that vowel.
        2. If the syllable has 'ou', place the tone over the 'o'.
        3. Otherwise, put the tone on the last vowel.

    """
    def keep_case_replace(s, vowel, replacement):
        accented = s.replace(vowel, replacement)
        if syllable[0].isupper():
            return accented[0].upper() + accented[1:]
        return accented

    tone = syllable[-1]
    if tone == '5':
        return re.sub('u:|v', '\u00fc', syllable[:-1])
    # Homogenise representation of u:
    syl = re.sub('u:|v', '\u00fc', syllable[:-1].lower())
    if 'a' in syl:
        return keep_case_replace(syl, 'a', _num_vowel_to_acc('a', tone))
    elif 'e' in syl:
        return keep_case_replace(syl, 'e', _num_vowel_to_acc('e', tone))
    elif 'ou' in syl:
        return keep_case_replace(syl, 'o', _num_vowel_to_acc('o', tone))
    last_vowel = syl[max(map(syl.rfind, VOWELS))]  # Find last vowel index.
    return keep_case_replace(syl, last_vowel, _num_vowel_to_acc(last_vowel, tone))

def bitop(self, operation, dest, *keys):
        """
        Perform a bitwise operation using ``operation`` between ``keys`` and
        store the result in ``dest``.
        """
        return self.execute_command('BITOP', operation, dest, *keys)

def bitop(self, operation, dest, *keys):
        """
        Perform a bitwise operation using ``operation`` between ``keys`` and
        store the result in ``dest``.
        """
        if operation not in self.bitops:
            raise RedisError("Unknown bit operation: %s" % operation)
        return self.execute_command(self.bitops[operation], dest, *keys)

def parse_bytes(self, bytestr, isfinal=True):
        """
        Parse a byte string. If the string is very large, split it in chuncks
        and parse each chunk with isfinal=False, then parse an empty chunk
        with isfinal=True.
        """
        if len(bytestr) > 1000000:
            for i in range(0, len(bytestr), 1000000):
                self.parse_bytes(bytestr[i:i+1000000], False)
            self.parse_bytes(b'', True)
        else:
            self.parse_bytes_fast(bytestr, isfinal)

def _process_param_value(self, value):
        """
        Returns a UTF-8 string representation of the parameter value,
        recursing into lists.
        """
        # Extract IDs from objects
        if isinstance(value, TroveboxObject):
            return str(value.id).encode('utf-8')

        # Ensure strings are UTF-8 encoded
        elif isinstance(value, TEXT_TYPE):
            return value.encode("utf-8")

        # Handle lists
        elif isinstance(value, list):
            # Make a copy of the list, to avoid overwriting the original
            new_list = list(value)
            # Process each item in the list
            for i, item in enumerate(new_list):
                new_list[i] = self._process_param_value(item)
            # new_list elements are UTF-8 encoded strings - simply join up
            return b','.join(new_list)

        # Handle booleans
        elif isinstance(value, bool):
            return b"1" if value else b"0"

        # Unknown - just do our best
        else:
            return str(value).encode("utf-8")

def _process_param_value(self, value):
        """
        Returns a UTF-8 string representation of the parameter value,
        recursing into lists.
        """
        if isinstance(value, list):
            return [self._process_param_value(v) for v in value]
        elif isinstance(value, dict):
            return {k: self._process_param_value(v) for k, v in value.items()}
        else:
            return value.encode('utf-8')

def light_curve(self, t, texp=0.0, tol=1e-8, maxdepth=4, use_batman=False):
        """
        Get the light curve evaluated at a list of times using the current
        model.

        :param t:
            The times where the light curve should be evaluated (in days).

        :param tol:
            The stopping criterion for the exposure time integration.

        :param maxdepth:
            The maximum recursion depth of the exposure time integrator.

        """
        if use_batman:
            return self.batman_light_curve(t, texp, tol, maxdepth)
        else:
            return self.exposure_time_integrator(t, texp, tol, maxdepth)

