def _attr_func_(self, slots):
        """
        Does not work as expected, makes an empty object with a new __slots__
        definition.
        """

        self.__attr_func = type(
            ''.join([type(self).__name__, 'Funcs']),
            (),
            {
                '__module__': type(self).__module__,
                '__slots__': tuple(set(slots))
            }
        )()

def _attr_func_(self, slots):
        """
        Does not work as expected, makes an empty object with a new __slots__
        definition.
        """
        return type(self.__class__.__name__, (self.__class__,), slots)

def rate_overall(self):
        """Returns the overall average rate based on the start time."""
        if self.start_time:
            return self.rate_per_second * (time.time() - self.start_time)
        else:
            return 0

def vectors(self, direction="all", failed=False):
        """Get vectors that connect at this node.

        Direction can be "incoming", "outgoing" or "all" (default).
        Failed can be True, False or all
        """
        if direction == "all":
            return self.incoming + self.outgoing
        elif direction == "incoming":
            return self.incoming
        elif direction == "outgoing":
            return self.outgoing
        else:
            raise ValueError("Direction must be 'all', 'incoming' or 'outgoing'")

def d2ASbr_dV2(dSbr_dVa, dSbr_dVm, Sbr, Cbr, Ybr, V, lam):
    """ Computes 2nd derivatives of |complex power flow|**2 w.r.t. V.
    """
    return 2 * (dSbr_dVa * dSbr_dVm - Sbr * (d2Sbr_dVa2(dSbr_dVa, dSbr_dVm, Sbr, Cbr, Ybr, V, lam) + d2Sbr_dVm2(dSbr_dVa, dSbr_dVm, Sbr, Cbr, Ybr, V, lam)))

