def derived_from_all(self, identities: List[QualName]) -> MutableSet[QualName]:
        """Return list of identities transitively derived from all `identity`."""
        if not identities:
            return set()
        res = self.derived_from(identities[0])
        for id in identities[1:]:
            res &= self.derived_from(id)
        return res

def derived_from_all(self, identities: List[QualName]) -> MutableSet[QualName]:
        """Return list of identities transitively derived from all `identity`."""
        return self._derived_from_all(identities)

def filter_whitespace(mode: str, text: str) -> str:
    """Transform whitespace in ``text`` according to ``mode``.

    Available modes are:

    * ``all``: Return all whitespace unmodified.
    * ``single``: Collapse consecutive whitespace with a single whitespace
      character, preserving newlines.
    * ``oneline``: Collapse all runs of whitespace into a single space
      character, removing all newlines in the process.

    .. versionadded:: 4.3
    """
    if mode == "all":
        return text
    elif mode == "single":
        text = re.sub(r"([\t ]+)", " ", text)
        text = re.sub(r"(\s*\n\s*)", "\n", text)
        return text
    elif mode == "oneline":
        return re.sub(r"(\s+)", " ", text)
    else:
        raise Exception("invalid whitespace mode %s" % mode)

def filter_whitespace(mode: str, text: str) -> str:
    """Transform whitespace in ``text`` according to ``mode``.

    Available modes are:

    * ``all``: Return all whitespace unmodified.
    * ``single``: Collapse consecutive whitespace with a single whitespace
      character, preserving newlines.
    * ``oneline``: Collapse all runs of whitespace into a single space
      character, removing all newlines in the process.

    .. versionadded:: 4.3
    """
    if mode == "all":
        return text
    elif mode == "single":
        return re.sub(r"\s+", " ", text)
    elif mode == "oneline":
        return re.sub(r"\s+", " ", text).replace("\n", " ")
    else:
        raise ValueError(f"Unknown whitespace mode: {mode!r}")

def _collect_attrs(self, name, obj):
        """Collect all the attributes for the provided file object.
        """
        for key in obj.ncattrs():
            value = getattr(obj, key)
            fc_key = "{}/attr/{}".format(name, key)
            try:
                self.file_content[fc_key] = np2str(value)
            except ValueError:
                self.file_content[fc_key] = value

def _collect_attrs(self, name, obj):
        """Collect all the attributes for the provided file object.
        """
        attrs = {}
        for attr in self._attrs:
            try:
                attrs[attr] = getattr(obj, attr)
            except AttributeError:
                pass
        return attrs

def name_tree(tree):
    """
    Names all the tree nodes that are not named or have non-unique names, with unique names.

    :param tree: tree to be named
    :type tree: ete3.Tree

    :return: void, modifies the original tree
    """
    if tree.name is None:
        tree.name = 'tree'
    if len(tree.get_leaves()) == 0:
        tree.name = 'tree'
    else:
        tree.name = 'tree' + str(len(tree.get_leaves()))
    for node in tree.traverse():
        if node.name is None:
            node.name = 'node' + str(node.idx)
        if len(node.get_leaves()) == 0:
            node.name = 'node' + str(node.idx)
        else:
            node.name = 'node' + str(node.idx) + str(len(node.get_leaves()))

def validate_is_non_abstract_vertex_type(self, vertex_classname):
        """Validate that a vertex classname corresponds to a non-abstract vertex class."""
        element = self.get_vertex_schema_element_or_raise(vertex_classname)

        if element.abstract:
            raise InvalidClassError(u'Expected a non-abstract vertex class, but {} is abstract'
                                    .format(vertex_classname))

def validate_is_non_abstract_vertex_type(self, vertex_classname):
        """Validate that a vertex classname corresponds to a non-abstract vertex class."""
        if not self.is_vertex_type(vertex_classname):
            raise ValueError(f"Vertex type {vertex_classname} is not a vertex type.")
        if self.is_abstract_vertex_type(vertex_classname):
            raise ValueError(f"Vertex type {vertex_classname} is an abstract vertex type.")

def bip32(self, s):
        """
        Parse a bip32 public key from a text string, either a seed, a prv or a pub.
        Return a :class:`BIP32 <pycoin.key.BIP32Node.BIP32Node>` or None.
        """
        if s.startswith('0x'):
            s = s[2:]
        if len(s) == 64:
            return BIP32Node.from_master_secret(s)
        if len(s) == 66:
            return BIP32Node.from_master_public_key(s)
        if len(s) == 128:
            return BIP32Node.from_master_secret(s)
        if len(s) == 130:
            return BIP32Node.from_master_public_key(s)
        return None

def wr_xlsx_sections(self, fout_xlsx, sections, sortby=None, **kws_usr):
        """Write goids into a table."""
        nts = self.get_nts_sections(sections, sortby)
        kws_wr = kws_usr.copy()
        if 'fld2col_widths' not in kws_wr:
            kws_wr['fld2col_widths'] = self.fld2col_widths
        else:
            fld2col_widths = self.fld2col_widths.copy()
            for fld, wid in kws_usr['fld2col_widths'].items():
                fld2col_widths[fld] = wid
            kws_wr['fld2col_widths'] = fld2col_widths
        wr_xlsx_sections_tbl(fout_xlsx, nts, **kws_wr)

def import_url(self, url=None, force=None):
        """
        Read a list of host entries from a URL, convert them into instances of HostsEntry and
        then append to the list of entries in Hosts
        :param url: The URL of where to download a hosts file
        :return: Counts reflecting the attempted additions
        """
        if url is None:
            url = self.url
        if force is None:
            force = self.force
        if url is None:
            raise ValueError("No URL provided")
        if force is None:
            raise ValueError("No force provided")
        try:
            response = requests.get(url)
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            raise HostsError("Failed to download hosts file: {}".format(e))
        try:
            entries = self.parse_hosts_file(response.text)
        except HostsError as e:
            raise HostsError("Failed to parse hosts file: {}".format(e))
        for entry in entries:
            self.add(entry, force=force)
        return len(entries)

