def calculate_size(name, attribute, ordered):
    """ Calculates the request payload size"""
    if attribute == "name":
        return len(name)
    elif attribute == "ordered":
        return len(ordered)
    else:
        return len(attribute)

def set_file_position(body, pos):
    """
    If a position is provided, move file to that point.
    Otherwise, we'll attempt to record a position for future use.
    """
    if pos is not None:
        rewind_body(body, pos)
    elif getattr(body, 'tell', None) is not None:
        try:
            pos = body.tell()
        except (IOError, OSError):
            # This differentiates from None, allowing us to catch
            # a failed `tell()` later when trying to rewind the body.
            pos = _FAILEDTELL

    return pos

def _find_advisory_targets(name=None,
                           advisory_ids=None,
                           **kwargs):
    """
    Inspect the arguments to pkg.patch_installed and discover what advisory
    patches need to be installed. Return a dict of advisory patches to install.
    """
    cur_patches = __salt__['pkg.list_installed_patches'](**kwargs)
    if advisory_ids:
        to_download = advisory_ids
    else:
        to_download = [name]
        if cur_patches.get(name, {}):
            # Advisory patch already installed, no need to install it again
            return {'name': name,
                    'changes': {},
                    'result': True,
                    'comment': 'Advisory patch {0} is already '
                               'installed'.format(name)}

    # Find out which advisory patches will be targeted in the call to pkg.install
    targets = []
    for patch_name in to_download:
        cver = cur_patches.get(patch_name, {})
        # Advisory patch not yet installed, so add to targets
        if not cver:
            targets.append(patch_name)
            continue

    if not targets:
        # All specified packages are already downloaded
        msg = ('All specified advisory patches are already installed')
        return {'name': name,
                'changes': {},
                'result': True,
                'comment': msg}

    return targets

def _find_advisory_targets(name=None,
                           advisory_ids=None,
                           **kwargs):
    """
    Inspect the arguments to pkg.patch_installed and discover what advisory
    patches need to be installed. Return a dict of advisory patches to install.
    """
    # If the user specified a list of advisory IDs, use those.
    if advisory_ids is not None:
        advisory_ids = [str(advisory_id) for advisory_id in advisory_ids]
        return {advisory_id: None for advisory_id in advisory_ids}

    # If the user specified a list of advisory names, use those.
    if name is not None:
        advisory_names = [str(name) for name in name]
        return {advisory_name: None for advisory_name in advisory_names}

    # If the user specified a list of advisory names, use those.
    if kwargs is not None:
        advisory_names = [str(name) for name in kwargs]
        return {advisory_name: None for advisory_name in advisory_names}

    # If the user did not specify anything, return all advisories.
    return {advisory_id: None for advisory_id in _get_advisory_ids()}

def _parse_pool_options(options):
    """Parse connection pool options."""
    pool_options = {}
    for key, value in options.items():
        if key.startswith('pool_'):
            pool_options[key[5:]] = value
    return pool_options

