        """Format using strftime().  The date part of the timestamp passed
        to underlying strftime should not be used.
        """
        return self.strftime(fmt)

def fillna(series_or_arr, missing_value=0.0):
    """Fill missing values in pandas objects and numpy arrays.

    Arguments
    ---------
    series_or_arr : pandas.Series, numpy.ndarray
        The numpy array or pandas series for which the missing values
        need to be replaced.
    missing_value : float, int, str
        The value to replace the missing value with. Default 0.0.

    Returns
    -------
    pandas.Series, numpy.ndarray
        The numpy array or pandas series with the missing values
        filled.
    """
    if isinstance(series_or_arr, pd.Series):
        return series_or_arr.fillna(missing_value)
    elif isinstance(series_or_arr, np.ndarray):
        return np.where(np.isnan(series_or_arr), missing_value, series_or_arr)
    else:
        raise TypeError(
            "The series_or_arr argument must be a pandas.Series or numpy.ndarray."
        )

def agent_leave(consul_url=None, token=None, node=None):
    """
    Used to instruct the agent to force a node into the left state.

    :param consul_url: The Consul server URL.
    :param node: The node the agent will force into left state
    :return: Boolean and message indicating success or failure.

    CLI Example:

    .. code-block:: bash

        salt '*' consul.agent_leave node='web1.example.com'

    """
    if not consul_url:
        consul_url = __salt__["config.get"]("consul.consul_url")
    if not token:
        token = __salt__["config.get"]("consul.token")
    if not node:
        node = __salt__["config.get"]("consul.node")
    if not node:
        return False, "No node specified"
    url = "{}/v1/agent/force-leave/{}".format(consul_url, node)
    headers = {"X-Consul-Token": token}
    try:
        r = requests.put(url, headers=headers)
        if r.status_code == 200:
            return True, "Node {} force-left".format(node)
        else:
            return False, "Failed to force-leave node {}: {}".format(node, r.text)
    except requests.exceptions.RequestException as e:
        return False, "Failed to force-leave node {}: {}".format(node, e)

