        return URLField(
            model_class=model_class,
            field_name=field_name,
            read_only=True,
            required=False,
        )

def contains_point(self, p):
        """
        Returns whether this node or a child overlaps p.
        """
        for iv in self.s_center:
            if iv.contains_point(p):
                return True
        branch = self[p > self.x_center]
        return branch and branch.contains_point(p)

def contains_point(self, p):
        """
        Returns whether this node or a child overlaps p.
        """
        if self.is_leaf():
            return self.point in self.points
        else:
            return self.children[0].contains_point(p) or self.children[1].contains_point(p)

def dimensions(filenames):
    """given a filename or list of filenames,
    return a tuple or sequence of tuples (x, y, filename)"""

    single = type(filenames) is str
    if single:
        filenames = [filenames]
    dims = get_dimensions(filenames)
    if single:
        dims = dims[0]
    return dims

def dimensions(filenames):
    """given a filename or list of filenames,
    return a tuple or sequence of tuples (x, y, filename)"""
    if isinstance(filenames, str):
        filenames = [filenames]
    return [(Image.open(f).size[0], Image.open(f).size[1], f) for f in filenames]

def any2utf8(text, errors='strict', encoding='utf8'):
    """Convert a string (unicode or bytestring in `encoding`), to bytestring in utf8."""
    if isinstance(text, unicode):
        return text.encode('utf8')
    # do bytestring -> unicode -> utf8 full circle, to ensure valid utf8
    return unicode(text, encoding, errors=errors).encode('utf8')

def any2utf8(text, errors='strict', encoding='utf8'):
    """Convert a string (unicode or bytestring in `encoding`), to bytestring in utf8."""
    if isinstance(text, unicode):
        return text.encode(encoding, errors)
    return text

def path(self, goal):
        """Get the shortest way between two nodes of the graph

        Args:
            goal (str): Name of the targeted node
        Return:
            list of Node
        """
        if goal not in self.nodes:
            raise ValueError("Goal node not in graph")
        if self.start == goal:
            return [self.start]
        visited = set()
        queue = [self.start]
        while queue:
            node = queue.pop(0)
            if node == goal:
                return self.path_to(node)
            visited.add(node)
            for neighbor in self.neighbors(node):
                if neighbor not in visited:
                    queue.append(neighbor)
        return None

