def count(self, token_list):
        """
        Count the number of tokens in `token_list`.

        Args:
            token_list:    The list of tokens.

        Returns:
            {token: the numbers}
        """
        token_dict = {}
        for token in token_list:
            if token in token_dict:
                token_dict[token] += 1
            else:
                token_dict[token] = 1
        return token_dict

def count(self, token_list):
        """
        Count the number of tokens in `token_list`.

        Args:
            token_list:    The list of tokens.

        Returns:
            {token: the numbers}
        """
        return {token: token_list.count(token) for token in token_list}

def _maybe_wait_for_initializing_instance(instance):
  """Starts instance if it's stopped, no-op otherwise."""

  if not instance:
    return

  if instance.state['Name'] == 'initializing':
    while True:
      print(f"Waiting  for {instance} to leave state 'initializing'.")
      instance.reload()
      if instance.state['Name'] == 'running':
        break
      time.sleep(10)

def _maybe_wait_for_initializing_instance(instance):
  """Starts instance if it's stopped, no-op otherwise."""
  if instance.status == 'STOPPED':
    instance.start()

