def local_maxima(vector,min_distance = 4, brd_mode = "wrap"):
    """
    Internal finder for local maxima .
    Returns UNSORTED indices of maxima in input vector.
    """
    fits = gaussian_filter(numpy.asarray(vector,dtype=numpy.float32),1., mode=brd_mode)
    for ii in range(len(fits)):
        if fits[ii] == fits[ii-1]:
            fits[ii-1] = 0.0
    maxfits     = maximum_filter(fits, size=min_distance, mode=brd_mode)
    maxima_mask = fits == maxfits
    maximum     = numpy.transpose(maxima_mask.nonzero())
    return numpy.asarray(maximum)

def local_maxima(vector,min_distance = 4, brd_mode = "wrap"):
    """
    Internal finder for local maxima .
    Returns UNSORTED indices of maxima in input vector.
    """
    if brd_mode == "wrap":
        vector = np.concatenate((vector[-min_distance:],vector,vector[:min_distance]))
    elif brd_mode == "none":
        pass
    else:
        raise ValueError("Unknown boundary mode: %s" % brd_mode)
    maxima = np.where(np.logical_and(vector[:-min_distance] < vector[min_distance:],vector[:-min_distance] < vector[min_distance:min_distance+1]))[0]
    return maxima

def assoc(self, key, value):
        """Returns a new ImmutableDict instance with value associated with key.
        The implicit parameter is not modified."""
        return ImmutableDict(self.items() + [(key, value)])

def abusecheck(self, send, nick, target, limit, cmd):
        """ Rate-limits commands.

        | If a nick uses commands with the limit attr set, record the time
        | at which they were used.
        | If the command is used more than `limit` times in a
        | minute, ignore the nick.
        """
        if nick not in self.abuselist:
            self.abuselist[nick] = {}
        if cmd not in self.abuselist[nick]:
            self.abuselist[nick][cmd] = [datetime.now()]
        else:
            self.abuselist[nick][cmd].append(datetime.now())
        count = 0
        for x in self.abuselist[nick][cmd]:
            # 60 seconds - arbitrary cuttoff
            if datetime.now() - x < timedelta(seconds=60):
                count = count + 1
        if count > limit:
            msg = "%s: don't abuse scores!" if cmd == 'scores' else "%s: stop abusing the bot!"
            send(msg % nick, target=target)
            with self.db.session_scope() as session:
                send(misc.ignore(session, nick))
