def set_encode_key_value(self, value, store_type):
        """Save the key value base on it's storage type."""
        self._store_type = store_type
        if store_type == PUBLIC_KEY_STORE_TYPE_HEX:
            self._value = value.hex()
        elif store_type == PUBLIC_KEY_STORE_TYPE_BASE64:
            self._value = b64encode(value).decode()
        elif store_type == PUBLIC_KEY_STORE_TYPE_BASE85:
            self._value = b85encode(value).decode()
        elif store_type == PUBLIC_KEY_STORE_TYPE_JWK:
            # TODO: need to decide on which jwk library to import?
            raise NotImplementedError
        else:
            self._value = value
        return value

def set_encode_key_value(self, value, store_type):
        """Save the key value base on it's storage type."""
        if store_type == 'file':
            self.set_file_key_value(value)
        elif store_type =='memory':
            self.set_memory_key_value(value)
        elif store_type =='redis':
            self.set_redis_key_value(value)
        else:
            raise Exception('Unknown storage type')

def ellipsis_or_number(context, paginator, current_page):
    """
    To avoid display a long pagination bar

    :param context: template context
    :param paginator: paginator_obj
    :param current_page: int
    :return: str or None
    """
    if paginator.num_pages > 11:
        if current_page <= 5:
            return range(1, 12)
        elif current_page > paginator.num_pages - 5:
            return range(paginator.num_pages - 11, paginator.num_pages + 1)
        else:
            return range(current_page - 5, current_page + 6)
    else:
        return None

def get_func(fullFuncName):
    """Retrieve a function object from a full dotted-package name."""
    module_name, func_name = fullFuncName.rsplit('.', 1)
    module = importlib.import_module(module_name)
    return getattr(module, func_name)

