    return hasattr(obj, '__iter__') and not isinstance(obj, str)

def to_str(s, encoding=None, errors='strict', normalize=False):
    """
    Given str, bytes, bytearray, or unicode (py2), return str
    """
    def _normalize(s):
        try:
            return unicodedata.normalize('NFC', s) if normalize else s
        except TypeError:
            return s

    if encoding is None:
        # Try utf-8 first, and fall back to detected encoding
        encoding = ('utf-8', __salt_system_encoding__)
    if not isinstance(encoding, (tuple, list)):
        encoding = (encoding,)

    if not encoding:
        raise ValueError('encoding cannot be empty')

    # This shouldn't be six.string_types because if we're on PY2 and we already
    # have a string, we should just return it.
    if isinstance(s, str):
        return _normalize(s)

    exc = None
    if six.PY3:
        if isinstance(s, (bytes, bytearray)):
            for enc in encoding:
                try:
                    return _normalize(s.decode(enc, errors))
                except UnicodeDecodeError as err:
                    exc = err
                    continue
            # The only way we get this far is if a UnicodeDecodeError was
            # raised, otherwise we would have already returned (or raised some
            # other exception).
            raise exc  # pylint: disable=raising-bad-type
        raise TypeError('expected str, bytes, or bytearray not {}'.format(type(s)))
    else:
        if isinstance(s, bytearray):
            return str(s)  # future lint: disable=blacklisted-function
        if isinstance(s, unicode):  # pylint: disable=incompatible-py3-code,undefined-variable
            for enc in encoding:
                try:
                    return _normalize(s).encode(enc, errors)
                except UnicodeEncodeError as err:
                    exc = err
                    continue
            # The only way we get this far is if a UnicodeDecodeError was
            # raised, otherwise we would have already returned (or raised some
            # other exception).
            raise exc  # pylint: disable=raising-bad-type
        raise TypeError('expected str, bytearray, or unicode')

def to_str(s, encoding=None, errors='strict', normalize=False):
    """
    Given str, bytes, bytearray, or unicode (py2), return str
    """
    if isinstance(s, bytes):
        if encoding is None:
            encoding = 'utf-8'
        return s.decode(encoding, errors)
    elif isinstance(s, bytearray):
        if encoding is None:
            encoding = 'utf-8'
        return s.decode(encoding, errors)
    elif isinstance(s, str):
        return s
    elif isinstance(s, unicode):
        return s.encode('utf-8', errors)
    else:
        raise TypeError('to_str() arg must be one of str, bytes, bytearray, or unicode, not'+ str(type(s)))

def refresh_fqdn_cache(force=False):
    """
    Force refreshes all FQDNs used in rules.

    force
        Forces all fqdn refresh

    CLI Example:

    .. code-block:: bash

        salt '*' panos.refresh_fqdn_cache
        salt '*' panos.refresh_fqdn_cache force=True

    """
    if not isinstance(force, bool):
        raise CommandExecutionError("Force option must be boolean.")

    if force:
        query = {'type': 'op',
                 'cmd': '<request><system><fqdn><refresh><force>yes</force></refresh></fqdn></system></request>'}
    else:
        query = {'type': 'op', 'cmd': '<request><system><fqdn><refresh></refresh></fqdn></system></request>'}

    return __proxy__['panos.call'](query)

def closeView(self, view=None):
        """
        Closes the inputed view.

        :param      view | <int> || <XView> || None
        """
        if type(view) == int:
            view = self.widget(view)
        elif view == None:
            view = self.currentView()

        index = self.indexOf(view)
        if index == -1:
            return False

        # close the view
        count = self.count()
        if count == 1:
            self.closePanel()
        else:
            view.close()

        return True

def closeView(self, view=None):
        """
        Closes the inputed view.

        :param      view | <int> || <XView> || None
        """
        if view is None:
            view = self.view
        if isinstance(view, int):
            view = self.view.view(view)
        if isinstance(view, XView):
            view.close()
        else:
            raise TypeError("view must be an int or XView")

def set_value(self, comp_str):
        """
        Set the value of component.

        :param string comp_str: value of component
        :returns: None
        :exception: ValueError - incorrect value of component
        """
        if comp_str == '0':
            self.value = 0
        elif comp_str == '1':
            self.value = 1
        else:
            raise ValueError('Incorrect value of component')

def get_fields_with_visibility(self, visibility, mode="add"):
        """Return the AR fields with the current visibility
        """
        fields = []
        for field in self.fields:
            if field.visibility == visibility:
                fields.append(field)
        return fields

def generate_readme(self):
        """ Generate a readme with all the generators
        """
        readme = []
        for generator in self.generators:
            readme.append(generator.generate_readme())
        return "\n".join(readme)

def process_nested_tags(self, node, tag = ''):
        """
        Process child tags.

        @param node: Current node being parsed.
        @type node: xml.etree.Element

        @raise ParseError: Raised when an unexpected nested tag is found.
        """
        ##print("---------Processing: %s, %s"%(node.tag,tag))

        if tag == '':
            t = node.ltag
        else:
            t = tag.lower()

        for child in node.children:
            self.xml_node_stack = [child] + self.xml_node_stack

            ctagl = child.ltag

            if ctagl in self.tag_parse_table and ctagl in self.valid_children[t]:
                #print("Processing known type: %s"%ctagl)
                self.tag_parse_table[ctagl](child)
            else:
                #print("Processing unknown type: %s"%ctagl)
                self.parse_component_by_typename(child, child.tag)

            self.xml_node_stack = self.xml_node_stack[1:]

