      return self.load_map(map_name)
    else:
      raise ValueError("No map named %s" % map_name)

def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    try:
        return ~x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return ~y.isin(x)
            except AttributeError:
                pass
        return x not in y

def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    if isinstance(x, np.ndarray) and isinstance(y, np.ndarray):
        return np.in1d(x, y, invert=True)
    else:
        return [i not in y for i in x]

