def _handle_retry(self, resp):
        """Handle any exceptions during API request or
        parsing its response status code.

        Parameters:
        resp: requests.Response instance obtained during concerning request
            or None, when request failed

        Returns: True if should retry our request or raises original Exception
        """
        exc_t, exc_v, exc_tb = sys.exc_info()

        if exc_t is None:
            raise TypeError('Must be called in except block.')

        retry_on_exc = tuple(
            (x for x in self._retry_on if inspect.isclass(x)))
        retry_on_codes = tuple(
            (x for x in self._retry_on if isinstance(x, int)))

        if issubclass(exc_t, ZendeskError):
            code = exc_v.error_code
            if exc_t not in retry_on_exc and code not in retry_on_codes:
                six.reraise(exc_t, exc_v, exc_tb)
        else:
            if not issubclass(exc_t, retry_on_exc):
                six.reraise(exc_t, exc_v, exc_tb)

        if resp is not None:
            try:
                retry_after = float(resp.headers.get('Retry-After', 0))
                time.sleep(retry_after)
            except (TypeError, ValueError):
                pass

        return True

def _handle_retry(self, resp):
        """Handle any exceptions during API request or
        parsing its response status code.

        Parameters:
        resp: requests.Response instance obtained during concerning request
            or None, when request failed

        Returns: True if should retry our request or raises original Exception
        """
        if resp is None:
            raise Exception("Request failed")
        if resp.status_code == 429:
            raise Exception("Too many requests")
        if resp.status_code == 400:
            raise Exception("Bad request")
        if resp.status_code == 401:
            raise Exception("Unauthorized")
        if resp.status_code == 403:
            raise Exception("Forbidden")
        if resp.status_code == 404:
            raise Exception("Not found")
        if resp.status_code == 500:
            raise Exception("Internal server error")
        if resp.status_code == 502:
            raise Exception("Bad gateway")
        if resp.status_code == 503:
            raise Exception("Service unavailable")
        if resp.status_code == 504:
            raise Exception("Gateway timeout")
        return False

def check_network_id(network_id, web3: Web3):
    """ Check periodically if the underlying ethereum client's network id has changed"""
    while True:
        current_id = int(web3.version.network)
        if network_id != current_id:
            raise RuntimeError(
                f'Raiden was running on network with id {network_id} and it detected '
                f'that the underlying ethereum client network id changed to {current_id}.'
                f' Changing the underlying blockchain while the Raiden node is running '
                f'is not supported.',
            )
        gevent.sleep(CHECK_NETWORK_ID_INTERVAL)

def check_network_id(network_id, web3: Web3):
    """ Check periodically if the underlying ethereum client's network id has changed"""
    while True:
        time.sleep(10)
        if web3.eth.net.getId()!= network_id:
            raise Exception(
                "Network id changed from {} to {}".format(
                    network_id, web3.eth.net.getId()
                )
            )

def stream_command(cmd, no_newline_regexp="Progess", sudo=False):
    """stream a command (yield) back to the user, as each line is available.

       # Example usage:
       results = []
       for line in stream_command(cmd):
           print(line, end="")
           results.append(line)

       Parameters
       ==========
       cmd: the command to send, should be a list for subprocess
       no_newline_regexp: the regular expression to determine skipping a
                          newline. Defaults to finding Progress

    """
    if sudo:
        cmd = ["sudo"] + cmd
    p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    while True:
        line = p.stdout.readline()
        if line:
            if no_newline_regexp:
                if re.search(no_newline_regexp, line.decode("utf-8")):
                    continue
            yield line
        else:
            break
    p.wait()
    if p.returncode!= 0:
        raise Exception("Command failed with return code %d" % p.returncode)

def duration(self):
        """Returns the integer value of the interval, the value is in milliseconds.

        If the interval has not had stop called yet,
        it will report the number of milliseconds in the interval up to the current point in time.
        """
        if self._stop_instant is None:
            return int((instant() - self._start_instant) * 1000)
        if self._duration is None:
            self._duration = int((self._stop_instant - self._start_instant) * 1000)
        return self._duration

def get_entity_uuid_coords(self, uuid):
        """
        Returns the coordinates of the given entity UUID inside this world, or
        `None` if the UUID is not found.
        """
        if uuid in self._entity_to_region_map:
            coords = self._entity_to_region_map[uuid]
            entities = self.get_entities(*coords)
            for entity in entities:
                if 'uniqueId' in entity.data and entity.data['uniqueId'] == uuid:
                    return tuple(entity.data['tilePosition'])
        return None

def get_entity_uuid_coords(self, uuid):
        """
        Returns the coordinates of the given entity UUID inside this world, or
        `None` if the UUID is not found.
        """
        return self.entity_uuid_coords.get(uuid)

def _calculate_offset(date, local_tz):
    """
    input :
    date : date type
    local_tz : if true, use system timezone, otherwise return 0

    return the date of UTC offset.
    If date does not have any timezone info, we use local timezone,
    otherwise return 0
    """
    if local_tz:
        #handle year before 1970 most sytem there is no timezone information before 1970.
        if date.year < 1970:
            # Use 1972 because 1970 doesn't have a leap day
            t = time.mktime(date.replace(year=1972).timetuple)
        else:
            t = time.mktime(date.timetuple())

        # handle daylightsaving, if daylightsaving use altzone, otherwise use timezone
        if time.localtime(t).tm_isdst:
            return -time.altzone
        else:
            return -time.timezone
    else:
        return 0

def _calculate_offset(date, local_tz):
    """
    input :
    date : date type
    local_tz : if true, use system timezone, otherwise return 0

    return the date of UTC offset.
    If date does not have any timezone info, we use local timezone,
    otherwise return 0
    """
    if date.tzinfo is None:
        if local_tz:
            return date.tzinfo
        else:
            return 0
    else:
        return date.utcoffset()

def _number_zero_start_handler(c, ctx):
    """Handles numeric values that start with zero or negative zero. Branches to delegate co-routines according to
    _ZERO_START_TABLE.
    """
    if ctx.match_char('0'):
        if ctx.match_char('x'):
            return _number_hex_start_handler(c, ctx)
        elif ctx.match_char('b'):
            return _number_binary_start_handler(c, ctx)
        elif ctx.match_char('o'):
            return _number_octal_start_handler(c, ctx)
        elif ctx.match_char('d'):
            return _number_decimal_start_handler(c, ctx)
        elif ctx.match_char('e'):
            return _number_exponent_start_handler(c, ctx)
        elif ctx.match_char('f'):
            return _number_float_start_handler(c, ctx)
        elif ctx.match_char('n'):
            return _number_nan_start_handler(c, ctx)
        elif ctx.match_char('i'):
            return _number_infinity_start_handler(c, ctx)
        elif ctx.match_char('p'):
            return _number_infinity_start_handler(c, ctx)
        elif ctx.match_char('t'):
            return _number_true_start_handler(c, ctx)
        elif ctx.match_char('f'):
            return _number_false_start_handler(c, ctx)
        else:
            return _number_decimal_start_handler(c, ctx)
    else:
        return _number_decimal_start_handler(c, ctx)

def is_monotonic(a, increasing=True):
    """
    Tests whether a vector a has monotonicity.

    Parameters
    ----------
    a : array-like
        Array that should be tested for monotonicity

    increasing : bool, default: True
        Test if the array is montonically increasing, otherwise test if the
        array is montonically decreasing.
    """
    a = np.asarray(a) # ensure a is array-like

    if a.ndim > 1:
        raise ValueError("not supported for multi-dimensonal arrays")

    if len(a) <= 1:
        return True

    if increasing:
        return np.all(a[1:] >= a[:-1], axis=0)
    return np.all(a[1:] <= a[:-1], axis=0)

def is_monotonic(a, increasing=True):
    """
    Tests whether a vector a has monotonicity.

    Parameters
    ----------
    a : array-like
        Array that should be tested for monotonicity

    increasing : bool, default: True
        Test if the array is montonically increasing, otherwise test if the
        array is montonically decreasing.
    """
    if increasing:
        return np.all(np.diff(a) >= 0)
    else:
        return np.all(np.diff(a) <= 0)

def propagate_timezone_option(self):
        """Set our timezone value and give it too to unset satellites

        :return: None
        """
        if self.use_timezone:
            # first apply myself
            os.environ['TZ'] = self.use_timezone
            time.tzset()

            tab = [self.schedulers, self.pollers, self.brokers, self.receivers, self.reactionners]
            for sat_list in tab:
                for sat in sat_list:
                    if sat.use_timezone == 'NOTSET':
                        setattr(sat, 'use_timezone', self.use_timezone)

def propagate_timezone_option(self):
        """Set our timezone value and give it too to unset satellites

        :return: None
        """
        if self.timezone is not None:
            self.set_timezone(self.timezone)
            for satellite in self.satellites:
                satellite.set_timezone(self.timezone)

