def save_favorite_query(arg, **_):
    """Save a new favorite query.
    Returns (title, rows, headers, status)"""

    usage = 'Syntax: \\fs name query.\n\n' + favoritequeries.usage
    if not arg:
        return [(None, None, None, usage)]

    name, _, query = arg.partition(' ')

    # If either name or query is missing then print the usage and complain.
    if (not name) or (not query):
        return [(None, None, None,
            usage + 'Err: Both name and query are required.')]

    favoritequeries.save(name, query)
    return [(None, None, None, "Saved.")]

def save_favorite_query(arg, **_):
    """Save a new favorite query.
    Returns (title, rows, headers, status)"""
    title = arg.get('title')
    if not title:
        return 'Title is required', None, None, 400
    query = arg.get('query')
    if not query:
        return 'Query is required', None, None, 400
    if not isinstance(query, str):
        return 'Query must be a string', None, None, 400
    if not isinstance(title, str):
        return 'Title must be a string', None, None, 400
    if len(title) > 255:
        return 'Title must be less than 255 characters', None, None, 400
    if len(query) > 10000:
        return 'Query must be less than 10000 characters', None, None, 400
    user = get_user()
    if not user:
        return 'User not found', None, None, 404
    try:
        db.session.add(FavoriteQuery(title=title, query=query, user_id=user.id))
        db.session.commit()
    except Exception as e:
        return 'Error saving favorite query: {}'.format(e), None, None, 500
    return 'Favorite query saved', None, None, 200

