def aprint(*values, sep=None, end='\n', flush=False, streams=None, use_stderr=False, loop=None):
    """Asynchronous equivalent to *print*."""
    if streams is None:
        streams = [sys.stdout]
    if use_stderr:
        streams.append(sys.stderr)
    if loop is None:
        loop = asyncio.get_event_loop()
    coros = [loop.create_task(stream.write(sep.join(str(v) for v in values) + end)) for stream in streams]
    return asyncio.gather(*coros)

def sort_cyclic_graph_best_effort(graph, pick_first='head'):
    """Fallback for cases in which the graph has cycles."""
    if pick_first == 'head':
        return sort_cyclic_graph_head_first(graph)
    elif pick_first == 'tail':
        return sort_cyclic_graph_tail_first(graph)
    else:
        raise ValueError(f"Unknown pick_first value: {pick_first}")

def generate_checker(value):
