def reportMemory(k, options, field=None, isBytes=False):
    """ Given k kilobytes, report back the correct format as string.
    """
    if options.pretty:
        return prettyMemory(int(k), field=field, isBytes=isBytes)
    else:
        if isBytes:
            k /= 1024.
        if field is not None:
            return "%*dK" % (field - 1, k)  # -1 for the "K"
        else:
            return "%dK" % int(k)

def reportMemory(k, options, field=None, isBytes=False):
    """ Given k kilobytes, report back the correct format as string.
    """
    if isBytes:
        k *= 1024
    if k < 1024:
        return "%d B" % k
    elif k < 1024 * 1024:
        return "%.1f KB" % (k / 1024.0)
    elif k < 1024 * 1024 * 1024:
        return "%.1f MB" % (k / (1024.0 * 1024.0))
    elif k < 1024 * 1024 * 1024 * 1024:
        return "%.1f GB" % (k / (1024.0 * 1024.0 * 1024.0))
    else:
        return "%.1f TB" % (k / (1024.0 * 1024.0 * 1024.0 * 1024.0))

