def verify(self, signature, msg):
        """
        Verify the message
        """
        if not self.key:
            return False
        try:
            self.key.verify(signature + msg)
        except ValueError:
            return False
        return True

def verify(self, signature, msg):
        """
        Verify the message
        """
        return self.key.verify(signature, msg)

def uninstall(self):
    """Uninstall this importer if possible and un-import any modules imported by it."""
    if not self._uninstallable:
      _tracer().log('Not uninstalling {}'.format(self), V=9)
      return

    if self in sys.meta_path:
      sys.meta_path.remove(self)
      maybe_exposed = frozenset(os.path.join(self._root, importable.path)
                                for importable in self._importables)
      sys.path[:] = [path_item for path_item in sys.path if path_item not in maybe_exposed]
      for loader in self._loaders:
        loader.unload()
      _tracer().log('Uninstalled {}'.format(self), V=3)

def uninstall(self):
    """Uninstall this importer if possible and un-import any modules imported by it."""
    if self.is_installed():
      self.uninstall_impl()
      self.unimport_modules()

def convert_enum(func):
    """
    Decorator to use Enum value on type casts.
    """

    @wraps(func)
    def inner(self, value):
        try:
            if self.check_value(value.value):
                return value.value
            return func(self, value.value)
        except AttributeError:
            pass

        return func(self, value)

    return inner

def read(self, line, f, data):
        """See :meth:`PunchParser.read`"""
        self.used = True
        data["title"] = f.readline().strip()
        data["symmetry"] = f.readline().split()[0]
        if data["symmetry"] != "C1":
            raise NotImplementedError("Only C1 symmetry is supported.")
        symbols = []
        while line != " $END      \n":
            line = f.readline()
            if line[0] != " ":
                symbols.append(line.split()[0])
        data["symbols"] = symbols

def read(self, line, f, data):
        """See :meth:`PunchParser.read`"""
        if line.startswith('PUNCH'):
            self.punch_count += 1
            self.punch_data.append(data)
        elif line.startswith('PUNCH_END'):
            self.punch_end_count += 1
            self.punch_end_data.append(data)
        else:
            self.other_count += 1
            self.other_data.append(data)

def get_data(session=None, day=None, year=None):
    """
    Get data for day (1-25) and year (>= 2015)
    User's session cookie is needed (puzzle inputs differ by user)
    """
    if session is None:
        raise ValueError('Session cookie is needed')
    if day is None:
        raise ValueError('Day is needed')
    if year is None:
        raise ValueError('Year is needed')
    if year < 2015:
        raise ValueError('Year must be >= 2015')
    if day < 1 or day > 25:
        raise ValueError('Day must be 1-25')

    url = 'https://www.puzzle-123.com/puzzle/123/123-day-{}-{}.html'.format(day, year)
    r = requests.get(url, cookies={'session': session})
    if r.status_code!= 200:
        raise ValueError('Failed to get data')
    soup = BeautifulSoup(r.text, 'html.parser')
    return soup.find('div', {'class': 'puzzle-content'}).text.strip()

def get_file_size(filename):
    """
    Get size of all files in gigabytes (Gb).

    :param str | collections.Iterable[str] filename: A space-separated
        string or list of space-separated strings of absolute file paths.
    :return float: size of file(s), in gigabytes.
    """
    if filename is None:
        return float(0)
    if type(filename) is list:
        return float(sum([get_file_size(x) for x in filename]))
    try:
        total_bytes = sum([float(os.stat(f).st_size)
                           for f in filename.split(" ") if f is not ''])
    except OSError:
        # File not found
        return 0.0
    else:
        return float(total_bytes) / (1024 ** 3)

def resolve_resource_id_refs(self, input_dict, supported_resource_id_refs):
        """
        Updates references to the old logical id of a resource to the new (generated) logical id.

        Example:
            {"Ref": "MyLayer"} => {"Ref": "MyLayerABC123"}

        :param dict input_dict: Dictionary representing the Ref function to be resolved.
        :param dict supported_resource_id_refs: Dictionary that maps old logical ids to new ones.
        :return dict: Dictionary with resource references resolved.
        """

        if not self.can_handle(input_dict):
            return input_dict

        ref_value = input_dict[self.intrinsic_name]
        if not isinstance(ref_value, string_types) or self._resource_ref_separator in ref_value:
            return input_dict

        logical_id = ref_value

        resolved_value = supported_resource_id_refs.get(logical_id)
        if not resolved_value:
            return input_dict

        return {
            self.intrinsic_name: resolved_value
        }

def resolve_resource_id_refs(self, input_dict, supported_resource_id_refs):
        """
        Updates references to the old logical id of a resource to the new (generated) logical id.

        Example:
            {"Ref": "MyLayer"} => {"Ref": "MyLayerABC123"}

        :param dict input_dict: Dictionary representing the Ref function to be resolved.
        :param dict supported_resource_id_refs: Dictionary that maps old logical ids to new ones.
        :return dict: Dictionary with resource references resolved.
        """
        if input_dict is None:
            return None

        if isinstance(input_dict, dict):
            if "Ref" in input_dict:
                if input_dict["Ref"] in supported_resource_id_refs:
                    input_dict["Ref"] = supported_resource_id_refs[input_dict["Ref"]]
            else:
                for key, value in input_dict.items():
                    input_dict[key] = self.resolve_resource_id_refs(value, supported_resource_id_refs)
        elif isinstance(input_dict, list):
            for index, value in enumerate(input_dict):
                input_dict[index] = self.resolve_resource_id_refs(value, supported_resource_id_refs)
        return input_dict

def utf8(value):
    r"""
    Check that the string is UTF-8. Returns an encode bytestring.

    >>> utf8(b'\xe0')  # doctest: +ELLIPSIS
    Traceback (most recent call last):
    ...
    ValueError: Not UTF-8: ...
    """
    try:
        if isinstance(value, bytes):
            return value.decode('utf-8')
        else:
            return value
    except Exception:
        raise ValueError('Not UTF-8: %r' % value)

def utf8(value):
    r"""
    Check that the string is UTF-8. Returns an encode bytestring.

    >>> utf8(b'\xe0')  # doctest: +ELLIPSIS
    Traceback (most recent call last):
    ...
    ValueError: Not UTF-8: ...
    """
    if isinstance(value, str):
        return value.encode('utf-8')
    if isinstance(value, bytes):
        return value
    raise ValueError('Not UTF-8: %r' % value)

def click_table_printer(headers, _filter, data):
    """Generate space separated output for click commands."""
    if not data:
        return ''
    if not headers:
        headers = data[0].keys()
    return''.join(
        [
           ''.join(
                [
                    str(data[i][header])
                    for header in headers
                    if header in data[i]
                ]
            )
            for i in range(len(data))
        ]
    )

def add_path(self, path, method=None):
        """
        Adds the path/method combination to the Swagger, if not already present

        :param string path: Path name
        :param string method: HTTP method
        :raises ValueError: If the value of `path` in Swagger is not a dictionary
        """
        if not isinstance(self.swagger['paths'][path], dict):
            raise ValueError('Path {} already exists in Swagger'.format(path))

        if method is None:
            self.swagger['paths'][path] = self.swagger['paths'][path]
        else:
            self.swagger['paths'][path][method.lower()] = self.swagger['paths'][path][method.lower()]

def generate_valid_keys():
    """ create a list of valid keys """
    valid_keys = []
    for minimum, maximum in RANGES:
        for i in range(ord(minimum), ord(maximum) + 1):
            valid_keys.append(chr(i))
    return valid_keys

def generate_valid_keys():
    """ create a list of valid keys """
    valid_keys = []
    for i in range(0, 256):
        valid_keys.append(i)
    return valid_keys

def enc_setup(self, enc_alg, msg, auth_data=b'', key=None, iv=""):
        """ Encrypt JWE content.

        :param enc_alg: The JWE "enc" value specifying the encryption algorithm
        :param msg: The plain text message
        :param auth_data: Additional authenticated data
        :param key: Key (CEK)
        :return: Tuple (ciphertext, tag), both as bytes
        """
        if key is None:
            key = self.key
        if iv == "":
            iv = self.iv
        if enc_alg == "A128CBC-HS256":
            return self.encrypt_a128cbc_hs256(msg, auth_data, key, iv)
        elif enc_alg == "A192CBC-HS384":
            return self.encrypt_a192cbc_hs384(msg, auth_data, key, iv)
        elif enc_alg == "A256CBC-HS512":
            return self.encrypt_a256cbc_hs512(msg, auth_data, key, iv)
        elif enc_alg == "A128GCM":
            return self.encrypt_a128gcm(msg, auth_data, key, iv)
        elif enc_alg == "A192GCM":
            return self.encrypt_a192gcm(msg, auth_data, key, iv)
        elif enc_alg == "A256GCM":
            return self.encrypt_a256gcm(msg, auth_data, key, iv)
        elif enc_alg == "A128KW":
            return self.encrypt_a128kw(msg, key, iv)
        elif enc_alg == "A192KW":
            return self.encrypt_a192kw(msg, key, iv)
        elif enc_alg == "A256KW":
            return self.encrypt_a256kw(msg, key, iv)
        elif enc_alg == "dir":
            return self.encrypt_dir(msg, key, iv)
        else:
            raise ValueError("Unsupported encryption algorithm: {}".format(enc_alg))

def iriToURI(iri):
    """Transform an IRI to a URI by escaping unicode."""
    # According to RFC 3987, section 3.1, "Mapping of IRIs to URIs"
    if isinstance(iri, bytes):
        iri = str(iri, encoding="utf-8")
    return iri.encode('ascii', errors='oid_percent_escape').decode()

def iriToURI(iri):
    """Transform an IRI to a URI by escaping unicode."""
    return quote(iri.encode('utf8'))

def check_for_deletion(self, relative_path=None):
        """Traverse the entire remote_path tree.

        Find files/directories that need to be deleted,
        not being present in the local folder.
        """
        if not relative_path:
            relative_path = str()  # root of shared directory tree

        remote_path = path_join(self.remote_path, relative_path)
        local_path = path_join(self.local_path, relative_path)

        for remote_st in self.sftp.listdir_attr(remote_path):
            r_lstat = self.sftp.lstat(path_join(remote_path, remote_st.filename))

            inner_remote_path = path_join(remote_path, remote_st.filename)
            inner_local_path = path_join(local_path, remote_st.filename)

            # check if remote_st is a symlink
            # otherwise could delete file outside shared directory
            if S_ISLNK(r_lstat.st_mode):
                if self._must_be_deleted(inner_local_path, r_lstat):
                    self.remote_delete(inner_remote_path, r_lstat)
                continue

            if self._must_be_deleted(inner_local_path, remote_st):
                self.remote_delete(inner_remote_path, remote_st)
            elif S_ISDIR(remote_st.st_mode):
                self.check_for_deletion(
                    path_join(relative_path, remote_st.filename)
                )

def check_for_deletion(self, relative_path=None):
        """Traverse the entire remote_path tree.

        Find files/directories that need to be deleted,
        not being present in the local folder.
        """
        if relative_path is None:
            relative_path = self.remote_path
        if not os.path.exists(relative_path):
            return
        if os.path.isdir(relative_path):
            for item in os.listdir(relative_path):
                self.check_for_deletion(os.path.join(relative_path, item))
        else:
            if relative_path not in self.local_files:
                self.delete_file(relative_path)

