def _get_debug_formatter(conf):
    """Get debug formatter based on configuration.

    :param conf: configurtration namespace (ex. argparser)

    --debug: log line numbers, file data
    --verbose: standard log format at a DEBUG loglevel
    --quiet: turn down logging output (logging.WARNING)
    default is logging.INFO
    """
    if conf.debug is True:
        return DebugFormatter('%(pathname)s:%(lineno)d: %(levelname)-8s '
                              '%(message)s')
    elif conf.verbose is True:
        return logging.Formatter(
            '%(name)-30s: %(levelname)-8s %(message)s')
    elif conf.quiet is True:
        return logging.Formatter('%(message)s')
    else:
        return logging.Formatter(logging.BASIC_FORMAT)

def _get_debug_formatter(conf):
    """Get debug formatter based on configuration.

    :param conf: configurtration namespace (ex. argparser)

    --debug: log line numbers, file data
    --verbose: standard log format at a DEBUG loglevel
    --quiet: turn down logging output (logging.WARNING)
    default is logging.INFO
    """
    if conf.debug:
        return logging.Formatter(
            '%(levelname)s:%(filename)s:%(lineno)d: %(message)s'
        )
    elif conf.verbose:
        return logging.Formatter(
            '%(levelname)s:%(filename)s: %(message)s'
        )
    else:
        return logging.Formatter('%(message)s')

def train(self, record):
        """
        Updates the trees with the given training record.
        """
        self._fell_trees()
        self._grow_trees()
        for tree in self.trees:
            if random.random() < self.sample_ratio:
                tree.train(record)
            else:
                tree.out_of_bag_samples.append(record)
                while len(tree.out_of_bag_samples) > self.max_out_of_bag_samples:
                    tree.out_of_bag_samples.pop(0)

def get_pubmed_citation_response(pubmed_identifiers: Iterable[str]):
    """Get the response from PubMed E-Utils for a given list of PubMed identifiers.

    :param pubmed_identifiers:
    :rtype: dict
    """
    pubmed_identifiers = list(pubmed_identifiers)
    if not pubmed_identifiers:
        return {}

    url = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
    params = {
        'db': 'pubmed',
        'id': ','.join(pubmed_identifiers),
       'retmode': 'xml',
       'rettype': 'abstract',
    }
    response = requests.get(url, params=params)
    response.raise_for_status()
    return response.json()

def clear(self, pat=None):
        """
        Minor diversion with built-in dict here;  clear can take a glob
        style expression and remove keys based on that expression.
        """
        if pat is None:
            return self.__dict__.clear()

        expr = re.compile(fnmatch.translate(pat))
        for key in tuple(self.keys()):
            #make sure the key is a str first
            if isinstance(key, string_types):
                if expr.match(key):
                    del self.__dict__[key]

def clear(self, pat=None):
        """
        Minor diversion with built-in dict here;  clear can take a glob
        style expression and remove keys based on that expression.
        """
        if pat is None:
            self.clear()
        else:
            for key in self.keys():
                if fnmatch.fnmatch(key, pat):
                    del self[key]

