def _is_module_included(self, module):
        """Evaluate if the module must be included in the Odoo addons.

        :param string module: the name of the module
        :rtype: bool
        """
        if module in self.exclude_modules:
            return False

        if self.include_modules is None:
            return True

        return module in self.include_modules

def _is_module_included(self, module):
        """Evaluate if the module must be included in the Odoo addons.

        :param string module: the name of the module
        :rtype: bool
        """
        if module in self.modules:
            return True
        elif module in self.modules_exclude:
            return False
        elif module in self.modules_include:
            return True
        elif module in self.modules_include_exclude:
            return False
        elif module in self.modules_include_exclude_exclude:
            return True
        else:
            return False

