def graph_to_dot(graph, node_renderer=None, edge_renderer=None):
    """Produces a DOT specification string from the provided graph."""
    if node_renderer is None:
        node_renderer = lambda node: node
    if edge_renderer is None:
        edge_renderer = lambda edge: edge
    dot = "digraph {\n"
    for node in graph.nodes():
        dot += "  %s [label=\"%s\"];\n" % (node, node_renderer(node))
    for edge in graph.edges():
        dot += "  %s -> %s [label=\"%s\"];\n" % (edge[0], edge[1], edge_renderer(edge))
    dot += "}"
    return dot

def thaicheck(word: str) -> bool:
    """
    Check if a word is an "authentic Thai word"

    :param str word: word
    :return: True or False
    """
    if not word:
        return False
    if len(word) < 2:
        return False
    if word[0] in 'ก-ฮ':
        return False
    if word[-1] in 'ก-ฮ':
        return False
    return True

def mainloop(self):
        """ The main loop.
        """
        if len(self.args) == 1 and "=urn:btih:" in self.args[0]:
            # Handle magnet link
            self.make_magnet_meta(self.args[0])
            return

        if not self.args:
            self.parser.print_help()
            self.parser.exit()
        elif len(self.args) < 2:
            self.parser.error("Expected a path and at least one announce URL, got: %s" % (' '.join(self.args),))

        # Create and configure metafile factory
        datapath = self.args[0].rstrip(os.sep)
        metapath = datapath
        if self.options.output_filename:
            metapath = self.options.output_filename
            if os.path.isdir(metapath):
                metapath = os.path.join(metapath, os.path.basename(datapath))
        if not metapath.endswith(".torrent"):
            metapath += ".torrent"
        torrent = metafile.Metafile(metapath)
        torrent.ignore.extend(self.options.exclude)

        def callback(meta):
            "Callback to set label and resume data."
            if self.options.cross_seed:
                if self.options.cross_seed == "@entropy":
                    meta["info"]["entropy"] = format(random.getrandbits(self.ENTROPY_BITS),
                                                     'x').zfill(self.ENTROPY_BITS//4)
                else:
                    meta["info"]["x_cross_seed_label"] = self.options.cross_seed
            if self.options.no_cross_seed:
                del meta["info"]["x_cross_seed"]

            # Set specific keys?
            metafile.assign_fields(meta, self.options.set)

        # Create and write the metafile(s)
        # TODO: make it work better with multiple trackers (hash only once), also create fast-resume file for each tracker
        meta = torrent.create(datapath, self.args[1:],
            progress=None if self.options.quiet else metafile.console_progress(),
            root_name=self.options.root_name, private=self.options.private, no_date=self.options.no_date,
            comment=self.options.comment, created_by="PyroScope %s" % self.version, callback=callback
        )

        # Create second metafile with fast-resume?
        if self.options.hashed:
            try:
                metafile.add_fast_resume(meta, datapath)
            except EnvironmentError as exc:
                self.fatal("Error making fast-resume data (%s)" % (exc,))
                raise

            hashed_path = re.sub(r"\.torrent$", "", metapath) + "-resume.torrent"
            self.LOG.info("Writing fast-resume metafile %r..." % (hashed_path,))
            try:
                bencode.bwrite(hashed_path, meta)
            except EnvironmentError as exc:
                self.fatal("Error writing fast-resume metafile %r (%s)" % (hashed_path, exc,))
                raise

def _perform_unique_localized_field_checks(self, unique_checks):
        """
        Do the checks for the localized fields.
        """
        for model_class, unique_check in unique_checks:
            # Get the localized fields for the model
            localized_fields = self._get_localized_fields(model_class)

            # Check if the localized fields are unique
            if localized_fields:
                self._check_unique_localized_fields(model_class, unique_check, localized_fields)

def _has_actions(self, event):
        """Check if a notification type has any enabled actions."""
        event_actions = self._aconfig.get(event)
        return event_actions is None or bool(event_actions)

def _has_actions(self, event):
        """Check if a notification type has any enabled actions."""
        return any(
            action.enabled
            for action in self._get_actions(event)
            if action.enabled
        )

def convert_tags_to_dict(item):
    """
    Convert AWS inconvenient tags model of a list of {"Key": <key>, "Value": <value>} pairs
    to a dict of {<key>: <value>} for easier querying.

    This returns a proxied object over given item to return a different tags format as the tags
    attribute is read-only and we cannot modify it directly.
    """
    if hasattr(item, 'tags'):
        tags = item.tags
        if isinstance(tags, list):
            tags_dict = {}
            for kv_dict in tags:
                if isinstance(kv_dict, dict) and 'Key' in kv_dict and 'Value' in kv_dict:
                    tags_dict[kv_dict['Key']] = kv_dict['Value']
            return ObjectProxy(item, tags=tags_dict)
    return item

def append(self, data):
        """Append the given `data` to the output.

        :arg data: If a list, it is formatted as a bullet list with each
            entry in the list being a separate bullet.  Otherwise if it is a
            string, the string is added as a paragraph.

        :raises: ValueError if `data` is not a list or a string.

        """
        if isinstance(data, list):
            for item in data:
                self.append(item)
        elif isinstance(data, str):
            self.append_paragraph(data)
        else:
            raise ValueError("data must be a list or a string")

def save(self, **kwargs):
        """Override save method to catch handled errors and repackage them as 400 errors."""
        try:
            return super().save(**kwargs)
        except SlugError as error:
            raise ParseError(error)

