def parse_file(file_or_path, encoding='utf-8', validate=False):
    """
    Tries to parse a given filepath or fileobj into a Bibliography instance. If
    ``validate`` is passed as keyword argument and set to ``True``, the
    Bibliography will be validated using the standard rules.
    """
    try:
        is_string = isinstance(file_or_path, basestring)
    except NameError:
        is_string = isinstance(file_or_path, str)
    if is_string:
        with codecs.open(file_or_path, 'r', encoding) as file_:
            result = pattern.parseFile(file_)[0]
    else:
        result = pattern.parseFile(file_or_path)[0]
    if validate:
        result.validate()
    return result

def parse_file(file_or_path, encoding='utf-8', validate=False):
    """
    Tries to parse a given filepath or fileobj into a Bibliography instance. If
    ``validate`` is passed as keyword argument and set to ``True``, the
    Bibliography will be validated using the standard rules.
    """
    if isinstance(file_or_path, basestring):
        with open(file_or_path, 'r') as f:
            return parse_fileobj(f, encoding=encoding, validate=validate)
    else:
        return parse_fileobj(file_or_path, encoding=encoding, validate=validate)

def is_fqdn(hostname):
    """
    Verify if hostname conforms to be a FQDN.

    :param hostname: text string with the name of the host
    :return: bool, True if hostname is correct FQDN, False otherwise
    """
    if not isinstance(hostname, str):
        return False
    try:
        socket.gethostbyname(hostname)
        return True
    except socket.error:
        return False

def _make_validations(self, table: pd.DataFrame) -> Box:
        """Return a dict-like object containing dataframes of which tests passed/failed for each column."""
        results = []

        for column in self.columns:
            results.append(column.validate(table))

        return results

def _make_validations(self, table: pd.DataFrame) -> Box:
        """Return a dict-like object containing dataframes of which tests passed/failed for each column."""
        validations = Box()
        for col in table.columns:
            validations[col] = self._make_validation(table[col])
        return validations

