def structs2pandas(structs):
    """convert ctypes structure or structure array to pandas data frame"""
    if isinstance(structs, ctypes._Pointer):
        structs = structs.contents
    if isinstance(structs, ctypes._Array):
        structs = structs[:]
    if isinstance(structs, ctypes._Structure):
        return pd.DataFrame([structs])
    if isinstance(structs, list):
        return pd.DataFrame([s._asdict() for s in structs])
    raise TypeError("structs must be a ctypes structure or structure array")

def delete_node(node_id, purge_data,**kwargs):
    """
        Remove node from DB completely
        If there are attributes on the node, use purge_data to try to
        delete the data. If no other resources link to this data, it
        will be deleted.

    """
    if not node_id:
        raise exception.InvalidParameterValue(
            'node_id is required'
        )

    try:
        node = Node.objects.get(id=node_id)
    except Node.DoesNotExist:
        raise exception.NodeNotFound(node_id=node_id)

    # Delete the node
    node.delete()

    # Delete the node's attributes
    if purge_data:
        try:
            node.delete_attributes()
        except exception.NodeAttributeNotFound:
            pass

    # Delete the node's relationships
    try:
        node.delete_relationships()
    except exception.NodeRelationshipNotFound:
        pass

