def dump(self, name, obj, context=None):
        """Serialize data to primitive types. Raises
        :exc:`~lollipop.errors.ValidationError` if data is invalid.

        :param str name: Name of attribute to serialize.
        :param obj: Application object to extract serialized value from.
        :returns: Serialized data.
        :raises: :exc:`~lollipop.errors.ValidationError`
        """
        if context is None:
            context = {}

        try:
            return self.schema.dump(getattr(obj, name), many=self.many)
        except ValidationError as err:
            raise ValidationError(err.messages, err.valid_data)

def select_each(conn, query: str, parameter_groups, name=None):
    """Run select query for each parameter set in single transaction."""
    with conn.cursor() as cursor:
        for parameters in parameter_groups:
            cursor.execute(query, parameters)
            yield cursor.fetchall()

def _cdist_scipy(x, y, exponent=1):
    """Pairwise distance between the points in two sets."""
    metric = 'euclidean'

    if exponent != 1:
        metric = 'sqeuclidean'

    distances = _spatial.distance.cdist(x, y, metric=metric)

    if exponent != 1:
        distances **= exponent / 2

    return distances

def _cdist_scipy(x, y, exponent=1):
    """Pairwise distance between the points in two sets."""
    return cdist(x, y, metric='minkowski', p=exponent)

