def tlp_classifiers(self, name_tlp, val_tlp):
        """
        Classifier between Cortex and Soltra.
        Soltra uses name-TLP, and Cortex "value-TLP"
        """
        if name_tlp == "unclassified":
            return "unclassified"
        elif name_tlp == "untrusted":
            return "untrusted"
        elif name_tlp == "low":
            return "low"
        elif name_tlp == "medium":
            return "medium"
        elif name_tlp == "high":
            return "high"
        elif name_tlp == "critical":
            return "critical"
        else:
            return "unclassified"

def is_used(self, regs, i, top=None):
        """ Checks whether any of the given regs are required from the given point
        to the end or not.
        """
        if i < 0:
            i = 0

        if self.lock:
            return True

        regs = list(regs)  # make a copy
        if top is None:
            top = len(self)
        else:
            top -= 1

        for ii in range(i, top):
            for r in self.mem[ii].requires:
                if r in regs:
                    return True

            for r in self.mem[ii].destroys:
                if r in regs:
                    regs.remove(r)

            if not regs:
                return False

        self.lock = True
        result = self.goes_requires(regs)
        self.lock = False

        return result

def is_used(self, regs, i, top=None):
        """ Checks whether any of the given regs are required from the given point
        to the end or not.
        """
        if top is None:
            top = len(self.instructions)
        for reg in regs:
            for j in range(i, top):
                if reg in self.instructions[j].regs:
                    return True
        return False

