        :param soap_headers:
        :param sign:
        :return: dictionary
        """
        if not soap_headers:
            soap_headers = {}
        if not destination:
            destination = self.service_url
        if not sign:
            sign = self.sign
        return {
           'request': request,
            'destination': destination,
           'soap_headers': soap_headers,
           'sign': sign
        }

def index_template_delete(name, hosts=None, profile=None):
    """
    Delete an index template (type) along with its data

    name
        Index template name

    CLI example::

        salt myminion elasticsearch.index_template_delete testindex_templ user
    """
    es = _get_instance(hosts, profile)
    try:
        result = es.indices.delete_template(name=name)

        return result.get('acknowledged', False)
    except elasticsearch.exceptions.NotFoundError:
        return True
    except elasticsearch.TransportError as e:
        raise CommandExecutionError("Cannot delete template {0}, server returned code {1} with message {2}".format(name, e.status_code, e.error))

def index_template_delete(name, hosts=None, profile=None):
    """
    Delete an index template (type) along with its data

    name
        Index template name

    CLI example::

        salt myminion elasticsearch.index_template_delete testindex_templ user
    """
    if hosts is None:
        hosts = __salt__['elasticsearch.hosts']()
    if profile is None:
        profile = __salt__['elasticsearch.profile']()
    return __salt__['elasticsearch.index_template_delete'](name, hosts, profile)

def rgb_to_name(rgb_triplet, spec=u'css3'):
    """
    Convert a 3-tuple of integers, suitable for use in an ``rgb()``
    color triplet, to its corresponding normalized color name, if any
    such name exists.

    The optional keyword argument ``spec`` determines which
    specification's list of color names will be used; valid values are
    ``html4``, ``css2``, ``css21`` and ``css3``, and the default is
    ``css3``.

    If there is no matching name, ``ValueError`` is raised.

    """
    if spec == u'html4':
        return _html4_names.get(rgb_triplet)
    elif spec == u'css2':
        return _css2_names.get(rgb_triplet)
    elif spec == u'css21':
        return _css21_names.get(rgb_triplet)
    elif spec == u'css3':
        return _css3_names.get(rgb_triplet)
    else:
        raise ValueError(u'Unknown color specification: %s' % spec)

