        self.mailbox.put(message)

def validate(self, value, attribute_filter=None, minified=False):
        """
        :param value:
        :type value: list | None
        :param attribute_filter:
        :type attribute_filter: prestans.parser.AttributeFilter
        :param minified:
        :type minified: bool
        :return:
        """

        if not self._required and value is None:
            return None
        elif self._required and value is None:
            raise exception.RequiredAttributeError()

        _validated_value = self.__class__(
            element_template=self._element_template,
            min_length=self._min_length,
            max_length=self._max_length
        )

        if not isinstance(value, (list, tuple)):
            raise TypeError(value)

        for array_element in value:

            if isinstance(self._element_template, DataCollection):
                validated_array_element = self._element_template.validate(array_element, attribute_filter, minified)
            else:
                validated_array_element = self._element_template.validate(array_element)

            _validated_value.append(validated_array_element)

        if self._min_length is not None and len(_validated_value) < self._min_length:
            raise exception.LessThanMinimumError(value, self._min_length)

        if self._max_length is not None and len(_validated_value) > self._max_length:
            raise exception.MoreThanMaximumError(value, self._max_length)

        return _validated_value

def validate(self, value, attribute_filter=None, minified=False):
        """
        :param value:
        :type value: list | None
        :param attribute_filter:
        :type attribute_filter: prestans.parser.AttributeFilter
        :param minified:
        :type minified: bool
        :return:
        """
        if value is None:
            return

        if not isinstance(value, list):
            raise ValueError("Value must be a list")

        for item in value:
            if not isinstance(item, dict):
                raise ValueError("Value must be a list of dict")

            if not self.validate_item(item, attribute_filter, minified):
                return False

        return True

def add(self, name, parents=None):
        """
        add a node to the graph.

        Raises an exception if the node cannot be added (i.e., if a node
        that name already exists, or if it would create a cycle.

        NOTE: A node can be added before its parents are added.

        name: The name of the node to add to the graph. Name can be any
            unique Hashable value.
        parents: (optional, None) The name of the nodes parents.
        """
        if not isinstance(name, Hashable):
            raise TypeError(name)

        parents = set(parents or ())
        is_stub = False

        if name in self._nodes:
            if name in self._stubs:
                node = Node(name, self._nodes[name].children, parents)
                is_stub = True
            else:
                raise ValueError(name)
        else:
            node = Node(name, set(), parents)

        # cycle detection
        visited = set()

        for parent in parents:
            if self.ancestor_of(parent, name, visited=visited):
                raise ValueError(parent)
            elif parent == name:
                raise ValueError(parent)

        # Node safe to add
        if is_stub:
            self._stubs.remove(name)

        if parents:
            for parent_name in parents:
                parent_node = self._nodes.get(parent_name)

                if parent_node is not None:
                    parent_node.children.add(name)
                else:  # add stub
                    self._nodes[parent_name] = Node(
                        name=parent_name,
                        children=set((name,)),
                        parents=frozenset(),
                    )
                    self._stubs.add(parent_name)
        else:
            self._roots.add(name)

        self._nodes[name] = node

def status(self):
        """
        The current status of the event (started, finished or pending).
        """
        myNow = timezone.localtime(timezone=self.tz)
        if getAwareDatetime(self.date_to, self.time_to, self.tz) < myNow:
            return "finished"
        elif getAwareDatetime(self.date_from, self.time_from, self.tz) < myNow:
            return "started"

