def _get_node(response, *ancestors):
    """ Traverse tree to node """
    document = response
    for ancestor in ancestors:
        if ancestor not in document:
            return {}
        else:
            document = document[ancestor]
    return document

def _get_node(response, *ancestors):
    """ Traverse tree to node """
    for ancestor in ancestors:
        response = response[ancestor]
    return response

