            return self.fmtname2wbfmtobj.get('plain')
        # User namedtuple field/value for color
        if self.ntfld_wbfmt is not None:
            return self.__get_wbfmt_usrfld(data_nt)
        # namedtuple format_txt for color/bold/border
        if self.b_format_txt:
            wbfmt = self.__get_wbfmt_format_txt(data_nt)
            if wbfmt is not None:
                return wbfmt
        # 'ntfld_wbfmt': namedtuple field which contains a value used as a key for a xlsx format
        # 'ntval2wbfmtdict': namedtuple value and corresponding xlsx format dict.
        return self.fmtname2wbfmtobj.get('plain')

def get_wbfmt(self, data_nt=None):
        """Return format for text cell."""
        if data_nt is None:
            data_nt = self.data_nt
        if data_nt is None:
            return None
        if data_nt.get_type() == 'text':
            return 'text'
        if data_nt.get_type() == 'int':
            return 'int'
        if data_nt.get_type() == 'float':
            return 'float'
        if data_nt.get_type() == 'bool':
            return 'bool'
        if data_nt.get_type() == 'date':
            return 'date'
        if data_nt.get_type() == 'datetime':
            return 'datetime'
        if data_nt.get_type() == 'time':
            return 'time'
        if data_nt.get_type() == 'timedelta':
            return 'timedelta'
        if data_nt.get_type() == 'list':
            return 'list'
        if data_nt.get_type() == 'dict':
            return 'dict'
        if data_nt.get_type() =='set':
            return'set'
        if data_nt.get_type() == 'tuple':
            return 'tuple'
        if data_nt.get_type() == 'object':
            return 'object'
        return None

def construct_result_generator_middleware(result_generators):
    """
    Constructs a middleware which intercepts requests for any method found in
    the provided mapping of endpoints to generator functions, returning
    whatever response the generator function returns.  Callbacks must be
    functions with the signature `fn(method, params)`.
    """
    def result_generator_middleware(make_request, web3):
        def middleware(method, params):
            if method in result_generators:
                result = result_generators[method](method, params)
                return {'result': result}
            else:
                return make_request(method, params)
        return middleware
    return result_generator_middleware

def result(self, result, functionality):
        """
        For the final result of the scan.
        @param result: as returned by BasePluginInternal.url_scan
        @param functionality: functionality as returned by
            BasePluginInternal._general_init
        """
