def _add_compounds(self, variant_obj, info_dict):
        """Check if there are any compounds and add them to the variant

            The compounds that are added should be sorted on rank score
        """
        compound_list = []
        compound_entry = info_dict.get('Compounds')
        if compound_entry:
            for family_annotation in compound_entry.split(','):
                compounds = family_annotation.split(':')[-1].split('|')
                for compound in compounds:
                    splitted_compound = compound.split('>')

                    compound_score = None
                    if len(splitted_compound) > 1:
                        compound_id = splitted_compound[0]
                        compound_score = int(splitted_compound[-1])

                    compound_list.append(Compound(
                        variant_id=compound_id,
                        combined_score=compound_score
                        )
                    )

        #Sort the compounds based on rank score
        compound_list.sort(key = operator.attrgetter('combined_score'), reverse=True)

        for compound in compound_list:
            variant_obj.add_compound(compound)

def _add_compounds(self, variant_obj, info_dict):
        """Check if there are any compounds and add them to the variant

            The compounds that are added should be sorted on rank score
        """
        if 'compounds' in info_dict:
            compounds = info_dict['compounds']
            for compound in compounds:
                compound_obj = Compound.objects.get(id=compound['id'])
                variant_obj.compounds.add(compound_obj)
                variant_obj.save()

def read(self, pin, is_differential=False):
        """I2C Interface for ADS1x15-based ADCs reads.

        params:
            :param pin: individual or differential pin.
            :param bool is_differential: single-ended or differential read.
        """
        if is_differential:
            self.i2c.write(self.address, [self.REG_POINTER_DIFF_0 + pin])
        else:
            self.i2c.write(self.address, [self.REG_POINTER_SINGLE + pin])
        return self.i2c.read(self.address, 2)

def recursive_symlink_dirs(source_d, destination_d):
    """
    Create dirs and symlink all files recursively from source_d, ignoring
    errors (e.g. existing files)
    """
    for d in os.listdir(source_d):
        source_d_d = os.path.join(source_d, d)
        destination_d_d = os.path.join(destination_d, d)
        if os.path.isdir(source_d_d):
            if not os.path.exists(destination_d_d):
                os.mkdir(destination_d_d)
            recursive_symlink_dirs(source_d_d, destination_d_d)
        else:
            try:
                os.symlink(source_d_d, destination_d_d)
            except OSError:
                pass

def consume_path_sep(self, i):
        """Consume any consecutive path separators are they count as one."""

        try:
            if self.bslash_abort:
                count = -1
                c = '\\'
                while c == '\\':
                    count += 1
                    c = next(i)
                i.rewind(1)
                # Rewind one more if we have an odd number (escape): \\\*
                if count > 0 and count % 2:
                    i.rewind(1)
            else:
                c = '/'
                while c == '/':
                    c = next(i)
                i.rewind(1)
        except StopIteration:
            pass

def consume_path_sep(self, i):
        """Consume any consecutive path separators are they count as one."""
        while i < len(self.path) and self.path[i] == self.path_sep:
            i += 1
        return i

def remove_callback(obj, handle):
    """Remove a callback from an object."""
    callbacks = obj._callbacks
