  """Urquhart graph: made from the 2 shortest edges of each Delaunay triangle.
  """
  if weighted:
    raise NotImplementedError
  else:
    return nx.Graph(X)

def _get_color(self, age):
        """Get the fill color depending on age.

        Args:
            age (int): The age of the branch/es

        Returns:
            tuple: (r, g, b)
        """
        if age < 10:
            return (255, 255, 255)
        elif age < 20:
            return (255, 255, 0)
        elif age < 30:
            return (255, 0, 0)
        elif age < 40:
            return (255, 0, 255)
        elif age < 50:
            return (0, 0, 255)
        elif age < 60:
            return (0, 255, 255)
        elif age < 70:
            return (0, 255, 0)
        elif age < 80:
            return (0, 255, 255)
        elif age < 90:
            return (0, 0, 255)
        elif age < 100:
            return (255, 0, 0)
        else:
            return (255, 255, 255)

def find(self, name, current_location):
        """Given 'name' which can be project-id or plain directory name,
        return project module corresponding to that id or directory.
        Returns nothing of project is not found."""
        if name in self.projects:
            return self.projects[name]
        else:
            for project in self.projects.values():
                if project.directory == name:
                    return project
            else:
                print("Project not found: %s" % name)

