def exit_config_mode(self, exit_config="exit configuration-mode"):
        """Exit configuration mode."""
        output = ""
        if self.check_config_mode():
            output = self.send_command_timing(
                exit_config, strip_prompt=False, strip_command=False
            )
            # if 'Exit with uncommitted changes?' in output:
            if "uncommitted changes" in output:
                output += self.send_command_timing(
                    "yes", strip_prompt=False, strip_command=False
                )
            if self.check_config_mode():
                raise ValueError("Failed to exit configuration mode")
        return output

def calculateDatasetItems(self, scene, datasets):
        """
        Syncs the scene together with the given datasets to make sure we
        have the proper number of items, by removing non-existant datasets
        and adding new ones.

        :param      scene    | <XChartScene>
                    datasets | <XChartDataset>

        :return     {<XChartDataset>: <XChartDatasetItem>, ..}
        """
        # Remove datasets that are not in the scene
        for dataset in datasets:
            if dataset.name not in scene.datasets:
                scene.removeDataset(dataset.name)

        # Add datasets that are not in the scene
        for dataset in datasets:
            if dataset.name not in scene.datasets:
                scene.addDataset(dataset)

        # Return the scene's datasets
        return scene.datasets

