def plot_lr(self, show_text=True, show_moms=True):
        """Plots the lr rate/momentum schedule"""
        if not hasattr(self, 'lrs'):
            raise RuntimeError("Plotting before fitting has been run.")
        lrs = self.lrs
        iters = list(range(len(lrs)))
        if show_moms:
            moms = self.moms
            plt.plot(iters, moms, label='Momentum Schedule')
        plt.plot(iters, lrs, label='Learning Rate Schedule')
        if show_text:
            for x, y in zip(iters, lrs):
                plt.text(x, y, '%.4f' % y, ha='center', va='bottom', fontsize=10)
            if show_moms:
                for x, y in zip(iters, moms):
                    plt.text(x, y, '%.4f' % y, ha='center', va='top', fontsize=10)
        plt.xlabel("Iteration")
        plt.ylabel("Rate")
        plt.legend()
        plt.show()

