def read_data(
    nlp,
    conllu_file,
    text_file,
    raw_text=True,
    oracle_segments=False,
    max_doc_length=None,
    limit=None,
):
    """Read the CONLLU format into (Doc, GoldParse) tuples. If raw_text=True,
    include Doc objects created using nlp.make_doc and then aligned against
    the gold-standard sequences. If oracle_segments=True, include Doc objects
    created from the gold-standard segments. At least one must be True."""
    if not (raw_text or oracle_segments):
        raise ValueError("At least one of raw_text or oracle_segments must be True")
    if raw_text and oracle_segments:
        raise ValueError("Only one of raw_text or oracle_segments may be True")
    if oracle_segments and not conllu_file:
        raise ValueError("oracle_segments requires a conllu_file")
    if raw_text and not text_file:
        raise ValueError("raw_text requires a text_file")
    if raw_text:
        with open(text_file) as f:
            text = f.read()
    if oracle_segments:
        with open(conllu_file) as f:
            conllu = f.read()
    for doc, gold in read_conllu(conllu_file, text_file, limit=limit):
        if raw_text:
            doc = nlp.make_doc(text)
            doc = align_doc(doc, gold)
        if oracle_segments:
            doc = align_doc(doc, gold)
        yield doc, gold

def edge_val_set(self, graph, orig, dest, idx, key, branch, turn, tick, value):
        """Set this key of this edge to this value."""
        if (branch, turn, tick) in self._btts:
            raise TimeError
        self._btts.add((branch, turn, tick))
        graph, orig, dest, key, value = map(self.pack, (graph, orig, dest, key, value))
        self._edgevals2set.append(
            (graph, orig, dest, idx, key, branch, turn, tick, value)
        )

