def u2handlers(self):
        """
        Get a collection of urllib handlers.
        @return: A list of handlers to be installed in the opener.
        @rtype: [Handler,...]
        """
        handlers = []
        if self.proxy:
            handlers.append(urllib2.ProxyHandler(self.proxy))
        if self.ca_certs:
            handlers.append(urllib2.HTTPSHandler(ca_certs=self.ca_certs))
        return handlers

