def define_saver(exclude=None):
  """Create a saver for the variables we want to checkpoint.

  Args:
    exclude: List of regexes to match variable names to exclude.

  Returns:
    Saver object.
  """
  if exclude is None:
    exclude = []
  var_list = []
  for var in tf.global_variables():
    if not any(re.match(regex, var.name) for regex in exclude):
      var_list.append(var)
  return tf.train.Saver(var_list)

def await_results(url, pings=45, sleep=2):
    """
    Ping {url} until it returns a results payload, timing out after
    {pings} pings and waiting {sleep} seconds between pings.
    """
    for i in range(pings):
        try:
            r = requests.get(url)
            if r.status_code == 200:
                return r.json()
        except requests.exceptions.RequestException:
            pass
        time.sleep(sleep)
    return None

def reconstruct_dict(dot_paths, values):

    """ a method for reconstructing a dictionary from the values along dot paths """

    output_dict = {}

    for i in range(len(dot_paths)):
        if i + 1 <= len(values):
            path_segments = segment_path(dot_paths[i])
            current_nest = output_dict
            for j in range(len(path_segments)):
                key_name = path_segments[j]
                try:
                    key_name = int(key_name)
                except:
                    pass
                if j + 1 == len(path_segments):
                    if isinstance(key_name, int):
                        current_nest.append(values[i])
                    else:
                        current_nest[key_name] = values[i]
                else:
                    next_key = path_segments[j+1]
                    try:
                        next_key = int(next_key)
                    except:
                        pass
                    if isinstance(next_key, int):
                        if not key_name in current_nest.keys():
                            current_nest[key_name] = []
                        current_nest = current_nest[key_name]
                    else:
                        if isinstance(key_name, int):
                            current_nest.append({})
                            current_nest = current_nest[len(current_nest) - 1]
                        else:
                            if not key_name in current_nest.keys():
                                current_nest[key_name] = {}
                            current_nest = current_nest[key_name]

    return output_dict

def reconstruct_dict(dot_paths, values):

    """ a method for reconstructing a dictionary from the values along dot paths """

    # create a dictionary
    d = {}

    # iterate over the dot paths
    for i, dot_path in enumerate(dot_paths):

        # get the value
        value = values[i]

        # get the keys
        keys = dot_path.split('.')

        # iterate over the keys
        for j, key in enumerate(keys):

            # if this is the last key, assign the value
            if j == len(keys) - 1:
                d[key] = value

            # if this is not the last key, create a new dictionary
            else:
                d = {key: d}

    # return the dictionary
    return d

