def secho(text, file=None, nl=True, err=False, color=None, **styles):
    """This function combines :func:`echo` and :func:`style` into one
    call.  As such the following two calls are the same::

        click.secho('Hello World!', fg='green')
        click.echo(click.style('Hello World!', fg='green'))

    All keyword arguments are forwarded to the underlying functions
    depending on which one they go with.

    .. versionadded:: 2.0
    """
    if file is None:
        file = click.get_text_stdout()
    if nl:
        text += '\n'
    if err:
        file = click.get_text_stderr()
    return style(text, file=file, **styles)

def read_txt_file(filepath):
    """read text from `filepath` and remove linebreaks
    """
    if sys.version > '3':
        with open(filepath,'r',encoding='utf-8') as txt_file:
            return txt_file.readlines()
    else:
        with open(filepath) as txt_file:
            return txt_file.readlines()

def get_rupture(oqparam):
    """
    Read the `rupture_model` file and by filter the site collection

    :param oqparam:
        an :class:`openquake.commonlib.oqvalidation.OqParam` instance
    :returns:
        an hazardlib rupture
    """
    rupture_model = oqparam.get_value('rupture_model')
    if rupture_model is None:
        return None
    rupture_model_file = oqparam.get_value('rupture_model_file')
    if rupture_model_file is None:
        return None
    rupture_model_file = os.path.join(oqparam.get_value('base_dir'),
                                      rupture_model_file)
    rupture_model_file = os.path.abspath(rupture_model_file)
    if not os.path.exists(rupture_model_file):
        raise OqParamError('rupture_model_file %s does not exist' %
                           rupture_model_file)
    rupture_model_file = os.path.abspath(rupture_model_file)
    if rupture_model == 'point_source':
        return PointRuptureFromUtm(rupture_model_file)
    elif rupture_model == 'complex_fault_surface':
        return ComplexFaultRuptureFromUtm(rupture_model_file)
    else:
        raise OqParamError('rupture_model %s not supported' % rupture_model)

def split_fasta(f, id2f):
    """
    split fasta file into separate fasta files based on list of scaffolds
    that belong to each separate file
    """
    opened = {}
    for seq in parse_fasta(f):
        id = seq[0].split('>')[1].split()[0]
        if id not in id2f:
            continue
        fasta = id2f[id]
        if fasta not in opened:
            opened[fasta] = '%s.fa' % fasta
        seq[1] += '\n'
        with open(opened[fasta], 'a+') as f_out:
            f_out.write('\n'.join(seq))

def google_v3(address):
    """
    Given an address, return ``(computed_address, (latitude, longitude))``
    tuple using Google Geocoding API v3.

    """
    try:
        g = geocoders.GoogleV3(api_key=settings.EASY_MAPS_GOOGLE_KEY or settings.EASY_MAPS_GOOGLE_MAPS_API_KEY)

        results = g.geocode(smart_str(address), exactly_one=False)
        if results is not None:
            return results[0]

        raise Error("No results found for '%s'" % address)
    except (UnboundLocalError, ValueError, GeocoderServiceError) as e:
        raise Error(e)

def reorder_lines(lines, tol=TOLERANCE):
    """
    Changes the line coordinates to be given as (top, left, bottom, right)
    :param lines: list of lines coordinates
    :return: reordered list of lines coordinates
    """
    reordered_lines = []
    for line in lines:
        if line[0] > line[2]:
            reordered_lines.append((line[2], line[3], line[0], line[1]))
        else:
            reordered_lines.append(line)
    return reordered_lines

def log_fault (exc, message = "", level = logging.CRITICAL,
               traceback = False):
  """Print the usual traceback information, followed by a listing of all
  the local variables in each frame.
  """
  if message:
    print(message)
  print(exc)
  if traceback:
    traceback.print_exc()
  print("Locals by frame, innermost last")
  for frame in traceback.extract_tb(sys.exc_info()[2]):
    print("Frame %s in %s at line %s" % frame)
    for var_name, var_value in frame.frame.f_locals.items():
      print("  %15s = %s" % (var_name, repr(var_value)))

