def _check_for_default_values(fname, arg_val_dict, compat_args):
    """
    Check that the keys in `arg_val_dict` are mapped to their
    default values as specified in `compat_args`.

    Note that this function is to be called only when it has been
    checked that arg_val_dict.keys() is a subset of compat_args

    """
    for arg_name, arg_val in arg_val_dict.items():
        if arg_name not in compat_args:
            raise ValueError(
                f"Argument {arg_name} is not a valid argument for {fname}."
            )
        if arg_val!= compat_args[arg_name]:
            raise ValueError(
                f"Argument {arg_name} has a value of {arg_val} "
                f"which is not the default value of {compat_args[arg_name]}."
            )

