def compute_gradient(self):
        """Compute the gradient of the current model using the training set
        """
        delta = self.predict(self.X) - self.y
        return delta.dot(self.X) / len(self.X)

def set_property(obj, name, value):
        """
        Sets value of object property specified by its name.

        If the property does not exist or introspection fails
        this method doesn't do anything and doesn't any throw errors.

        :param obj: an object to write property to.

        :param name: a name of the property to set.

        :param value: a new value for the property to set.
        """
        if obj == None:
            raise Exception("Object cannot be null")
        if name == None:
            raise Exception("Property name cannot be null")

        name = name.lower()

        try:
            for property_name in dir(obj): 
                if property_name.lower() != name:
                    continue

                property = getattr(obj, property_name)

                if PropertyReflector._is_property(property, property_name):
                    setattr(obj, property_name, value)
        except:
            pass

def _get_type(self, s):
        """
        Converts a string from Scratch to its proper type in Python. Expects a
        string with its delimiting quotes in place. Returns either a string, 
        int or float. 
        """
        # TODO: what if the number is bigger than an int or float?
        if s.startswith('"') and s.endswith('"'):
            return s[1:-1]
        elif s.find('.') != -1: 
            return float(s) 
        else: 
            return int(s)

def _get_type(self, s):
        """
        Converts a string from Scratch to its proper type in Python. Expects a
        string with its delimiting quotes in place. Returns either a string, 
        int or float. 
        """
        if s.isdigit():
            return int(s)
        else:
            try:
                return float(s)
            except ValueError:
                return s

def apply(self, node):
        """ Apply transformation and return if an update happened. """
        if not isinstance(node, ast.Call):
            return False

        if not isinstance(node.func, ast.Attribute):
            return False

        if not isinstance(node.func.value, ast.Name):
            return False

        if node.func.value.id!= "self":
            return False

        if node.func.attr!= "get_context":
            return False

        if not isinstance(node.args[0], ast.Str):
            return False

        if node.args[0].s!= "request":
            return False

        if not isinstance(node.args[1], ast.Str):
            return False

        if node.args[1].s!= "context":
            return False

        if not isinstance(node.args[2], ast.Str):
            return False

        if node.args[2].s!= "default":
            return False

        node.args[2] = ast.Str(s=self.context)

        return True

