def percent_records_missing_location(user, method=None):
    """
    Return the percentage of records missing a location parameter.
    """

    if len(user.records) == 0:
        return 0.

    missing_locations = sum([1 for record in user.records if record.position._get_location(user) is None])
    return float(missing_locations) / len(user.records)

def percent_records_missing_location(user, method=None):
    """
    Return the percentage of records missing a location parameter.
    """
    if method is None:
        method = user.method
    return user.records_missing_location(method) / user.records_total(method)

def eval(lisp):
    """
    plash lisp is one dimensional lisp.
    """
    macro_values = []
    if not isinstance(lisp, list):
        raise EvalError('eval root element must be a list')
    for item in lisp:
        if not isinstance(item, list):
            raise EvalError('must evaluate list of list')
        if not all(isinstance(i, str) for i in item):
            raise EvalError(
                'must evaluate list of list of strings. not a list of strings: {}'
                .format(item))
        name = item[0]
        args = item[1:]
        try:
            macro = state['macros'][name]
        except KeyError:
            raise MacroNotFoundError("macro {} not found".format(repr(name)))
        try:
            res = macro(*args)
        except Exception as exc:
            if os.getenv('PLASH_DEBUG', '').lower() in ('1', 'yes', 'true'):
                raise
            if isinstance(exc, MacroError):
                # only raise that one time and don't have multiple wrapped MacroError
                raise
            raise MacroError(macro, name, sys.exc_info())
        if not isinstance(res, str) and res is not None:
            raise EvalError(
                'eval macro must return string or None ({} returned {})'.
                format(name, type(res)))
        if res is not None:
            macro_values.append(res)
    return '\n'.join(macro_values)

def eval(lisp):
    """
    plash lisp is one dimensional lisp.
    """
    if isinstance(lisp, list):
        if len(lisp) == 0:
            return None
        elif len(lisp) == 1:
            return eval(lisp[0])
        else:
            return eval_list(lisp)
    else:
        return lisp

def _adjust_inserted_indices(inserted_indices_list, prune_indices_list):
        """Adjust inserted indices, if there are pruned elements."""
        if not prune_indices_list:
            return inserted_indices_list

        # Adjust inserted indices, if there are pruned elements.
        for i, inserted_indices in enumerate(inserted_indices_list):
            if not inserted_indices:
                continue
            for j, inserted_index in enumerate(inserted_indices):
                if inserted_index in prune_indices_list:
                    inserted_indices_list[i][j] = inserted_index - 1
        return inserted_indices_list

