def _write_values(kwargs, variables):
    """Write values of kwargs and return thus-satisfied closures."""
    writeto = []
    for var_name, value in kwargs.items():
        var = variables[var_name]
        var.notify_will_write()
        var.write(value)
        writeto.append(var)
    return _notify_reader_writes(writeto)

def _write_values(kwargs, variables):
    """Write values of kwargs and return thus-satisfied closures."""
    closures = []
    for key, value in kwargs.items():
        if key in variables:
            closures.append(lambda: setattr(variables, key, value))
    return closures

def iuniq(ible):
    """Get an iterator over unique items of `ible`."""
    items = set()
    for item in ible:
        if item not in items:
            items.add(item)
            yield item

def iuniq(ible):
    """Get an iterator over unique items of `ible`."""
    return (x for x in set(ible))

def _parse(self, line):
        """Parse the output line"""
        try:
            result = line.split(':', maxsplit=4)
            filename, line_num_txt, column_txt, message_type, text = result
        except ValueError:
            return

        try:
            self.line_num = int(line_num_txt.strip())
            self.column = int(column_txt.strip())
        except ValueError:
            return

        self.filename = filename
        self.message_type = message_type.strip()
        self.text = text.strip()
        self.valid = True

def _parse(self, line):
        """Parse the output line"""
        if not line:
            return
        if line.startswith('>'):
            self._parse_header(line)
        else:
            self._parse_sequence(line)

def parse_footnotes(document, xmlcontent):
    """Parse footnotes document.

    Footnotes are defined in file 'footnotes.xml'
    """

    footnotes = etree.fromstring(xmlcontent)
    document.footnotes = {}

    for footnote in footnotes.xpath('.//w:footnote', namespaces=NAMESPACES):
        _type = footnote.attrib.get(_name('{{{w}}}type'), None)

        # don't know what to do with these now
        if _type in ['separator', 'continuationSeparator', 'continuationNotice']:
            continue

        paragraphs = [parse_paragraph(document, para) for para in footnote.xpath('.//w:p', namespaces=NAMESPACES)]

        document.footnotes[footnote.attrib[_name('{{{w}}}id')]] = paragraphs

def parse_footnotes(document, xmlcontent):
    """Parse footnotes document.

    Footnotes are defined in file 'footnotes.xml'
    """
    footnotes = {}
    for node in document.xpath('//footnote'):
        footnote_id = node.get('id')
        if footnote_id is None:
            continue
        footnotes[footnote_id] = node.text
    return footnotes

