def reverse(self, points, **kwargs):
        """
        General method for reversing addresses, either a single address or
        multiple.

        *args should either be a longitude/latitude pair or a list of
        such pairs::

        >>> multiple_locations = reverse([(40, -19), (43, 112)])
        >>> single_location = reverse((40, -19))

        """
        if isinstance(points, list):
            return self.batch_reverse(points, **kwargs)

        if self.order == "lat":
            x, y = points
        else:
            y, x = points
        return self.reverse_point(x, y, **kwargs)

def reverse(self, points, **kwargs):
        """
        General method for reversing addresses, either a single address or
        multiple.

        *args should either be a longitude/latitude pair or a list of
        such pairs::

        >>> multiple_locations = reverse([(40, -19), (43, 112)])
        >>> single_location = reverse((40, -19))

        """
        if isinstance(points, list):
            return self._reverse_multiple(points, **kwargs)
        else:
            return self._reverse_single(points, **kwargs)

def from_requirement(cls, provider, requirement, parent):
        """Build an instance from a requirement.
        """
        candidates = provider.find_matches(requirement)
        if not candidates:
            raise NoVersionsAvailable(requirement, parent)
        return cls(
            candidates=candidates,
            information=[RequirementInformation(requirement, parent)],
        )

def from_requirement(cls, provider, requirement, parent):
        """Build an instance from a requirement.
        """
        if isinstance(requirement, Requirement):
            return cls(provider, requirement, parent)
        elif isinstance(requirement, str):
            return cls(provider, Requirement(requirement), parent)
        else:
            raise TypeError(
                "Requirement must be a Requirement or a string, not %s"
                % type(requirement).__name__
            )

