def first(iterable = None, *, name = None, metric = call_default):
    """Measure time elapsed to produce first item of an iterable

    :arg iterable: any iterable
    :arg function metric: f(name, 1, time)
    :arg str name: name for the metric
    """
    if iterable is None:
        return _first_decorator(name, metric)
    else:
        return _do_first(iterable, name, metric)

def first(iterable = None, *, name = None, metric = call_default):
    """Measure time elapsed to produce first item of an iterable

    :arg iterable: any iterable
    :arg function metric: f(name, 1, time)
    :arg str name: name for the metric
    """
    if name is None:
        name = 'first'
    if metric is None:
        metric = call_default
    if iterable is None:
        iterable = range(1000000)
    start = time.time()
    for item in iterable:
        pass
    metric(name, 1, time.time() - start)

def is_class(data):
    """
    checks that the data (which is a string, buffer, or a stream
    supporting the read method) has the magic numbers indicating it is
    a Java class file. Returns False if the magic numbers do not
    match, or for any errors.
    """
    if isinstance(data, str):
        data = data.encode('utf-8')
    if isinstance(data, bytes):
        data = io.BytesIO(data)
    if not hasattr(data,'read'):
        raise TypeError('data must be a string, buffer, or a stream '
                       'supporting the read method')
    magic = data.read(4)
    if magic == b'\xca\xfe\xba\xbe':
        return True
    if magic == b'\xca\xfe\xbb\xbe':
        return False
    raise ValueError('Invalid magic number: %r' % magic)

