async def pull_metrics(self, event_fn, loop=None):
        """
        Method called by core.
        Should not be overwritten.
        """
        if loop is None:
            loop = asyncio.get_event_loop()

        while True:
            try:
                await event_fn(self.metrics)
            except Exception as e:
                logger.exception(e)
            await asyncio.sleep(self.pull_interval)

def from_code(cls, code, **kw):
        """Construct a ``TChannelError`` instance from an error code.

        This will return the appropriate class type for the given code.
        """
        if code == TChannelError.INVALID_REQUEST:
            return InvalidRequest(**kw)
        elif code == TChannelError.INVALID_ARGUMENT:
            return InvalidArgument(**kw)
        elif code == TChannelError.NOT_FOUND:
            return NotFound(**kw)
        elif code == TChannelError.ALREADY_EXISTS:
            return AlreadyExists(**kw)
        elif code == TChannelError.PERMISSION_DENIED:
            return PermissionDenied(**kw)
        elif code == TChannelError.RESOURCE_EXHAUSTED:
            return ResourceExhausted(**kw)
        elif code == TChannelError.FAILED_PRECONDITION:
            return FailedPrecondition(**kw)
        elif code == TChannelError.ABORTED:
            return Aborted(**kw)
        elif code == TChannelError.OUT_OF_RANGE:
            return OutOfRange(**kw)
        elif code == TChannelError.UNIMPLEMENTED:
            return Unimplemented(**kw)
        elif code == TChannelError.INTERNAL:
            return Internal(**kw)
        elif code == TChannelError.UNAVAILABLE:
            return Unavailable(**kw)
        elif code == TChannelError.DATA_LOSS:
            return DataLoss(**kw)
        elif code == TChannelError.UNAUTHENTICATED:
            return Unauthenticated(**kw)
        else:
            return TChannelError(code, **kw)

def _get_value(context, key):
    """
    Retrieve a key's value from a context item.

    Returns _NOT_FOUND if the key does not exist.

    The ContextStack.get() docstring documents this function's intended behavior.

    """
