        # type: (str) -> Dict[str, Any]
        """Return the function policy for a lambda function.

        This function will extract the policy string as a json document
        and return the json.loads(...) version of the policy.

        """
        client = self._client('lambda')
        try:
            policy = client.get_policy(FunctionName=function_name)
            return json.loads(policy['Policy'])
        except client.exceptions.ResourceNotFoundException:
            return {'Statement': []}

def cast(s):
    """
    Cast a basestring to a more appropriate type.
    Example::
        >>> from yaxil import cast
        >>> type(cast("999"))
        <type 'int'>

    :param s: String
    :type s: basestring
    :returns: Casted string
    :rtype: int|float|str
    """
    if not isinstance(s, basestring):
        raise TypeError("argument must be a string")
    for test in [int, float, str]:
        try:
            return test(s)
        except ValueError:
            continue
    return str(s)

def cast(s):
    """
    Cast a basestring to a more appropriate type.
    Example::
        >>> from yaxil import cast
        >>> type(cast("999"))
        <type 'int'>

    :param s: String
    :type s: basestring
    :returns: Casted string
    :rtype: int|float|str
    """
    try:
        return int(s)
    except ValueError:
        try:
            return float(s)
        except ValueError:
            return s

def _bracket_dim_suggest(self, variable):
        """Returns a dictionary of documentation for helping complete the
        dimensions of a variable."""
        if variable is not None:
            #Look for <dimension> descriptors that are children of the variable
            #in its docstrings.
            dims = variable.doc_children("dimension", ["member", "parameter", "local"])
            descript = str(variable)
            if len(dims) > 0:
                descript += " | " + " ".join([DocElement.format_dimension(d) for d in dims])

            return dict(
                params=[variable.dimension],
                index=0,
                call_name=variable.name,
                description=descript,
            )        
        else:
            return []

def _update_rotation(self, event):
        """Update rotation parmeters based on mouse movement"""
        if event.button == 1:
            self.rotation_x += event.x
            self.rotation_y += event.y
        elif event.button == 3:
            self.rotation_x -= event.x
            self.rotation_y -= event.y

def toJson(protoObject, indent=None):
