async def release(self) -> None:
        """Like read(), but reads all the data to the void."""
        if self._at_eof:
            return
        while not self._at_eof:
            await self.read_chunk(self.chunk_size)

def handle_request(self, environ, start_response):
        """Retrieves the route handler and calls the handler returning its the response

        :param dict environ: The WSGI environment dictionary for the request
        :param start_response:
        :return: The WbResponse for the request
        :rtype: WbResponse
        """
        urls = self.url_map.bind_to_environ(environ)
        try:
            endpoint, args = urls.match()
            # store original script_name (original prefix) before modifications are made
            environ['pywb.app_prefix'] = environ.get('SCRIPT_NAME')

            response = endpoint(environ, **args)
            return response(environ, start_response)

        except HTTPException as e:
            redir = self._check_refer_redirect(environ)
            if redir:
                return redir(environ, start_response)

            return e(environ, start_response)

        except Exception as e:
            if self.debug:
                traceback.print_exc()

            response = self.rewriterapp._error_response(environ, 'Internal Error: ' + str(e), '500 Server Error')
            return response(environ, start_response)

def parse_metadata(cls, obj, xml):
        """ Parse a resource to feed the object

        :param obj: Obj to set metadata of
        :type obj: XmlCtsTextMetadata
        :param xml: An xml representation object
        :type xml: lxml.etree._Element
        """

        for child in xml.xpath("ti:description", namespaces=XPATH_NAMESPACES):
            lg = child.get("{http://www.w3.org/XML/1998/namespace}lang")
            if lg is not None:
                obj.set_cts_property("description", child.text, lg)

        for child in xml.xpath("ti:label", namespaces=XPATH_NAMESPACES):
            lg = child.get("{http://www.w3.org/XML/1998/namespace}lang")
            if lg is not None:
                obj.set_cts_property("label", child.text, lg)

        obj.citation = cls.CLASS_CITATION.ingest(xml, obj.citation, "ti:online/ti:citationMapping/ti:citation")

        # Added for commentary
        for child in xml.xpath("ti:about", namespaces=XPATH_NAMESPACES):
            obj.set_link(RDF_NAMESPACES.CTS.term("about"), child.get('urn'))

        _parse_structured_metadata(obj, xml)

def query(self, asql, logger=None):
        """
        Execute an ASQL file and return the result of the first SELECT statement.

        :param asql:
        :param logger:
        :return:
        """
        import sqlparse
        from ambry.mprlib.exceptions import BadSQLError
        from ambry.bundle.asql_parser import process_sql
        from ambry.orm.exc import NotFoundError

        if not logger:
            logger = self._library.logger

        rec = process_sql(asql, self._library)

        for drop in reversed(rec.drop):

            if drop:
                connection = self._backend._get_connection()
                cursor = self._backend.query(connection, drop, fetch=False)
                cursor.close()

        for vid in rec.materialize:
            logger.debug('Materialize {}'.format(vid))
            self.materialize(vid, logger=logger)

        for vid in rec.install:
            logger.debug('Install {}'.format(vid))

            self.install(vid, logger=logger)


        for statement in rec.statements:

            statement = statement.strip()

            logger.debug("Process statement: {}".format(statement[:60]))

            if statement.lower().startswith('create'):
                logger.debug('    Create {}'.format(statement))
                connection = self._backend._get_connection()
                cursor = self._backend.query(connection, statement, fetch=False)

                cursor.close()

            elif statement.lower().startswith('select'):
                logger.debug('Run query {}'.format(statement))
                connection = self._backend._get_connection()
                return self._backend.query(connection, statement, fetch=False)

        for table_or_vid, columns in rec.indexes:

            logger.debug('Index {}'.format(table_or_vid))

            try:
                self.index(table_or_vid, columns)
            except NotFoundError as e:
                # Comon when the index table in's a VID, so no partition can be found.

                logger.debug('Failed to index {}; {}'.format(vid, e))
            except Exception as e:
                logger.error('Failed to index {}; {}'.format(vid, e))

        # A fake cursor that can be closed and iterated
        class closable_iterable(object):
            def close(self):
                pass

            def __iter__(self):
                pass

        return closable_iterable()

def query(self, asql, logger=None):
        """
        Execute an ASQL file and return the result of the first SELECT statement.

        :param asql:
        :param logger:
        :return:
        """
        if logger is None:
            logger = logging.getLogger(__name__)
        logger.debug('Querying ASQL: %s' % asql)
        try:
            return self.client.query(asql)
        except Exception as e:
            logger.error('Error querying ASQL: %s' % e)
            raise

