def on_shutdown(self, callback: callable, polling=True, webhook=True):
        """
        Register a callback for the shutdown process

        :param callback:
        :param polling: use with polling
        :param webhook: use with webhook
        """
        self._check_frozen()
        if not webhook and not polling:
            warn('This action has no effect!', UserWarning)
            return

        if isinstance(callback, (list, tuple, set)):
            for cb in callback:
                self.on_shutdown(cb, polling, webhook)
            return

        if polling:
            self._on_shutdown_polling.append(callback)
        if webhook:
            self._on_shutdown_webhook.append(callback)

def assert_valid(self, instance, value=None):
        """Returns True if the Property is valid on a HasProperties instance

        Raises a ValueError if the value required and not set, not valid,
        not correctly coerced, etc.

        .. note::

            Unlike :code:`validate`, this method requires instance to be
            a HasProperties instance; it cannot be None.
        """
        if value is None:
            value = instance.get(self.name)
        if value is None:
            if self.required:
                raise ValueError(
                    "Property '%s' is required on %s" % (self.name, instance)
                )
            else:
                return
        if not self.validate(value):
            raise ValueError(
                "Property '%s' is not valid on %s" % (self.name, instance)
            )
        return True

def day(year, month, day, home=None, away=None):
    """Return a list of games for a certain day.

    If the home and away team are the same,
    it will return the game(s) for that team.
    """
    if home and away:
        return [g for g in games(year, month) if (g.home == home and g.away == away) or (g.home == away and g.away == home)]
    else:
        return [g for g in games(year, month) if g.date == date(year, month, day)]

def update_progress(self, progress, prefix=''):
        """
        Print a progress bar for longer-running scripts.

        The progress value is a value between 0.0 and 1.0. If a prefix is
        present, it will be printed before the progress bar.
        """
        bar_length = 20
        if isinstance(progress, int):
            progress = float(progress)
        if not isinstance(progress, float):
            progress = 0
        if progress < 0:
            progress = 0
        if progress >= 1:
            progress = 1

        block = int(round(bar_length * progress))

        if prefix:
            print(prefix, end='')
        print('\r[{0}] {1:.1f}%'.format('#' * block + '-' * (bar_length - block), progress * 100), end='')
        if progress >= 1:
            print()

