                                  namespace=namespace or self.namespace,
                                  callback=callback)

def send(self, data, room=None, include_self=True, namespace=None,
             callback=None):
        """Send a message to one or more connected clients."""
        if room is None:
            room = self.room_name
        if namespace is None:
            namespace = self.namespace
        if callback is None:
            callback = self.callback
        if not isinstance(data, dict):
            data = {'message': data}
        if not isinstance(room, list):
            room = [room]
        if not isinstance(data, dict):
            data = {'message': data}
        if include_self:
            room.append(self.request.session.session_key)
        self.send_packet(data, room, namespace, callback)

