def parse_port_from_tensorboard_output(tensorboard_output: str) -> int:
    """
    Parse tensorboard port from its outputted message.

    :param tensorboard_output: Output message of Tensorboard
    in format TensorBoard 1.8.0 at http://martin-VirtualBox:36869
    :return: Returns the port TensorBoard is listening on.
    :raise UnexpectedOutputError
    """
    for line in tensorboard_output.splitlines():
        if "TensorBoard" in line:
            return int(line.split(" ")[-1])
    raise UnexpectedOutputError("Could not find port in Tensorboard output.")

def loss_maps(curves, conditional_loss_poes):
    """
    :param curves: an array of loss curves
    :param conditional_loss_poes: a list of conditional loss poes
    :returns: a composite array of loss maps with the same shape
    """
    loss_maps = []
    for curve in curves:
        loss_map = np.zeros(curve.shape)
        for i in range(len(conditional_loss_poes)):
            loss_map[curve == i] = conditional_loss_poes[i]
        loss_maps.append(loss_map)
    return np.array(loss_maps)

def gethost(self, ip_addr):
        """
        Do reverse lookup on an ip address
        """
        # Handle silly fake ipv6 addresses
        try:
            if ip_addr[:7] == '::ffff:':
                ip_addr = ip_addr[7:]
        except TypeError:
            pass

        if ip_addr[0] in string.letters:
            return ip_addr

        try:
            return self.hostsmap[ip_addr]
        except KeyError:
            pass

        try:
            name = socket.gethostbyaddr(ip_addr)[0]
        except socket.error:
            name = ip_addr

        self.hostsmap[ip_addr] = name
        return name

def gethost(self, ip_addr):
        """
        Do reverse lookup on an ip address
        """
        try:
            return socket.gethostbyaddr(ip_addr)[0]
        except socket.herror:
            return None

def getReffs(self, level: int=1, subreference: CtsReference=None) -> CtsReferenceSet:
        """ CtsReference available at a given level

        :param level: Depth required. If not set, should retrieve first encountered level (1 based)
        :param subreference: Subreference (optional)
        :returns: List of levels
        """

        if not subreference and hasattr(self, "reference"):
            subreference = self.reference
        elif subreference and not isinstance(subreference, CtsReference):
            subreference = CtsReference(subreference)

        return self.getValidReff(level=level, reference=subreference)

def getReffs(self, level: int=1, subreference: CtsReference=None) -> CtsReferenceSet:
        """ CtsReference available at a given level

        :param level: Depth required. If not set, should retrieve first encountered level (1 based)
        :param subreference: Subreference (optional)
        :returns: List of levels
        """
        if subreference is None:
            subreference = self.reference
        return self.reference.getReffs(level, subreference)

