def validateTagAttributes(self, attribs, element):
		"""docstring for validateTagAttributes"""
		out = {}
		if element not in _whitelist:
			return out
		whitelist = _whitelist[element]
		for attribute in attribs:
			value = attribs[attribute]
			if attribute not in whitelist:
				continue
			# Strip javascript "expression" from stylesheets.
			# http://msdn.microsoft.com/workshop/author/dhtml/overview/recalc.asp
			if attribute == u'style':
				value = self.checkCss(value)
				if value == False:
					continue
			elif attribute == u'id':
				value = self.escapeId(value)
			# If this attribute was previously set, override it.
			# Output should only have one attribute of each name.
			out[attribute] = value
		return out

def validateTagAttributes(self, attribs, element):
		"""docstring for validateTagAttributes"""
		if element.tag == 'a':
			if 'href' not in attribs:
				raise ValidationError('Tag <a> must have an attribute href')
		elif element.tag == 'img':
			if'src' not in attribs:
				raise ValidationError('Tag <img> must have an attribute src')

def calcDeviationLimits(value, tolerance, mode):
    """Returns the upper and lower deviation limits for a value and a given
    tolerance, either as relative or a absolute difference.

    :param value: can be a single value or a list of values if a list of values
        is given, the minimal value will be used to calculate the lower limit
        and the maximum value to calculate the upper limit
    :param tolerance: a number used to calculate the limits
    :param mode: either ``absolute`` or ``relative``, specifies how the
        ``tolerance`` should be applied to the ``value``.
    """
    if mode == "absolute":
        return value - tolerance, value + tolerance
    elif mode == "relative":
        return value * (1 - tolerance), value * (1 + tolerance)
    else:
        raise ValueError("mode must be either 'absolute' or'relative'")

