def deprecated(context):
    """Handle deprecated context input."""
    if context is None:
        return None
    if isinstance(context, dict):
        return context
    if isinstance(context, str):
        return {"deprecated": context}
    raise TypeError(f"context must be a dict or str, not {type(context)}")

def log_background_messages(self, name=None):
        """Forwards messages logged on background to Robot Framework log.

        By default forwards all messages logged by all threads, but can be
        limited to a certain thread by passing thread's name as an argument.

        Logged messages are removed from the message storage.
        """
        if name is None:
            name = 'all'
        if name == 'all':
            for thread in self.threads:
                self.log_background_messages(thread.name)
        else:
            if name in self.threads:
                thread = self.threads[name]
                for message in thread.messages:
                    self.log_message(message)
                    thread.messages.remove(message)

def differing_functions(self):
        """
        :returns: A list of function matches that appear to differ
        """
        different_funcs = []
        for (func_a, func_b) in self.function_matches:
            if not self.functions_probably_identical(func_a, func_b):
                different_funcs.append((func_a, func_b))
        return different_funcs

def in6_get6to4Prefix(addr):
    """
    Returns the /48 6to4 prefix associated with provided IPv4 address
    On error, None is returned. No check is performed on public/private
    status of the address
    """
    try:
        addr = ipaddress.ip_address(addr)
    except ValueError:
        return None
    if addr.version!= 4:
        return None
    if addr.is_private:
        return None
    return addr.exploded.replace('0000', '2002')

