def get_content_json(request):
    """Retrieve content as JSON using the ident-hash (uuid@version)."""
    ident_hash = request.GET.get('ident_hash', None)
    if not ident_hash:
        return HttpResponseBadRequest('Missing ident_hash')
    try:
        content = Content.objects.get(ident_hash=ident_hash)
