        return HttpResponseNotFound('Content not found')
    return HttpResponse(content.content_json, content_type='application/json')

def close(self):
        """Forcibly close all connections.

        This instance will not be usable after calling this method.
        """
        for connection in self.ready:
            connection.close()

        for connection in self.busy:
            connection.close()

        self._closed = True

def clear_screen(mode=2):
    """ Clear the terminal/console screen. (Also aliased to clear.)

        Arguments:

            mode:  | 0 | 'forward'   - Clear cursor to end of screen, cursor stays.
                   | 1 | 'backward'  - Clear cursor to beginning of screen, ""
                   | 2 | 'full'      - Clear entire visible screen, cursor to 1,1.
                   | 3 | 'history'   - Clear entire visible screen and scrollback
                                       buffer (xterm).
    """
    if mode == 0:
        print('\033[F', end='')
    elif mode == 1:
        print('\033[H', end='')
    elif mode == 2:
        print('\033[2J\033[H', end='')
    elif mode == 3:
        print('\033[2J\033[H\033[?3;0c', end='')
    else:
        raise ValueError('Invalid mode.')

def estimate_density(DATA_PATH, feature_size):
    """sample 10 times of a size of 1000 for estimating the density of the sparse dataset"""
    if not os.path.exists(DATA_PATH):
        raise Exception("Data is not there!")
    density = []
    P = 0.01
    for _ in range(10):
        num_non_zero = 0
        num_sample = 0
        with open(DATA_PATH) as f:
            for line in f:
                if (random.random() < P):
                    num_non_zero += len(line.split(" ")) - 1
                    num_sample += 1
        density.append(num_non_zero * 1.0 / (feature_size * num_sample))
    return sum(density) / len(density)

def estimate_density(DATA_PATH, feature_size):
    """sample 10 times of a size of 1000 for estimating the density of the sparse dataset"""
    density_list = []
    for i in range(10):
        data = np.load(DATA_PATH)
        data = data[:1000, :feature_size]
        density_list.append(estimate_density_of_data(data))
    return np.mean(density_list)

def _normalize_codec(codec, _cache={}):
    """Raises LookupError"""

    try:
        return _cache[codec]
    except KeyError:
        _cache[codec] = codecs.lookup(codec).name
        return _cache[codec]

def _normalize_codec(codec, _cache={}):
    """Raises LookupError"""
    if codec in _cache:
        return _cache[codec]
    if codec in _codec_aliases:
        codec = _codec_aliases[codec]
    if codec not in _codecs:
        raise LookupError(codec)
    _cache[codec] = codec
    return codec

def run(self):
        """Required by flake8
        Will be called after add_options and parse_options.

        Yields:
            tuple: (int, int, str, type) the tuple used by flake8 to construct a violation
        """

        if len(self.filename_checks) == 0:
            message = "N401 no configuration found for {}, " \
                      "please provide filename configuration in a flake8 config".format(self.name)
            yield (0, 0, message, type(self))

        rule_funcs = [rules.rule_n5xx]

        for rule_func in rule_funcs:
            for rule_name, configured_rule in self.filename_checks.items():
                for err in rule_func(self.filename, rule_name, configured_rule, type(self)):
                    yield err

