def _padding(self, image, geometry, options):
        """
        Pads the image
        """
        if geometry is None:
            return image

        geometry = geometry.split('x')
        if len(geometry)!= 2:
            raise ValueError('Invalid geometry: %s' % geometry)

        width, height = geometry

        if width == '0':
            width = image.size[0]
        else:
            width = int(width)

        if height == '0':
            height = image.size[1]
        else:
            height = int(height)

        if width < image.size[0]:
            raise ValueError('Invalid geometry: requested width %s is smaller than image width %s' % (width, image.size[0]))

        if height < image.size[1]:
            raise ValueError('Invalid geometry: requested height %s is smaller than image height %s' % (height, image.size[1]))

        if width == image.size[0] and height == image.size[1]:
            return image

        if options.get('transparent', False):
            background = Image.new('RGBA', (width, height), (0, 0, 0, 0))
        else:
            background = Image.new('RGB', (width, height), (255, 255, 255))

        offset_x = int((width - image.size[0]) / 2)
        offset_y = int((height - image.size[1]) / 2)

        background.paste(image, (offset_x, offset_y))
        return background

