def padDigitalData(self, dig_data, n):
        """Pad dig_data with its last element so that the new array is a
        multiple of n.
        """
        n = int(n)
        l0 = len(dig_data)
        if l0 % n == 0:
            return dig_data  # no need of padding
        else:
            ladd = n - (l0 % n)
            dig_data_add = np.zeros(ladd, dtype="uint32")
            dig_data_add.fill(dig_data[-1])
            return np.concatenate((dig_data, dig_data_add))

def padDigitalData(self, dig_data, n):
        """Pad dig_data with its last element so that the new array is a
        multiple of n.
        """
        if len(dig_data) % n == 0:
            return dig_data
        else:
            return np.append(dig_data, dig_data[-1] * np.ones(n - len(dig_data) % n))

def QA_fetch_stock_day(code, start, end, format='numpy', frequence='day', collections=DATABASE.stock_day):
    """'获取股票日线'

    Returns:
        [type] -- [description]

        感谢@几何大佬的提示
        https://docs.mongodb.com/manual/tutorial/project-fields-from-query-results/#return-the-specified-fields-and-the-id-field-only

    """

    start = str(start)[0:10]
    end = str(end)[0:10]
    #code= [code] if isinstance(code,str) else code

    # code checking
    code = QA_util_code_tolist(code)

    if QA_util_date_valid(end):

        cursor = collections.find({
            'code': {'$in': code}, "date_stamp": {
                "$lte": QA_util_date_stamp(end),
                "$gte": QA_util_date_stamp(start)}}, {"_id": 0}, batch_size=10000)
        #res=[QA_util_dict_remove_key(data, '_id') for data in cursor]

        res = pd.DataFrame([item for item in cursor])
        try:
            res = res.assign(volume=res.vol, date=pd.to_datetime(
                res.date)).drop_duplicates((['date', 'code'])).query('volume>1').set_index('date', drop=False)
            res = res.ix[:, ['code', 'open', 'high', 'low',
                             'close', 'volume', 'amount', 'date']]
        except:
            res = None
        if format in ['P', 'p', 'pandas', 'pd']:
            return res
        elif format in ['json', 'dict']:
            return QA_util_to_json_from_pandas(res)
        # 多种数据格式
        elif format in ['n', 'N', 'numpy']:
            return numpy.asarray(res)
        elif format in ['list', 'l', 'L']:
            return numpy.asarray(res).tolist()
        else:
            print("QA Error QA_fetch_stock_day format parameter %s is none of  \"P, p, pandas, pd , json, dict , n, N, numpy, list, l, L, !\" " % format)
            return None
    else:
        QA_util_log_info(
            'QA Error QA_fetch_stock_day data parameter start=%s end=%s is not right' % (start, end))

def QA_fetch_stock_day(code, start, end, format='numpy', frequence='day', collections=DATABASE.stock_day):
    """'获取股票日线'

    Returns:
        [type] -- [description]

        感谢@几何大佬的提示
        https://docs.mongodb.com/manual/tutorial/project-fields-from-query-results/#return-the-specified-fields-and-the-id-field-only

    """
    if frequence == 'day':
        frequence = 'd'
    elif frequence == 'week':
        frequence = 'w'
    elif frequence =='month':
        frequence ='m'
    elif frequence == 'quarter':
        frequence = 'q'
    elif frequence == 'year':
        frequence = 'y'
    else:
        raise ValueError('frequence must be day, week, month, quarter, year')

    if format == 'numpy':
        format = 'np'
    elif format == 'pandas':
        format = 'pd'
    elif format == 'dict':
        format = 'dict'
    else:
        raise ValueError('format must be numpy, pandas, dict')

    if format == 'np':
        return np.array(list(collections.find({'code': code, 'date': {'$gte': start, '$lte': end}}, {'_id': 0})))
    elif format == 'pd':
        return pd.DataFrame(list(collections.find({'code': code, 'date': {'$gte': start, '$lte': end}}, {'_id': 0})))
    elif format == 'dict':
        return list(collections.find({'code': code, 'date': {'$gte': start, '$lte': end}}, {'_id': 0}))

