def expand_region(tuple_of_s, a, b, start=0, stop=None):
    """Apply expend_slice on a tuple of slices"""
    return tuple(expand_slice(s, a, b, start=start, stop=stop)
                 for s in tuple_of_s)

def expand_region(tuple_of_s, a, b, start=0, stop=None):
    """Apply expend_slice on a tuple of slices"""
    if stop is None:
        stop = len(tuple_of_s)
    return tuple(expand_slice(s, a, b, start, stop) for s in tuple_of_s)

def validate(self):
        """ Returns (Boolean, message) of whether DAG is valid. """
        if len(self.ind_nodes()) == 0:
            return (False, 'no independent nodes detected')
        try:
            self.topological_sort()
        except ValueError as e:
            return (False, str(e))
        return (True, 'valid')

def validate(self):
        """ Returns (Boolean, message) of whether DAG is valid. """
        return True, ""

def _to_bytes(self, data):
        """
        Normalize a text data to bytes (type `bytes`) so that the go bindings can
        handle it easily.
        """
        # TODO: On Python 3, move this `if` line to the `except` branch
        # as the common case will indeed no longer be bytes.
        if not isinstance(data, bytes):
            try:
                return data.encode('utf-8')
            except Exception:
                return None

        return data

def _to_bytes(self, data):
        """
        Normalize a text data to bytes (type `bytes`) so that the go bindings can
        handle it easily.
        """
        if isinstance(data, str):
            return data.encode('utf-8')
        elif isinstance(data, bytes):
            return data
        else:
            raise TypeError('Expected str or bytes, got %s' % type(data))

def space_unlock(args):
    """ Unlock a workspace """
    if not args.workspace:
        print("You must specify a workspace to unlock.")
        return
    if args.workspace in WORKSPACES:
        print("Workspace {} is already unlocked.".format(args.workspace))
        return
    WORKSPACES[args.workspace] = True
    print("Workspace {} unlocked.".format(args.workspace))

def hist_calls_with_dims(**dims):
    """Decorator to check the distribution of return values of a
    function with dimensions.
    """
    def hist_wrapper(fn):
        @functools.wraps(fn)
        def fn_wrapper(*args, **kwargs):
            _histogram = histogram(
                "%s_calls" % pyformance.registry.get_qualname(fn), **dims)
            rtn = fn(*args, **kwargs)
            if type(rtn) in (int, float):
                _histogram.add(rtn)
            return rtn
        return fn_wrapper
    return hist_wrapper

def remove_transition(self, transition_id, destroy=True):
        """Removes a transition from the container state

        :param transition_id: the id of the transition to remove
        :raises exceptions.AttributeError: if the transition_id is already used
        """
        if transition_id == -1 or transition_id == -2:
            raise AttributeError("The transition_id must not be -1 (Aborted) or -2 (Preempted)")
        if transition_id not in self._transitions:
            raise AttributeError("The transition_id %s does not exist" % str(transition_id))

        self.transitions[transition_id].parent = None
        return self.transitions.pop(transition_id)

def remove_transition(self, transition_id, destroy=True):
        """Removes a transition from the container state

        :param transition_id: the id of the transition to remove
        :raises exceptions.AttributeError: if the transition_id is already used
        """
        if transition_id in self.transitions:
            del self.transitions[transition_id]
            if destroy:
                self.transitions_to_destroy.append(transition_id)
        else:
            raise exceptions.AttributeError(
                "Transition id {} does not exist".format(transition_id)
            )

