def to_feature(self, name=None, feature_type='misc_feature'):
        """Create a feature from the current object.

        :param name: Name for the new feature. Must be specified if the DNA
                     instance has no .name attribute.
        :type name: str
        :param feature_type: The type of feature (genbank standard).
        :type feature_type: str

        """
        if name is None:
            if hasattr(self, 'name'):
                name = self.name
            else:
                raise ValueError('No name specified for feature.')

        if feature_type =='misc_feature':
            return self._to_misc_feature(name)
        elif feature_type == 'CDS':
            return self._to_CDS(name)
        elif feature_type == 'gene':
            return self._to_gene(name)
        elif feature_type == 'tRNA':
            return self._to_tRNA(name)
        elif feature_type == 'rRNA':
            return self._to_rRNA(name)
        elif feature_type == 'ncRNA':
            return self._to_ncRNA(name)
        elif feature_type == 'tmRNA':
            return self._to_tmRNA(name)
        elif feature_type =='misc_RNA':
            return self._to_misc_RNA(name)
        elif feature_type == 'exon':
            return self._to_exon(name)
        elif feature_type == 'intron':
            return self._to_intron(name)
        elif feature_type == 'C_region':
            return self._to_C_region(name)
        elif feature_type == 'V_region':
            return self._to_V_region(name)
        elif feature_type == 'J_region':
            return self._to_J_region(name)
        elif feature_type == 'D_segment':
            return self._to_D_segment(name)
        elif feature_type == 'V_segment':
            return self._to_V_segment(name)
        elif feature_type == 'J_segment':
            return self._to_J_segment(name)
        elif feature_type == '3_prime_UTR':
            return self._to_3_prime_UTR(name)
        elif feature_type == '5_prime_UTR':
            return self._to_5_prime_UTR(name)
        elif feature_type =='mat_peptide':
            return self._to_mat_peptide(name)
        elif feature_type =='sig_peptide':
            return self._to_sig_peptide(name)
        elif feature_type == 'transit_peptide':
            return self._to_transit_

def clean(self, value, initial=None):
        """
        Most part of this method is a copy of
        django.forms.MultiValueField.clean, with the exception of initial
        value handling (this need for correct processing FileField's).
        All original comments saved.
        """
        if initial is None:
            initial = [None for x in range(0, len(value))]
        else:
            if not isinstance(initial, list):
                initial = self.widget.decompress(initial)

        clean_data = []
        errors = []
        if not value or isinstance(value, (list, tuple)):
            if (not value or not [v for v in value if
                                  v not in self.empty_values]) \
                    and (not initial or not [v for v in initial if
                                             v not in self.empty_values]):
                if self.required:
                    raise ValidationError(self.error_messages['required'],
                                          code='required')
        else:
            raise ValidationError(self.error_messages['invalid'],
                                  code='invalid')
        for i, field in enumerate(self.fields):
            try:
                field_value = value[i]
            except IndexError:
                field_value = None
            try:
                field_initial = initial[i]
            except IndexError:
                field_initial = None

            if field_value in self.empty_values and \
                    field_initial in self.empty_values:
                if self.require_all_fields:
                    # Raise a 'required' error if the MultiValueField is
                    # required and any field is empty.
                    if self.required:
                        raise ValidationError(self.error_messages['required'],
                                              code='required')
                elif field.required:
                    # Otherwise, add an 'incomplete' error to the list of
                    # collected errors and skip field cleaning, if a required
                    # field is empty.
                    if field.error_messages['incomplete'] not in errors:
                        errors.append(field.error_messages['incomplete'])
                    continue
            try:
                clean_data.append(field.clean(field_value, field_initial))
            except ValidationError as e:
                # Collect all validation errors in a single list, which we'll
                # raise at the end of clean(), rather than raising a single
                # exception for the first error we encounter. Skip duplicates.
                errors.extend(m for m in e.error_list if m not in errors)
        if errors:
            raise ValidationError(errors)

        out = self.compress(clean_data)
        self.validate(out)
        self.run_validators(out)
        return out

def clean(self, value, initial=None):
        """
        Most part of this method is a copy of
        django.forms.MultiValueField.clean, with the exception of initial
        value handling (this need for correct processing FileField's).
        All original comments saved.
        """
        if value is None:
            return None
        if isinstance(value, (list, tuple)):
            return [self.clean_value(v, initial) for v in value]
        return self.clean_value(value, initial)

def block(self, other_user_id):
        """Block the given user.

        :param str other_user_id: the ID of the user to block
        :return: the block created
        :rtype: :class:`~groupy.api.blocks.Block`
        """
        params = {'user': self.user_id, 'otherUser': other_user_id}
        response = self.session.post(self.url, params=params)
        block = response.data['block']
        return Block(self, **block)

def get_dictkey(In, k, dtype):
    """
        returns list of given key (k)  from input list of dictionaries (In) in data type dtype.  uses command:
        get_dictkey(In,k,dtype).  If dtype =="", data are strings; if "int", data are integers; if "f", data are floats.
    """

    Out = []
    for d in In:
        if dtype == '':
            Out.append(d[k])
        if dtype == 'f':
            if d[k] == "":
                Out.append(0)
            elif d[k] == None:
                Out.append(0)
            else:
                Out.append(float(d[k]))
        if dtype == 'int':
            if d[k] == "":
                Out.append(0)
            elif d[k] == None:
                Out.append(0)
            else:
                Out.append(int(d[k]))
    return Out

def get_dictkey(In, k, dtype):
    """
        returns list of given key (k)  from input list of dictionaries (In) in data type dtype.  uses command:
        get_dictkey(In,k,dtype).  If dtype =="", data are strings; if "int", data are integers; if "f", data are floats.
    """
    if dtype == "":
        return [In[i][k] for i in range(len(In))]
    elif dtype == "int":
        return [int(In[i][k]) for i in range(len(In))]
    elif dtype == "f":
        return [float(In[i][k]) for i in range(len(In))]
    else:
        print("ERROR: dtype must be '', 'int', or 'f'")
        return []

