def keys(self, prefix=None, delimiter=None):
        """
        :param prefix:  NOT A STRING PREFIX, RATHER PATH ID PREFIX (MUST MATCH TO NEXT "." OR ":")
        :param delimiter:  TO GET Prefix OBJECTS, RATHER THAN WHOLE KEYS
        :return: SET OF KEYS IN BUCKET, OR
        """
        if delimiter:
            # WE REALLY DO NOT GET KEYS, BUT RATHER Prefix OBJECTS
            # AT LEAST THEY ARE UNIQUE
            candidates = [k.name.rstrip(delimiter) for k in self.bucket.list(prefix=prefix, delimiter=delimiter)]
        else:
            candidates = [strip_extension(k.key) for k in self.bucket.list(prefix=prefix)]

        if prefix == None:
            return set(c for c in candidates if c != "0.json")
        else:
            return set(k for k in candidates if k == prefix or k.startswith(prefix + ".") or k.startswith(prefix + ":"))

def keys(self, prefix=None, delimiter=None):
        """
        :param prefix:  NOT A STRING PREFIX, RATHER PATH ID PREFIX (MUST MATCH TO NEXT "." OR ":")
        :param delimiter:  TO GET Prefix OBJECTS, RATHER THAN WHOLE KEYS
        :return: SET OF KEYS IN BUCKET, OR
        """
        if prefix is None:
            return self.bucket.keys()
        else:
            if delimiter is None:
                return self.bucket.keys(prefix=prefix)
            else:
                return self.bucket.keys(prefix=prefix, delimiter=delimiter)

def _to_xml(self, xml, data, key=None):
        """ Recursively convert the data into xml.

        This function was originally copied from the
        `Piston project <https://bitbucket.org/jespern/django-piston/>`_
        It has been modified since.

        :param xml: the xml document
        :type xml: SimplerXMLGenerator
        :param data: data to be formatted
        :param key: name of the parent element (for root this is ``None``)
        """
        if isinstance(data, dict):
            for key, value in data.items():
                if isinstance(value, (list, tuple)):
                    for item in value:
                        self._to_xml(xml, item, key)
                else:
                    self._to_xml(xml, value, key)
        elif isinstance(data, (list, tuple)):
            for item in data:
                self._to_xml(xml, item, key)
        elif isinstance(data, basestring):
            if key is None:
                xml.characters(data)
            else:
                xml.startElement(key, {})
                xml.characters(data)
                xml.endElement(key)
        elif isinstance(data, (int, long, float)):
            if key is None:
                xml.characters(str(data))
            else:
                xml.startElement(key, {})
                xml.characters(str(data))
                xml.endElement(key)
        elif isinstance(data, bool):
            if key is None:
                xml.characters(str(data))
            else:
                xml.startElement(key, {})
                xml.characters(str(data))
                xml.endElement(key)
        elif data is None:
            if key is None:
                xml.characters('')
            else:
                xml.startElement(key, {})
                xml.characters('')
                xml.endElement(key)
        else:
            if key is None:
                xml.characters(str(data))
            else:
                xml.startElement(key, {})
                xml.characters(str(data))
                xml.endElement(key)

