def parameterized_send(self, request, parameter_list):
        """Send batched requests for a list of parameters

        Args:
            request (str): Request to send, like "%s.*?\n"
            parameter_list (list): parameters to format with, like
                ["TTLIN", "TTLOUT"]

        Returns:
            dict: {parameter: response_queue}
        """
        responses = {}
        for parameter in parameter_list:
            responses[parameter] = self.send(request % parameter)
        return responses

def remove_search_paths(self, path_type, paths, target_name=None, configuration_name=None):
        """
        Removes the given search paths from the path_type section of the target on the configurations
        :param path_type: name of the path type to be removed the values from
        :param paths: A string or array of strings
        :param target_name: Target name or list of target names to remove the flag from or None for every target
        :param configuration_name: Configuration name to add the flag to or None for every configuration
        :return: void
        """
        if not isinstance(paths, list):
            paths = [paths]

        if target_name is None:
            target_names = self.get_target_names()
        else:
            target_names = [target_name]

        if configuration_name is None:
            configuration_names = self.get_configuration_names()
        else:
            configuration_names = [configuration_name]

        for target_name in target_names:
            for configuration_name in configuration_names:
                target = self.get_target(target_name, configuration_name)
                if target is None:
                    continue

                for path in paths:
                    if path_type in target:
                        target[path_type].remove(path)

def _repr(self, *args, **kwargs):
        """Return a __repr__ string from the arguments provided to __init__.

        @param args: list of arguments to __init__
        @param kwargs: dictionary of keyword arguments to __init__
        @return: __repr__ string

        """
        # Remove unnecessary empty keywords arguments and sort the arguments
        kwargs = {k: v for k, v in kwargs.items() if v is not None}
        kwargs = OrderedDict(sorted(kwargs.items()))

        # Build the __repr__ string pieces
        args_repr = ', '.join(repr(arg) for arg in args)
        kwargs_repr = ', '.join(k + '=' + repr(v) for k, v in kwargs.items())
        if args_repr and kwargs_repr:
            kwargs_repr = ', ' + kwargs_repr
        name = self.__class__.__name__

        return "{}({}{})".format(name, args_repr, kwargs_repr)

