def player_mode_stats(self, player_handle, game_mode=constants.GAME_MODE_WILDCARD, game_region=constants.GAME_REGION_WILDCARD):
        """Returns the stats for a particular mode of play,
        accepts solo, duo and squad.  Will return both regional
        and global stats.  Default gamemode is solo
        by Zac: Add parameter game_region to extract player stats by region directly
        """
        if game_mode == constants.GAME_MODE_WILDCARD:
            game_mode = self.default_game_mode
        if game_region == constants.GAME_REGION_WILDCARD:
            game_region = self.default_game_region
        return self.request_json(
            'https://api.steampowered.com/ISteamUserStats/GetUserStatsForGame/v0002/?appid={}&key={}&steamid={}&count={}&name={}&format=json'.format(
                self.appid, self.api_key, player_handle, game_mode, game_region))

def _get_ax_freq(ax):
    """
    Get the freq attribute of the ax object if set.
    Also checks shared axes (eg when using secondary yaxis, sharex=True
    or twinx)
    """
    ax_freq = getattr(ax, 'freq', None)
    if ax_freq is None:
        # check for left/right ax in case of secondary yaxis
        if hasattr(ax, 'left_ax'):
            ax_freq = getattr(ax.left_ax, 'freq', None)
        elif hasattr(ax, 'right_ax'):
            ax_freq = getattr(ax.right_ax, 'freq', None)
    if ax_freq is None:
        # check if a shared ax (sharex/twinx) has already freq set
        shared_axes = ax.get_shared_x_axes().get_siblings(ax)
        if len(shared_axes) > 1:
            for shared_ax in shared_axes:
                ax_freq = getattr(shared_ax, 'freq', None)
                if ax_freq is not None:
                    break
    return ax_freq

def _get_ax_freq(ax):
    """
    Get the freq attribute of the ax object if set.
    Also checks shared axes (eg when using secondary yaxis, sharex=True
    or twinx)
    """
    if hasattr(ax, 'freq'):
        return ax.freq
    else:
        for ax_ in ax.get_shared_x_axes().get_siblings(ax):
            if hasattr(ax_, 'freq'):
                return ax_.freq
    return None

def _sign_response(self, response):
        """Signs a response if it's possible."""
        if self.key is None:
            return response

        if response.status_code == 200:
            response.headers['X-Hub-Signature'] = self._sign(response.content)

        return response

def migration(resource, version, previous_version=''):
    """Register a migration function"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            migrated = func(*args, **kwargs)

            return migrated

        m = Migration(wrapper, resource, version, previous_version)
        m.register()

        return m

    return decorator

def migration(resource, version, previous_version=''):
    """Register a migration function"""
    if resource not in migrations:
        migrations[resource] = {}
    migrations[resource][version] = previous_version

def _secret_generator(baseline):
    """Generates secrets to audit, from the baseline"""
    for filename, secrets in baseline['results'].items():
        for secret in secrets:
            yield filename, secret

def _secret_generator(baseline):
    """Generates secrets to audit, from the baseline"""
    secrets = []
    for secret in baseline:
        secrets.append(secret)
        if secret.startswith('aws:'):
            secrets.append(secret.replace('aws:', 'aws:kms:'))
        elif secret.startswith('aws:kms:'):
            secrets.append(secret.replace('aws:kms:', 'aws:'))
        elif secret.startswith('aws:'):
            secrets.append(secret.replace('aws:', 'aws:kms:'))
        elif secret.startswith('aws:kms:'):
            secrets.append(secret.replace('aws:kms:', 'aws:'))
        elif secret.startswith('arn:aws:'):
            secrets.append(secret.replace('arn:aws:', 'arn:aws:kms:'))
        elif secret.startswith('arn:aws:kms:'):
            secrets.append(secret.replace('arn:aws:kms:', 'arn:aws:'))
        elif secret.startswith('arn:aws:'):
            secrets.append(secret.replace('arn:aws:', 'arn:aws:kms:'))
        elif secret.startswith('arn:aws:kms:'):
            secrets.append(secret.replace('arn:aws:kms:', 'arn:aws:'))
    return secrets

def _get_rnn_layer(mode, num_layers, input_size, hidden_size, dropout, weight_dropout):
    """create rnn layer given specs"""
    if mode == 'rnn_relu':
        rnn_block = functools.partial(rnn.RNN, activation='relu')
    elif mode == 'rnn_tanh':
        rnn_block = functools.partial(rnn.RNN, activation='tanh')
    elif mode == 'lstm':
        rnn_block = rnn.LSTM
    elif mode == 'gru':
        rnn_block = rnn.GRU

    block = rnn_block(hidden_size, num_layers, dropout=dropout,
                      input_size=input_size)

    if weight_dropout:
        apply_weight_drop(block, '.*h2h_weight', rate=weight_dropout)

    return block

def _get_rnn_layer(mode, num_layers, input_size, hidden_size, dropout, weight_dropout):
    """create rnn layer given specs"""
    if mode == 'LSTM':
        rnn_layer = nn.LSTM(input_size, hidden_size, num_layers, dropout=dropout, bidirectional=True)
    elif mode == 'GRU':
        rnn_layer = nn.GRU(input_size, hidden_size, num_layers, dropout=dropout, bidirectional=True)
    elif mode == 'RNN':
        rnn_layer = nn.RNN(input_size, hidden_size, num_layers, dropout=dropout, bidirectional=True)
    else:
        raise ValueError('Invalid RNN mode: %s' % mode)

    if weight_dropout > 0:
        rnn_layer = WeightDrop(rnn_layer, ['weight_hh_l0'], dropout=weight_dropout)

    return rnn_layer

def is_repo_instance(cls, path):
        """
        Return ``True`` if ``path`` is a source controlled repository.
        """
        try:
            cls.get_version(path)
            return True
        except subprocess.CalledProcessError:
            # Git returns non-zero status
            return False
        except OSError:
            # Git unavailable?
            return False

def is_repo_instance(cls, path):
        """
        Return ``True`` if ``path`` is a source controlled repository.
        """
        return os.path.exists(os.path.join(path, '.hg'))

