            indicator_type=indicator_type
        )

def nsmallest(n, iterable, key=None):
    """Find the n smallest elements in a dataset.

    Equivalent to:  sorted(iterable, key=key)[:n]
    """
    return heapq.nsmallest(n, iterable, key)

def _dump_multipolygon(obj, big_endian, meta):
    """
    Dump a GeoJSON-like `dict` to a multipolygon WKB string.

    Input parameters and output are similar to :funct:`_dump_point`.
    """
    if obj['type']!= 'MultiPolygon':
        raise ValueError('Expected a MultiPolygon object')
    if len(obj['coordinates']) == 0:
        raise ValueError('Expected a non-empty MultiPolygon object')
    if len(obj['coordinates'][0]) == 0:
        raise ValueError('Expected a non-empty MultiPolygon object')
    if len(obj['coordinates'][0][0]) == 0:
        raise ValueError('Expected a non-empty MultiPolygon object')

    # Dump the number of polygons
    n_polygons = len(obj['coordinates'])
    if big_endian:
        n_polygons = struct.pack('>i', n_polygons)
    else:
        n_polygons = struct.pack('<i', n_polygons)
    meta['wkb_string'] += n_polygons

    # Dump the number of rings in each polygon
    for polygon in obj['coordinates']:
        n_rings = len(polygon)
        if big_endian:
            n_rings = struct.pack('>i', n_rings)
        else:
            n_rings = struct.pack('<i', n_rings)
        meta['wkb_string'] += n_rings

        # Dump the number of points in each ring
        for ring in polygon:
            n_points = len(ring)
            if big_endian:
                n_points = struct.pack('>i', n_points)
            else:
                n_points = struct.pack('<i', n_points)
            meta['wkb_string'] += n_points

            # Dump the points
            for point in ring:
                meta['wkb_string'] += _dump_point(point, big_endian, meta)

    return meta['wkb_string']

def license_from_trove(trove):
    """Finds out license from list of trove classifiers.
    Args:
        trove: list of trove classifiers
    Returns:
        Fedora name of the package license or empty string, if no licensing
        information is found in trove classifiers.
    """
    for trove_class in trove:
        if trove_class.startswith('License:'):
            return trove_class.split(':', 1)[1].strip()
    return ''

def __update_display_items_model(self, display_items_model: ListModel.FilteredListModel, data_group: typing.Optional[DataGroup.DataGroup], filter_id: typing.Optional[str]) -> None:
        """Update the data item model with a new container, filter, and sorting.

        This is called when the data item model is created or when the user changes
        the data group or sorting settings.
        """
        if data_group is None:
            data_group = self.__data_group
        if filter_id is None:
            filter_id = self.__filter_id
        if data_group is not None:
            display_items_model.set_container(data_group.get_container())
        if filter_id is not None:
            display_items_model.set_filter(filter_id)
        if data_group is not None:
            display_items_model.set_sorting(data_group.get_sorting())

