def qmed_all_methods(self):
        """
        Returns a dict of QMED methods using all available methods.

        Available methods are defined in :attr:`qmed_methods`. The returned dict keys contain the method name, e.g.
        `amax_record` with value representing the corresponding QMED estimate in m³/s.

        :return: dict of QMED estimates
        :rtype: dict
        """
        result = {}
        for method in self.methods:
            try:
                result[method] = getattr(self, '_qmed_from_' + method)()
            except:
                result[method] = None
        return result

def get_atlas_peers(hostport, timeout=30, my_hostport=None, proxy=None):
    """
    Get an atlas peer's neighbors. 
    Return {'status': True, 'peers': [peers]} on success.
    Return {'error': ...} on error
    """
    assert hostport or proxy, 'need either hostport or proxy'

    peers_schema = {
        'type': 'object',
        'properties': {
            'peers': {
                'type': 'array',
                'items': {
                    'type': 'string',
                    'pattern': '^([^:]+):([1-9][0-9]{1,4})$',
                },
            },
        },
        'required': [
            'peers'
        ],
    }

    schema = json_response_schema( peers_schema )

    if proxy is None:
        proxy = connect_hostport(hostport)

    peers = None
    try:
        peer_list_resp = proxy.get_atlas_peers()
        peer_list_resp = json_validate(schema, peer_list_resp)
        if json_is_error(peer_list_resp):
            return peer_list_resp

        # verify that all strings are host:ports
        for peer_hostport in peer_list_resp['peers']:
            peer_host, peer_port = url_to_host_port(peer_hostport)
            if peer_host is None or peer_port is None:
                return {'error': 'Server did not return valid Atlas peers', 'http_status': 503}

        peers = peer_list_resp

    except ValidationError as ve:
        if BLOCKSTACK_DEBUG:
            log.exception(ve)

        resp = {'error': 'Server response did not match expected schema.  You are likely communicating with an out-of-date Blockstack node.', 'http_status': 502}
        return resp

    except socket.timeout:
        log.error("Connection timed out")
        resp = {'error': 'Connection to remote host timed out.', 'http_status': 503}
        return resp

    except socket.error as se:
        log.error("Connection error {}".format(se.errno))
        resp = {'error': 'Connection to remote host failed.', 'http_status': 502}
        return resp

    except Exception as ee:
        if BLOCKSTACK_DEBUG:
            log.exception(ee)

        log.error("Caught exception while connecting to Blockstack node: {}".format(ee))
        resp = {'error': 'Failed to contact Blockstack node {}.  Try again with `--debug`.'.format(hostport), 'http_status': 500}
        return resp

    return peers

def get_atlas_peers(hostport, timeout=30, my_hostport=None, proxy=None):
    """
    Get an atlas peer's neighbors. 
    Return {'status': True, 'peers': [peers]} on success.
    Return {'error': ...} on error
    """
    if my_hostport is None:
        my_hostport = get_my_hostport()
    if proxy is None:
        proxy = get_proxy()
    url = 'http://%s/atlas/peers' % hostport
    try:
        r = requests.get(url, timeout=timeout, proxies=proxy)
        if r.status_code!= 200:
            return {'error': 'get_atlas_peers: %s' % r.text}
        peers = json.loads(r.text)
        return {'status': True, 'peers': peers}
    except Exception as e:
        return {'error': 'get_atlas_peers: %s' % e}

def do_reload(bot, target, cmdargs, server_send=None):
    """The reloading magic.

    - First, reload handler.py.
    - Then make copies of all the handler data we want to keep.
    - Create a new handler and restore all the data.

    """
    if not cmdargs:
        return bot.say("Usage: %s <handler name>" % cmdargs)

    if cmdargs[0] not in bot.handlers:
        return bot.say("No such handler: %s" % cmdargs[0])

    # Reload the handler
    reload(bot.handlers[cmdargs[0]])

    # Copy the data we want to keep
    data = {}
    for key in bot.handlers[cmdargs[0]].__dict__:
        if key.startswith("_"):
            continue
        data[key] = bot.handlers[cmdargs[0]].__dict__[key]

    # Create a new handler and restore the data
    bot.handlers[cmdargs[0]] = bot.handlers[cmdargs[0]].__class__()
    for key in data:
        bot.handlers[cmdargs[0]].__dict__[key] = data[key]

    return bot.say("Reloaded handler: %s" % cmdargs[0])

def save_file_as(self, file_url, new_file_name, destination_folder=None):
