def has_implementation(self, number, arch, abi_list=()):
        """
        Pretty much the intersection of SimLibrary.has_implementation() and SimSyscallLibrary.get().

        :param number:      The syscall number
        :param arch:        The architecture being worked with, as either a string name or an archinfo.Arch
        :param abi_list:    A list of ABI names that could be used
        :return:            A bool of whether or not an implementation of the syscall is available
        """
        if not isinstance(arch, archinfo.Arch):
            arch = self.arch_from_name(arch)

        if not abi_list:
            abi_list = self.abis

        for abi in abi_list:
            if self.has_implementation(number, arch, abi):
                return True

        return False

def ensure_float_vector_or_None(F, require_order = False):
    """Ensures that F is either None, or a numpy array of floats

    If F is already either None or a numpy array of floats, F is returned (no copied!)
    Otherwise, checks if the argument can be converted to an array of floats and does that.

    Parameters
    ----------
    F: float, list of float or 1D-ndarray of float

    Returns
    -------
    arr : ndarray(n)
        numpy array with the floats contained in the argument

    """
    if F is None:
        return None
    elif isinstance(F, np.ndarray):
        if F.dtype!= np.float:
            raise ValueError("F must be a numpy array of floats")
        if require_order and not np.all(np.diff(F) >= 0):
            raise ValueError("F must be a monotonically increasing sequence of floats")
        return F
    elif isinstance(F, list):
        F = np.array(F)
    if not isinstance(F, np.ndarray):
        raise ValueError("F must be a numpy array of floats")
    if F.dtype!= np.float:
        raise ValueError("F must be a numpy array of floats")
    if require_order and not np.all(np.diff(F) >= 0):
        raise ValueError("F must be a monotonically increasing sequence of floats")
    return F

