def nose_selector(test):
    """Return the string you can pass to nose to run `test`, including argument
    values if the test was made by a test generator.

    Return "Unknown test" if it can't construct a decent path.

    """
    address = test_address(test)
    if address:
        file, module, rest = address

        if module:
            if rest:
                try:
                    return '%s:%s%s' % (module, rest, test.test.arg or '')
                except AttributeError:
                    return '%s:%s' % (module, rest)
            else:
                return module
    return 'Unknown test'

def nose_selector(test):
    """Return the string you can pass to nose to run `test`, including argument
    values if the test was made by a test generator.

    Return "Unknown test" if it can't construct a decent path.

    """
    if isinstance(test, nose.case.Test):
        return test.id()
    elif isinstance(test, nose.case.TestGenerator):
        return test.id()
    else:
        return "Unknown test"

def package_to_directory(package_path: str) -> str:
    """
    Translate a package/path specification into a real file system pathname.

    :param package_path: a package name or a package/path specification like
        ``package.subpackage/directory/subdirectory``
    :return: the translated path name
    :raises ImportError: if the package cannot be imported
    :raises LookupError: if the directory does not exist

    """
    if '/' in package_path:
        pkgname, subpath = package_path.split('/', 1)
    else:
        pkgname, subpath = package_path, ''

    module = import_module(pkgname)
    path = Path(module.__spec__.origin).parent / subpath
    if path.exists():
        if path.is_dir():
            return str(path)
        else:
            raise LookupError('{} is not a directory'.format(path))
    else:
        raise LookupError('{} does not exist'.format(path))

def package_to_directory(package_path: str) -> str:
    """
    Translate a package/path specification into a real file system pathname.

    :param package_path: a package name or a package/path specification like
        ``package.subpackage/directory/subdirectory``
    :return: the translated path name
    :raises ImportError: if the package cannot be imported
    :raises LookupError: if the directory does not exist

    """
    if not package_path:
        raise LookupError("No package/path specified")
    if "/" in package_path:
        package_name, path = package_path.split("/", 1)
    else:
        package_name = package_path
        path = ""
    try:
        package = importlib.import_module(package_name)
    except ImportError:
        raise ImportError(f"Package {package_name!r} not found")
    package_path = os.path.dirname(package.__file__)
    if not path:
        return package_path
    path = os.path.join(package_path, path)
    if not os.path.isdir(path):
        raise LookupError(f"Directory {path!r} not found")
    return path

def parse_request(cls, sock):
    """Parse the request (the pre-execution) section of the nailgun protocol from the given socket.

    Handles reading of the Argument, Environment, Working Directory and Command chunks from the
    client which represents the "request" phase of the exchange. Working Directory and Command are
    required and must be sent as the last two chunks in this phase. Argument and Environment chunks
    are optional and can be sent more than once (thus we aggregate them).
    """

    command = None
    working_dir = None
    arguments = []
    environment = {}

    while not all((working_dir, command)):
      chunk_type, payload = cls.read_chunk(sock)

      if chunk_type == ChunkType.ARGUMENT:
        arguments.append(payload)
      elif chunk_type == ChunkType.ENVIRONMENT:
        key, val = payload.split(cls.ENVIRON_SEP, 1)
        environment[key] = val
      elif chunk_type == ChunkType.WORKING_DIR:
        working_dir = payload
      elif chunk_type == ChunkType.COMMAND:
        command = payload
      else:
        raise cls.ProtocolError('received non-request chunk before header was fully received!')

    return working_dir, command, arguments, environment

def parse_request(cls, sock):
    """Parse the request (the pre-execution) section of the nailgun protocol from the given socket.

    Handles reading of the Argument, Environment, Working Directory and Command chunks from the
    client which represents the "request" phase of the exchange. Working Directory and Command are
    required and must be sent as the last two chunks in this phase. Argument and Environment chunks
    are optional and can be sent more than once (thus we aggregate them).
    """
    request = cls()
    while True:
        chunk = read_chunk(sock)
        if chunk.type == cls.ARG:
            request.args.append(chunk.data)
        elif chunk.type == cls.ENV:
            request.envs.append(chunk.data)
        elif chunk.type == cls.WD:
            request.wd = chunk.data
        elif chunk.type == cls.CMD:
            request.cmd = chunk.data
        elif chunk.type == cls.EOF:
            return request
        else:
            raise ValueError("Unknown chunk type: %s" % chunk.type)

def get_dbs(self, attr, args, kwargs, **fkwargs):
        """
        Returns a list of db keys to route the given call to.

        :param attr: Name of attribute being called on the connection.
        :param args: List of arguments being passed to ``attr``.
        :param kwargs: Dictionary of keyword arguments being passed to ``attr``.

        >>> redis = Cluster(router=BaseRouter)
        >>> router = redis.router
        >>> router.get_dbs('incr', args=('key name', 1))
        [0,1,2]

        """
        if not self._ready:
            if not self.setup_router(args=args, kwargs=kwargs, **fkwargs):
                raise self.UnableToSetupRouter()

        retval = self._pre_routing(attr=attr, args=args, kwargs=kwargs, **fkwargs)
        if retval is not None:
            args, kwargs = retval

        if not (args or kwargs):
            return self.cluster.hosts.keys()

        try:
            db_nums = self._route(attr=attr, args=args, kwargs=kwargs, **fkwargs)
        except Exception as e:
            self._handle_exception(e)
            db_nums = []

        return self._post_routing(attr=attr, db_nums=db_nums, args=args, kwargs=kwargs, **fkwargs)

