        """return a `close` :class:`Frame`.
        """
        return self.frame(code=code)

def activations(self):
        """Iterate over the Activations in the Agenda."""
        activation = lib.EnvGetNextActivation(self._env, ffi.NULL)

        while activation != ffi.NULL:
            yield Activation(self._env, activation)

            activation = lib.EnvGetNextActivation(self._env, activation)

def activations(self):
        """Iterate over the Activations in the Agenda."""
        for activation in self._activations:
            yield activation

def can_user_update_settings(request, view, obj=None):
        """ Only staff can update shared settings, otherwise user has to be an owner of the settings."""
        if obj is None:
            return

        # TODO [TM:3/21/17] clean it up after WAL-634. Clean up service settings update tests as well.
        if obj.customer and not obj.shared:
            return permissions.is_owner(request, view, obj)
        else:
            return permissions.is_staff(request, view, obj)

def can_user_update_settings(request, view, obj=None):
        """ Only staff can update shared settings, otherwise user has to be an owner of the settings."""
        if request.user.is_staff:
            return True
        if obj is None:
            return False
        return obj.owner == request.user

def get_full_name(self):
        """Get the full name for debugging (host_name/service_description)

        :return: service full name
        :rtype: str
        """
        if self.is_tpl():
            return "tpl-%s/%s" % (getattr(self, 'host_name', 'XxX'), self.name)
        if hasattr(self, 'host_name') and hasattr(self, 'service_description'):
            return "%s/%s" % (self.host_name, self.service_description)
        return 'UNKNOWN-SERVICE'

