def get_json_props_for_response(self, var_type, option_value):
        """
        Prepare JSON section with detailed information about response

        :param var_type: --contains variable type
        :type var_type: , unicode
        :param option_value: --dictionary that contains information about property
        :type option_value: dict
        :return: dictionary that contains, title and all properties of field
        :rtype: dict
        """
        props = list()
        for name, value in option_value.items():
            if var_type in ['dynamic', 'select2']:
                break
            elif name in ['format', 'title', 'type']:
                continue
            elif isinstance(value, dict) and value.get('$ref', None):
                props.append(':ref:`{}`'.format(value['$ref'].split('/')[-1]))
            elif '$ref' in name:
                props.append(':ref:`{}`'.format(value.split('/')[-1]))
            elif var_type == 'autocomplete':
                props.append('Example values: ' + ', '.join(value))
            else:
                props.append('{}={}'.format(name, value))

        if len(props):
            props_str = '(' + ', '.join(props) + ')'
        else:
            props_str = ''
        return dict(props_str=props_str, title=option_value.get('title', ''))

def get_json_props_for_response(self, var_type, option_value):
        """
        Prepare JSON section with detailed information about response

        :param var_type: --contains variable type
        :type var_type: , unicode
        :param option_value: --dictionary that contains information about property
        :type option_value: dict
        :return: dictionary that contains, title and all properties of field
        :rtype: dict
        """
        if var_type == 'list':
            return self.get_json_props_for_list_response(option_value)
        elif var_type == 'dict':
            return self.get_json_props_for_dict_response(option_value)
        else:
            return self.get_json_props_for_simple_response(option_value)

def add_configurations(self, experiments):
        """Chains generator given experiment specifications.

        Arguments:
            experiments (Experiment | list | dict): Experiments to run.
        """
        if isinstance(experiments, Experiment):
            experiments = [experiments]
        elif isinstance(experiments, dict):
            experiments = [Experiment(**experiment) for experiment in experiments]
        elif isinstance(experiments, list):
            experiments = [Experiment(**experiment) for experiment in experiments]
        else:
            raise TypeError(f"Expected Experiment, list or dict, got {type(experiments)}")

        for experiment in experiments:
            self.add_experiment(experiment)

def stage_files(pathmapper,             # type: PathMapper
                stage_func=None,        # type: Callable[..., Any]
                ignore_writable=False,  # type: bool
                symlink=True,           # type: bool
                secret_store=None       # type: SecretStore
               ):  # type: (...) -> None
    """Link or copy files to their targets. Create them as needed."""
    for key, entry in pathmapper.items():
        if not entry.staged:
            continue
        if not os.path.exists(os.path.dirname(entry.target)):
            os.makedirs(os.path.dirname(entry.target))
        if entry.type in ("File", "Directory") and os.path.exists(entry.resolved):
            if symlink:  # Use symlink func if allowed
                if onWindows():
                    if entry.type == "File":
                        shutil.copy(entry.resolved, entry.target)
                    elif entry.type == "Directory":
                        if os.path.exists(entry.target) \
                                and os.path.isdir(entry.target):
                            shutil.rmtree(entry.target)
                        copytree_with_merge(entry.resolved, entry.target)
                else:
                    os.symlink(entry.resolved, entry.target)
            elif stage_func is not None:
                stage_func(entry.resolved, entry.target)
        elif entry.type == "Directory" and not os.path.exists(entry.target) \
                and entry.resolved.startswith("_:"):
            os.makedirs(entry.target)
        elif entry.type == "WritableFile" and not ignore_writable:
            shutil.copy(entry.resolved, entry.target)
            ensure_writable(entry.target)
        elif entry.type == "WritableDirectory" and not ignore_writable:
            if entry.resolved.startswith("_:"):
                os.makedirs(entry.target)
            else:
                shutil.copytree(entry.resolved, entry.target)
                ensure_writable(entry.target)
        elif entry.type == "CreateFile" or entry.type == "CreateWritableFile":
            with open(entry.target, "wb") as new:
                if secret_store is not None:
                    new.write(
                        secret_store.retrieve(entry.resolved).encode("utf-8"))
                else:
                    new.write(entry.resolved.encode("utf-8"))
            if entry.type == "CreateFile":
                os.chmod(entry.target, stat.S_IRUSR)  # Read only
            else:  # it is a "CreateWritableFile"
                ensure_writable(entry.target)
            pathmapper.update(
                key, entry.target, entry.target, entry.type, entry.staged)

def stage_files(pathmapper,             # type: PathMapper
                stage_func=None,        # type: Callable[..., Any]
                ignore_writable=False,  # type: bool
                symlink=True,           # type: bool
                secret_store=None       # type: SecretStore
               ):  # type: (...) -> None
    """Link or copy files to their targets. Create them as needed."""
    if stage_func is None:
        stage_func = _default_stage_func
    for src, dst in pathmapper.items():
        if not os.path.exists(dst):
            if os.path.exists(src):
                stage_func(src, dst, symlink=symlink, secret_store=secret_store)
            else:
                raise FileNotFoundError(f"Source file {src} does not exist")
        elif os.path.islink(dst):
            if os.path.realpath(dst)!= src:
                stage_func(src, dst, symlink=symlink, secret_store=secret_store)
        elif os.path.isdir(dst):
            if not os.path.isdir(src):
                raise ValueError(f"Source {src} is a directory, but destination {dst} is not")
            if not os.path.islink(src):
                raise ValueError(f"Source {src} is a directory, but destination {dst} is not a symlink")
            if os.path.realpath(src)!= dst:
                stage_func(src, dst, symlink=symlink, secret_store=secret_store)
        elif os.path.isfile(dst):
            if not os.path.isfile(src):
                raise ValueError(f"Source {src} is a file, but destination {dst} is not")
            if not os.path.islink(src):
                raise ValueError(f"Source {src} is a file, but destination {dst} is not a symlink")
            if os.path.realpath(src)!= dst:
                stage_func(src, dst, symlink=symlink, secret_store=secret_store)
        else:
            raise ValueError(f"Destination {dst} is neither a file nor a directory")
        if not ignore_writable and os.path.exists(dst) and os.access(dst, os.W_OK):
            raise ValueError(f"Destination {dst} is writable")

