def loads(s, encoding=None, cls=None, object_hook=None, parse_float=None,
          parse_int=None, parse_constant=None, object_pairs_hook=None):
    """Deserialize ``s`` (a ``str`` or ``unicode`` instance containing a
    JSON5 document) to a Python object."""

    assert cls is None, 'Custom decoders are not supported'

    if sys.version_info[0] < 3:
        decodable_type = type('')
    else:
        decodable_type = type(b'')
    if isinstance(s, decodable_type):
        encoding = encoding or 'utf-8'
        s = s.decode(encoding)

    if not s:
        raise ValueError('Empty strings are not legal JSON5')
    parser = Parser(s, '<string>')
    ast, err, newpos = parser.parse()
    if err:
        raise ValueError(err)

    def _fp_constant_parser(s):
        return float(s.replace('Infinity', 'inf').replace('NaN', 'nan'))

    if object_pairs_hook:
        dictify = object_pairs_hook
    elif object_hook:
        dictify = lambda pairs: object_hook(dict(pairs))
    else:
        dictify = dict

    parse_float = parse_float or float
    parse_int = parse_int or int
    parse_constant = parse_constant or _fp_constant_parser

    return _walk_ast(ast, dictify, parse_float, parse_int, parse_constant)

def init_flatpak():
    """
    If we are in Flatpak, we must build a tessdata/ directory using the
    .traineddata files from each locale directory
    """
    if not os.path.exists(TESSERACT_DATA_DIR):
        os.makedirs(TESSERACT_DATA_DIR)

    for locale in os.listdir(LOCALE_DIR):
        if locale.startswith('.'):
            continue
        locale_dir = os.path.join(LOCALE_DIR, locale)
        if not os.path.isdir(locale_dir):
            continue
        for filename in os.listdir(locale_dir):
            if filename.endswith('.traineddata'):
                shutil.copy(os.path.join(locale_dir, filename),
                            os.path.join(TESSERACT_DATA_DIR, filename))

def _make_request(self, path, method='GET', params_=None):
        """Make a request to the API"""
        uri = self.api_root + path
        if params_:
            params_['text_format'] = self.response_format
        else:
            params_ = {'text_format': self.response_format}

        # Make the request
        response = None
        try:
            response = self._session.request(method, uri,
                                            timeout=self.timeout,
                                            params=params_)
        except Timeout as e:
            print("Timeout raised and caught:\n{e}".format(e=e))

        # Enforce rate limiting
        time.sleep(max(self._SLEEP_MIN, self.sleep_time))
        return response.json()['response'] if response else None

def _make_request(self, path, method='GET', params_=None):
        """Make a request to the API"""
        url = self.base_url + path
        if method == 'GET':
            response = requests.get(url, params=params_)
        elif method == 'POST':
            response = requests.post(url, params=params_)
        else:
            raise Exception('Invalid method')
        return response

def require_axis(f):
    """ Check if the object of the function has axis and sel_axis members """

    @wraps(f)
    def _wrapper(self, *args, **kwargs):
        if None in (self.axis, self.sel_axis):
            raise ValueError('%(func_name) requires the node %(node)s '
                    'to have an axis and a sel_axis function' %
                    dict(func_name=f.__name__, node=repr(self)))

        return f(self, *args, **kwargs)

    return _wrapper

def require_axis(f):
    """ Check if the object of the function has axis and sel_axis members """
    if not hasattr(f, 'axis') or not hasattr(f,'sel_axis'):
        raise ValueError("Function must have axis and sel_axis members")
    return f

def write_settings(settings):
    """
    Saves user's settings
    @returns True on success
    @returns False on failure
    """
    if not os.access(DATA_DIR, os.W_OK): return False
    try:
        f = open(DATA_DIR + os.sep + SETTINGS_FILE, 'w')
        f.writelines(json.dumps(settings, indent=0))
        f.close()
        os.chmod(os.path.abspath(DATA_DIR + os.sep + SETTINGS_FILE), 0o777) # to avoid (or create?) IO problems with multiple users
    except IOError:
        return False
    else:
        return True

