def get(self, href):
        """Fetch a single item."""
        if self.is_fake:
            return

        uid = _trim_suffix(href, ('.ics', '.ical', '.vcf'))
        etesync_item = self.collection.get(uid)
        if etesync_item is None:
            return None

        try:
            item = vobject.readOne(etesync_item.content)
        except Exception as e:
            raise RuntimeError("Failed to parse item %r in %r" %
                               (href, self.path)) from e
        # FIXME: Make this sensible
        last_modified = time.strftime(
            "%a, %d %b %Y %H:%M:%S GMT",
            time.gmtime(time.time()))
        return EteSyncItem(self, item, href, last_modified=last_modified, etesync_item=etesync_item)

def get(self, href):
        """Fetch a single item."""
        return self.get_all(href)[0]

def DocbookXslt(env, target, source=None, *args, **kw):
    """
    A pseudo-Builder, applying a simple XSL transformation to the input file.
    """
    if source is None:
        source = target
    return env.Command(target, source,
                       [env.DocbookXslt, source, target] + args)

def rotated(self, angle_degrees_ccw):
        """Concatenates a rotation matrix on this matrix"""
        angle = angle_degrees_ccw / 180.0 * pi
        c, s = cos(angle), sin(angle)
        return self @ PdfMatrix((c, s, -s, c, 0, 0))

def rotated(self, angle_degrees_ccw):
        """Concatenates a rotation matrix on this matrix"""
        angle_radians_ccw = angle_degrees_ccw * math.pi / 180.0
        return Matrix(
            [
                [math.cos(angle_radians_ccw), -math.sin(angle_radians_ccw)],
                [math.sin(angle_radians_ccw), math.cos(angle_radians_ccw)],
            ]
        )

def cross(self, vec):
        """Cross product with another Vector3Array"""
        if not isinstance(vec, Vector3Array):
            raise TypeError('Cross product operand must be a Vector3Array')
        if self.nV != 1 and vec.nV != 1 and self.nV != vec.nV:
            raise ValueError('Cross product operands must have the same '
                             'number of elements.')
        return Vector3Array(np.cross(self, vec))

def cross(self, vec):
        """Cross product with another Vector3Array"""
        return Vector3Array(
            self.x * vec.y - self.y * vec.x,
            self.x * vec.z - self.z * vec.x,
            self.y * vec.z - self.z * vec.y,
        )

def _update_keycache(self, *args, forward):
        """Add or remove a key in the set describing the keys that exist."""
        entity, key, branch, turn, tick, value = args[-6:]
        parent = args[:-6]
        kc = self._get_keycache(parent + (entity,), branch, turn, tick, forward=forward)
        if value is None:
            kc = kc.difference((key,))
        else:
            kc = kc.union((key,))
        self.keycache[parent+(entity, branch)][turn][tick] = kc

def _update_keycache(self, *args, forward):
        """Add or remove a key in the set describing the keys that exist."""
        if forward:
            self.keycache.add(args[0])
        else:
            self.keycache.discard(args[0])

