def checkTikaServer(scheme="http", serverHost=ServerHost, port=Port, tikaServerJar=TikaServerJar, classpath=None, config_path=None):
    """
    Check that tika-server is running.  If not, download JAR file and start it up.
    :param scheme: e.g. http or https
    :param serverHost:
    :param port:
    :param tikaServerJar:
    :param classpath:
    :return:
    """
    # Check if tika-server is running
    try:
        r = requests.get(scheme + "://" + serverHost + ":" + str(port) + "/tika")
        if r.status_code == 200:
            return True
    except:
        pass

    # If not, download JAR file and start it up
    if classpath is None:
        classpath = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tika-server-1.16.jar")
    if config_path is None:
        config_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tika-config.xml")
    if not os.path.exists(tikaServerJar):
        print("Downloading tika-server-1.16.jar to " + tikaServerJar)
        r = requests.get("http://search.maven.org/remotecontent?filepath=org/apache/tika/tika-server/1.16/tika-server-1.16.jar", stream=True)
        with open(tikaServerJar, 'wb') as f:
            for chunk in r.iter_content(chunk_size=1024):
                if chunk:
                    f.write(chunk)
    print("Starting tika-server")
    subprocess.Popen(["java", "-jar", tikaServerJar, "-h", serverHost, "-p", str(port), "-c", config_path, "-cp", classpath])
    time.sleep(1)
    return checkTikaServer(scheme, serverHost, port, tikaServerJar, classpath, config_path)

def create(cls, community, record, user=None, expires_at=None,
               notify=True):
        """Create a record inclusion request to a community.

        :param community: Community object.
        :param record: Record API object.
        :param expires_at: Time after which the request expires and shouldn't
            be resolved anymore.
        """
        if not isinstance(community, Community):
            raise TypeError('community must be a Community object')
        if not isinstance(record, Record):
            raise TypeError('record must be a Record object')
        if not isinstance(user, User) and user is not None:
            raise TypeError('user must be a User object')
        if not isinstance(expires_at, datetime) and expires_at is not None:
            raise TypeError('expires_at must be a datetime object')

        if user is None:
            user = User.current()

        if expires_at is None:
            expires_at = datetime.utcnow() + timedelta(days=1)

        request = cls(community=community, record=record, user=user,
                      expires_at=expires_at)
        request.save()

        if notify:
            request.notify()

        return request

def subgraph_from(self, targets: sos_targets):
        """Trim DAG to keep only nodes that produce targets"""
        if 'DAG' in env.config['SOS_DEBUG'] or 'ALL' in env.config['SOS_DEBUG']:
            env.log_to_file('DAG', 'create subgraph')
        # first, find all nodes with targets
        subnodes = []
        for node in self.nodes():
            if node._output_targets.valid() and any(
                    x in node._output_targets for x in targets):
                subnodes.append(node)
        #
        ancestors = set()
        for node in subnodes:
            ancestors |= nx.ancestors(self, node)
        return SoS_DAG(nx.subgraph(self, subnodes + list(ancestors)))

def subgraph_from(self, targets: sos_targets):
        """Trim DAG to keep only nodes that produce targets"""
        if not targets:
            return self

        # Create a new DAG with only the nodes that produce the targets
        new_dag = self.copy()
        new_dag.remove_nodes_from(
            [node for node in self.nodes if node not in targets]
        )
        return new_dag

def del_map(self, event, handle, *args):
        """
        Remove a mapping like event -(arg0, arg1, arg2, ...)-> handle.
        """
        if args:
            self.base[event].remove((handle, args))
        else:
            self.base[event] = [ind for ind in self.base[event] if ind[0] != handle]

def del_map(self, event, handle, *args):
        """
        Remove a mapping like event -(arg0, arg1, arg2, ...)-> handle.
        """
        try:
            self.event_map.pop(event)
        except KeyError:
            pass

def _get_args(cls, **kwargs):
        """Parse style and locale.

        Argument location precedence: kwargs > view_args > query
        """
        csl_args = {
            'style': cls._default_style,
            'locale': cls._default_locale
        }

        if has_request_context():
            parser = FlaskParser(locations=('view_args', 'query'))
            csl_args.update(parser.parse(cls._user_args, request))

        csl_args.update({k: kwargs[k]
                         for k in ('style', 'locale') if k in kwargs})

        try:
            csl_args['style'] = get_style_filepath(csl_args['style'].lower())
        except StyleNotFoundError:
            if has_request_context():
                raise StyleNotFoundRESTError(csl_args['style'])
            raise
        return csl_args

def verifyCert(self, cert):
        """ Verifies either a Cert or an X509_Cert. """
        if isinstance(cert, X509_Cert):
            return cert.verify(self.cert)
        else:
            return cert.verify(self.cert.get_pubkey())

