def merge_kwargs(local_kwarg, default_kwarg):
    """Merges kwarg dictionaries.

    If a local key in the dictionary is set to None, it will be removed.
    """

    if default_kwarg is None:
        return local_kwarg

    if isinstance(local_kwarg, basestring):
        return local_kwarg

    if local_kwarg is None:
        return default_kwarg

    # Bypass if not a dictionary (e.g. timeout)
    if not hasattr(default_kwarg, 'items'):
        return local_kwarg

    # Update new values.
    kwargs = default_kwarg.copy()
    kwargs.update(local_kwarg)

    # Remove keys that are set to None.
    for (k,v) in local_kwarg.items():
        if v is None:
            del kwargs[k]

    return kwargs

def merge_kwargs(local_kwarg, default_kwarg):
    """Merges kwarg dictionaries.

    If a local key in the dictionary is set to None, it will be removed.
    """
    local_kwarg = local_kwarg.copy()
    for key, value in default_kwarg.items():
        if local_kwarg.get(key) is None:
            local_kwarg[key] = value
    return local_kwarg

def convert_squeeze(node, **kwargs):
    """Map MXNet's squeeze operator attributes to onnx's squeeze operator
    and return the created node.
    """
    # pylint: disable=unused-argument
    if len(node.inputs)!= 1:
        raise ValueError(
            "Squeeze operator must have exactly one input, got {}.".format(
                len(node.inputs)
            )
        )
    if len(node.outputs)!= 1:
        raise ValueError(
            "Squeeze operator must have exactly one output, got {}.".format(
                len(node.outputs)
            )
        )
    if len(node.attrs)!= 1:
        raise ValueError(
            "Squeeze operator must have exactly one attribute, got {}.".format(
                len(node.attrs)
            )
        )
    if node.attrs[0]!= "axes":
        raise ValueError(
            "Squeeze operator must have exactly one attribute named 'axes', got {}.".format(
                node.attrs[0]
            )
        )
    axes = node.attrs["axes"]
    if not isinstance(axes, int):
        raise ValueError(
            "Squeeze operator's attribute 'axes' must be an int, got {}.".format(
                axes
            )
        )
    return onnx.helper.make_node(
        "Squeeze",
        inputs=[node.inputs[0]],
        outputs=[node.outputs[0]],
        axes=[axes],
    )

