def resolve(track_url):
    """
    Resolves the URL to an actual track from the SoundCloud API.

    If the track resolves to more than one possible track, it takes the first search result.

    :returns: The track dictionary from the SoundCloud API
    """
    try:
        path = urlparse.urlparse(track_url).path
        tracks = client.get('/tracks', q=path)

        if tracks:
            return tracks[0]
        else:
            raise ValueError('Track not found for URL {}'.format(track_url))
    except Exception as e:
        raise ValueError('Error obtaining track by url: {}'.format(str(e)))

def _generate_timezone(date, local_tz):
    """
    input :
    date : date type
    local_tz : bool

    offset generated from _calculate_offset
    offset in seconds
    offset = 0 -> +00:00
    offset = 1800 -> +00:30
    offset = -3600 -> -01:00
    """
    offset = _calculate_offset(date, local_tz)
    if offset == 0:
        return pytz.timezone('Etc/GMT')
    elif offset > 0:
        return pytz.timezone('Etc/GMT+' + str(offset))
    else:
        return pytz.timezone('Etc/GMT-' + str(offset))

def get_phi_comps_from_recfile(recfile):
    """read the phi components from a record file by iteration

    Parameters
    ----------
    recfile : str
        pest record file name

    Returns
    -------
    iters : dict
        nested dictionary of iteration number, {group,contribution}

    """
    iters = {}
    with open(recfile, 'r') as f:
        for line in f:
            if line.startswith('phi'):
                line = line.strip().split()
                iters[int(line[1])] = {}
                iters[int(line[1])]['group'] = line[2]
                iters[int(line[1])]['contribution'] = line[3]
    return iters

