def shorten_url(url, length=32, strip_www=True, strip_path=True, ellipsis=False):
    """
    Shorten a URL by chopping out the middle.

    For example if supplied with http://subdomain.example.com.au and length 16
    the following would be returned.

    sub...le.com.au
    """
    if '://' not in url:
        # Ensure we have a protocol
        url = 'http://%s' % url

    parsed_url = urlparse(url)
    ext = tldextract.extract(parsed_url.netloc)
    if ext.subdomain and (not strip_www or (strip_www and ext.subdomain != 'www')):
        shortened = u'%s.%s' % (ext.subdomain, ext.domain)
    else:
        shortened = u'%s' % ext.domain

    if ext.tld:
        shortened = u'%s.%s' % (shortened, ext.tld)

    if not strip_path:
        if parsed_url.path:
            shortened += parsed_url.path

    if len(shortened) <= length:
        return shortened
    else:
        domain = shortened
        i = length + 1 - 3
        left = right = int(i/2)
        if not i % 2:
            right -= 1
        if ellipsis:
            shortened = u"%s\u2026%s" % (domain[:left], domain[-right:])
        else:
            shortened = '%s...%s' % (domain[:left], domain[-right:])

        return shortened

def shorten_url(url, length=32, strip_www=True, strip_path=True, ellipsis=False):
    """
    Shorten a URL by chopping out the middle.

    For example if supplied with http://subdomain.example.com.au and length 16
    the following would be returned.

    sub...le.com.au
    """
    if strip_www:
        url = url.replace('www.', '')
    if strip_path:
        url = url.split('/')[0]
    if ellipsis:
        url = url[:length] + '...' + url[-length:]
    else:
        url = url[:length]
    return url

def hexdump(src, length=8):
    """ Produce a string hexdump of src, for debug output."""
    if not src:
        return str(src)
    src = input_validate_str(src, 'src')
    offset = 0
    result = ''
    for this in group(src, length):
        hex_s = ' '.join(["%02x" % ord(x) for x in this])
        result += "%04X   %s\n" % (offset, hex_s)
        offset += length
    return result

def hexdump(src, length=8):
    """ Produce a string hexdump of src, for debug output."""
    result = []
    digits = 4 if isinstance(src, unicode) else 2
    for i in xrange(0, len(src), length):
        s = src[i:i+length]
        hexa = b' '.join(["%0*X" % (digits, ord(x)) for x in s])
        text = b''.join([x if 0x20 <= ord(x) < 0x7F else b'.' for x in s])
        result.append(b"%04X   %-*s   %s" % (i, length*(digits + 1), hexa, text))
    return b'\n'.join(result)

def _parse_vars(self, tokens):
        """
        Given an iterable of tokens, returns variables and their values as a
        dictionary.

        For example:
            ['dtap=prod', 'comment=some comment']
        Returns:
            {'dtap': 'prod', 'comment': 'some comment'}
        """
        key_values = {}
        for token in tokens:
            if token.startswith('#'):
                # End parsing if we encounter a comment, which lasts
                # until the end of the line.
                break
            else:
                k, v = token.split('=', 1)
                key = k.strip()
                key_values[key] = v.strip()
        return key_values

def _parse_vars(self, tokens):
        """
        Given an iterable of tokens, returns variables and their values as a
        dictionary.

        For example:
            ['dtap=prod', 'comment=some comment']
        Returns:
            {'dtap': 'prod', 'comment': 'some comment'}
        """
        return dict(token.split('=', 1) for token in tokens)

def missing(name, limit=''):
    """
    The inverse of service.available.
    Return True if the named service is not available.  Use the ``limit`` param to
    restrict results to services of that type.

    CLI Examples:

    .. code-block:: bash

        salt '*' service.missing sshd
        salt '*' service.missing sshd limit=upstart
        salt '*' service.missing sshd limit=sysvinit
    """
    if limit == 'upstart':
        return not _service_is_upstart(name)
    elif limit == 'sysvinit':
        return not _service_is_sysv(name)
    else:
        if _service_is_upstart(name) or _service_is_sysv(name):
            return False
        else:
            return True

