def set_current_filename(self, filename, focus=True):
        """Set current filename and return the associated editor instance."""
        index = self.has_filename(filename)
        if index is not None:
            if focus:
                self.set_stack_index(index)
            editor = self.data[index].editor
            if focus:
                editor.setFocus()
            else:
                self.stack_history.remove_and_append(index)

            return editor

def set_current_filename(self, filename, focus=True):
        """Set current filename and return the associated editor instance."""
        if filename is None:
            return None
        if filename in self.editors:
            editor = self.editors[filename]
            if focus:
                editor.setFocus()
            return editor
        else:
            editor = self.create_editor(filename)
            self.editors[filename] = editor
            return editor

def filter(fastq, sam, paired = False):
	""" 
	filter sequences that are shown to be mapped in the sam file
	reads not in sam file are in *.filtered.fastq
	reads that are in the sam file are in *.matched.fastq
	"""
	if paired is False:
		list = sam_list(sam)
	else:
		list = sam_list_paired(sam)
	if paired is False:
		filter_fastq(fastq, list)
	else:
		filter_fastq_paired(fastq, list)

def filter(fastq, sam, paired = False):
	""" 
	filter sequences that are shown to be mapped in the sam file
	reads not in sam file are in *.filtered.fastq
	reads that are in the sam file are in *.matched.fastq
	"""
	if paired:
		# paired end
		with open(fastq + ".filtered.fastq", "w") as out1, open(fastq + ".matched.fastq", "w") as out2:
