def chunks(self):
        """ Returns a chunk iterator over the sound. """
        if not hasattr(self, '_it'):
            class ChunkIterator(object):
                def __iter__(iter):
                    return iter

                def __next__(iter):
                    try:
                        chunk = self._next_chunk()
                    except StopIteration:
                        if self.loop:
                            self._init_stretching()
                            return iter.__next__()

                        raise

                    return chunk
                next = __next__

            self._it = ChunkIterator()

        return self._it

def chunks(self):
        """ Returns a chunk iterator over the sound. """
        return self._chunks

def _get_column(self, column_or_label):
        """Convert label to column and check column length."""
        c = column_or_label
        if isinstance(c, collections.Hashable) and c in self.labels:
            return self[c]
        elif isinstance(c, numbers.Integral):
            return self[c]
        elif isinstance(c, str):
            raise ValueError('label "{}" not in labels {}'.format(c, self.labels))
        else:
            assert len(c) == self.num_rows, 'column length mismatch'
            return c

def _get_column(self, column_or_label):
        """Convert label to column and check column length."""
        if isinstance(column_or_label, int):
            column = column_or_label
        else:
            column = self.columns.get_loc(column_or_label)
        if column >= self.shape[1]:
            raise ValueError(f"Column {column_or_label} does not exist.")
        return column

def _MatchPath(self, pathspec, response):
    """Check if the responses matches the pathspec (considering options)."""
    to_match = response.pathspec.Basename()
    if pathspec.path_options == rdf_paths.PathSpec.Options.CASE_INSENSITIVE:
      return to_match.lower() == pathspec.path.lower()
    elif pathspec.path_options == rdf_paths.PathSpec.Options.CASE_LITERAL:
      return to_match == pathspec.path
    elif pathspec.path_options == rdf_paths.PathSpec.Options.REGEX:
      return bool(re.match(pathspec.path, to_match, flags=re.IGNORECASE))
    elif pathspec.path_options == rdf_paths.PathSpec.Options.RECURSIVE:
      return True
    raise ValueError("Unknown Pathspec type.")

def _MatchPath(self, pathspec, response):
    """Check if the responses matches the pathspec (considering options)."""
    if not self._pathspec_options.match_case:
      pathspec = pathspec.lower()
      response = response.lower()
    if self._pathspec_options.match_whole_word:
      pathspec = r'\b%s\b' % pathspec
      response = r'\b%s\b' % response
    if self._pathspec_options.match_regex:
      pathspec = re.escape(pathspec)
      response = re.escape(response)
    if self._pathspec_options.match_whole_line:
      pathspec = r'^%s$' % pathspec
      response = r'^%s$' % response
    return re.search(pathspec, response)

def marksheet(self):
        """Returns an pandas empty dataframe object containing rows and columns for marking. This can then be passed to a google doc that is distributed to markers for editing with the mark for each section."""
        columns=['Number', 'Question', 'Correct (a fraction)', 'Max Mark', 'Comments']
        mark_sheet = pd.DataFrame() 
        for qu_number, question in enumerate(self.answers):
            part_no = 0
            for number, part in enumerate(question):
                if number>0:
                    if part[2] > 0:
                        part_no += 1
                        index = str(qu_number+1) +'_'+str(part_no)
                        frame = pd.DataFrame(columns=columns, index=[index])
                        frame.loc[index]['Number'] = index
                        frame.loc[index]['Question'] = part[0]
                        frame.loc[index]['Max Mark'] = part[2]
                        mark_sheet =  mark_sheet.append(frame)

        return mark_sheet.sort(columns='Number')

def number_of_interactions(records, direction=None):
    """
    The number of interactions.

    Parameters
    ----------
    direction : str, optional
        Filters the records by their direction: ``None`` for all records,
        ``'in'`` for incoming, and ``'out'`` for outgoing.
    """
    if direction is None:
        return len(records)
    else:
        return len([r for r in records if r.direction == direction])

