def _build_operator_name(name, function, symbol):
        """implementation details"""
        def add_operator(sym):
            if 'new' in sym or 'delete' in sym:
                return 'operator ' + sym
            return 'operator' + sym
        if isinstance(name, Callable) and None is function:
            name = None
        if name:
            if 'operator' not in name:
                name = add_operator(name)
            return name
        elif symbol:
            return add_operator(symbol)
        return name

def _build_operator_name(name, function, symbol):
        """implementation details"""
        return name + symbol + function.__name__

def distance(self, *args, **kwargs):
        """
        Compute the distance distance between two vectors or more (all combinations) of words

        Parameters
        ----------
        words : one or more words
        n : int (default 10)
            number of neighbors to return
        metric : string (default "cosine")
            What metric to use
        """
        if len(args) == 1:
            words = args[0]
        else:
            words = args

        if not isinstance(words, list):
            words = [words]

        if len(words) == 1:
            return self.distance_single(words[0], **kwargs)

        else:
            return self.distance_multiple(words, **kwargs)

def get_property_values(self, property_name):
        """
        Returns all property values for a particular property name in this collection
        """
        property_values = set()
        for signature_value in self.values():
            if signature_value.get(property_name):
                property_values.add(signature_value[property_name])
        return property_values

def get_property_values(self, property_name):
