        """
        return self.property_values.get(property_name, [])

def async_task(func, *args, **kwargs):
    """Queue a task for the cluster."""
    if not isinstance(func, str):
        func = func.__name__
    task = {
        'func': func,
        'args': args,
        'kwargs': kwargs,
    }
    return _queue_task(task)

