def set_double_stack(socket_obj, double_stack=True):
    # type: (socket.socket, bool) -> None
    """
    Sets up the IPv6 double stack according to the operating system

    :param socket_obj: A socket object
    :param double_stack: If True, use the double stack, else only support IPv6
    :raise AttributeError: Python or system doesn't support V6
    :raise socket.error: Error setting up the double stack value
    """
    if not double_stack:
        return

    if sys.platform == 'win32':
        # Windows doesn't support the double stack
        return

    if sys.platform == 'darwin':
        # macOS doesn't support the double stack
        return

    if sys.platform == 'linux':
        # Linux supports the double stack
        try:
            socket_obj.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)
        except socket.error as e:
            raise socket.error('Error setting up the double stack value: {}'.format(e))

def select_regexp_char(char):
    """
    Select correct regex depending the char
    """
    regexp = '{}'.format(char)

    if not isinstance(char, str) and not isinstance(char, int):
        regexp = ''

    if isinstance(char, str) and not char.isalpha() and not char.isdigit():
        regexp = r"\{}".format(char)

    return regexp

def select_regexp_char(char):
    """
    Select correct regex depending the char
    """
    if char == '(':
        return '\('
    elif char == ')':
        return '\)'
    elif char == '[':
        return '\['
    elif char == ']':
        return '\]'
    elif char == '{':
        return '\{'
    elif char == '}':
        return '\}'
    elif char == '|':
        return '\|'
    elif char == '.':
        return '\.'
    elif char == '*':
        return '\*'
    elif char == '+':
        return '\+'
    elif char == '?':
        return '\?'
    elif char == '^':
        return '\^'
    elif char == '$':
        return '\$'
    elif char == '\\':
        return '\\\\'
    else:
        return char

