def com_google_fonts_check_metadata_unique_weight_style_pairs(family_metadata):
  """METADATA.pb: check if fonts field
     only contains unique style:weight pairs.
  """
  pairs = {}
  for f in family_metadata.fonts:
    styleweight = f"{f.style}:{f.weight}"
    pairs[styleweight] = 1
  if len(set(pairs.keys())) != len(family_metadata.fonts):
    yield FAIL, ("Found duplicated style:weight pair"
                 " in METADATA.pb fonts field.")
  else:
    yield PASS, ("METADATA.pb \"fonts\" field only has"
                 " unique style:weight pairs.")

def com_google_fonts_check_metadata_unique_weight_style_pairs(family_metadata):
  """METADATA.pb: check if fonts field
     only contains unique style:weight pairs.
  """
  if not family_metadata.fonts:
    return
  font_names = [f.name for f in family_metadata.fonts]
  for font_name in font_names:
    if font_name in font_names[font_names.index(font_name)+1:]:
      raise Exception(
          'Font name %s appears more than once in METADATA.pb' % font_name)
  for font in family_metadata.fonts:
    if font.style in ['normal', 'italic']:
      raise Exception(
          'Font %s has invalid style %s' % (font.name, font.style))
    if font.weight not in ['100', '200', '300', '400', '500', '600', '700',
                           '800', '900']:
      raise Exception(
          'Font %s has invalid weight %s' % (font.name, font.weight))
    if font.style == 'normal' and font.weight!= '400':
      raise Exception(
          'Font %s has invalid weight %s' % (font.name, font.weight))
    if font.style == 'italic' and font.weight!= '400':
      raise Exception(
          'Font %s has invalid weight %s' % (font.name, font.weight))

def get_records_with_attachments(attachment_table, rel_object_field="REL_OBJECTID"):
    """returns a list of ObjectIDs for rows in the attachment table"""
    if arcpyFound == False:
        raise Exception("ArcPy is required to use this function")
    OIDs = []
    with arcpy.da.SearchCursor(attachment_table,
                               [rel_object_field]) as rows:
        for row in rows:
            if not str(row[0]) in OIDs:
                OIDs.append("%s" % str(row[0]))
            del row
    del rows
    return OIDs

def to_bytes(s, encoding="utf8"):
    """Converts str s to bytes"""
    if PY_VERSION == 2:
        b = bytes(s)
    elif PY_VERSION == 3:
        b = bytes(s, encoding)
    else:
        raise ValueError("Is Python 4 out already?")

    return b

def to_bytes(s, encoding="utf8"):
    """Converts str s to bytes"""
    return s.encode(encoding)

def prune(force):
    """Remove all configuration for environments."""
    if not force:
        echo_warning(
            'Removing configuration of environments that may be in use will leave '
            'them in a potentially unusable state. If you wish to proceed (e.g. you '
            'have just restarted your machine), you may use the -f / --force flag.'
        )
        abort(code=2)

    checks = get_configured_checks()
    for check in checks:
        envs = get_configured_envs(check)

        if envs:
            echo_info('{}:'.format(check))
            for env in envs:
                echo_waiting('Removing `{}`... '.format(env), nl=False, indent=True)
                remove_env_data(check, env)
                echo_success('success!')

        remove_env_root(check)

def prune(force):
    """Remove all configuration for environments."""
    if force:
        print("Removing all configuration for environments.")
    else:
        print("Removing all configuration for environments.")
        print("Use --force to remove all configuration for environments.")
        return

    for env in get_environments():
        if force:
            print("Removing configuration for environment: {}".format(env))
            remove_environment(env)
        else:
            print("Not removing configuration for environment: {}".format(env))

def common_cli_list_options(f):
    """Add common list options to commands."""

    @click.option(
        "-p",
        "--page",
        default=1,
        type=int,
        help="The page to view for lists, where 1 is the first page",
        callback=validators.validate_page,
    )
    @click.option(
        "-l",
        "--page-size",
        default=30,
        type=int,
        help="The amount of items to view per page for lists.",
        callback=validators.validate_page_size,
    )
    @click.pass_context
    @functools.wraps(f)
    def wrapper(ctx, *args, **kwargs):
        # pylint: disable=missing-docstring
        opts = config.get_or_create_options(ctx)
        kwargs["opts"] = opts
        return ctx.invoke(f, *args, **kwargs)

    return wrapper

def rename(self, newname):
    """
    Rename a cluster.

    @param newname: New cluster name
    @return: An ApiCluster object
    @since: API v2
    """
    dic = self.to_json_dict()
    if self._get_resource_root().version < 6:
      dic['name'] = newname
    else:
      dic['displayName'] = newname
    return self._put_cluster(dic)

