def validate_deserialize(rawmsg, requrl=None, check_expiration=True,
                         decode_payload=True, algorithm_name=DEFAULT_ALGO):
    """
    Validate a JWT compact serialization and return the header and
    payload if the signature is good.

    If check_expiration is False, the payload will be accepted even if
    expired.

    If decode_payload is True then this function will attempt to decode
    it as JSON, otherwise the raw payload will be returned. Note that
    it is always decoded from base64url.
    """
    if not rawmsg:
        raise InvalidTokenError('No token provided')

    try:
        header, payload, signature = rawmsg.split('.')
    except ValueError:
        raise InvalidTokenError('Malformed token')

    if not all((header, payload, signature)):
        raise InvalidTokenError('Malformed token')

    try:
        header_dict = json.loads(base64url_decode(header))
    except (TypeError, ValueError):
        raise InvalidTokenError('Invalid header encoding')

    if 'typ' in header_dict and header_dict['typ']!= 'JWT':
        raise InvalidTokenError('Invalid token type')

    if 'alg' not in header_dict:
        raise InvalidTokenError('Algorithm not specified')

    if algorithm_name is not None and header_dict['alg']!= algorithm_name:
        raise InvalidTokenError('Algorithm not supported')

    if requrl is not None:
        if 'iss' not in header_dict:
            raise InvalidTokenError('Issuer not specified')
        if header_dict['iss']!= requrl:
            raise InvalidTokenError('Issuer mismatch')

    if 'exp' in payload:
        if check_expiration and time.time() > payload['exp']:
            raise ExpiredTokenError('Token has expired')

    try:
        payload_dict = json.loads(base64url_decode(payload))
    except (TypeError, ValueError):
        raise InvalidTokenError('Invalid payload encoding')

    if decode_payload:
        return header_dict, payload_dict

    return header_dict, payload, signature

