def _buildElementTree(self,):
        """Turns object into a Element Tree
        """
        t_binder = ctree.Element(self.name)

        for k,v in self.__dict__.items():
            if k not in ('name', 'urls', 'inputs', 'paging') and v :
                t_binder.set(k,v)

        self.etree = t_binder
        return t_binder

def _get_stddevs(self, C, stddev_types, num_sites):
        """
        Return total standard deviation.
        """
        stddevs = []
        for stddev_type in stddev_types:
            if stddev_type == 'total':
                stddevs.append(np.sqrt(np.sum(C)))
            elif stddev_type =='site':
                stddevs.append(np.sqrt(np.sum(C, axis=0)))
            elif stddev_type == 'bond':
                stddevs.append(np.sqrt(np.sum(C, axis=1)))
            elif stddev_type =='site-bond':
                stddevs.append(np.sqrt(np.sum(C, axis=0) + np.sum(C, axis=1)))
            elif stddev_type =='site-site':
                stddevs.append(np.sqrt(np.sum(C, axis=0) + np.sum(C, axis=1) - np.diag(C)))
            elif stddev_type =='site-site-bond':
                stddevs.append(np.sqrt(np.sum(C, axis=0) + np.sum(C, axis=1) - np.diag(C) + np.sum(C, axis=2)))
            else:
                raise ValueError('Unknown stddev type: {}'.format(stddev_type))
        return stddevs

def generate_tar_files(directory_list):
    """Public function that reads a list of local directories and generates tar archives from them"""

    tar_file_list = []

    for directory in directory_list:
        if dir_exists(directory):
            _generate_tar(directory)                  # create the tar archive
            tar_file_list.append(directory + '.tar')  # append the tar archive filename to the returned tar_file_list list
        else:
            stderr("The directory '" + directory + "' does not exist and a tar archive could not be created from it.", exit=1)            

    return tar_file_list

def to_data(self, value):
        """
        Coerce python data type to simple form for serialization.
        If default value was defined returns the default value if None was passed.
        Throw exception is value is ``None`` is ``required`` is set to ``True``
        """
        try:
            if value is None and self._default is not None:
                return self._export(self.default)
            self._check_required(value)
            value = self._export(value)
            return value
        except ValueError as ex:
            raise ValueError(ex, self._errors['to_data'])

def to_data(self, value):
        """
        Coerce python data type to simple form for serialization.
        If default value was defined returns the default value if None was passed.
        Throw exception is value is ``None`` is ``required`` is set to ``True``
        """
        if value is None:
            if self.required:
                raise ValueError("Field {} is required".format(self.name))
            else:
                return self.default
        else:
            return value

def pdb_to_uniparc(pdb_ids, silent = True, cache_dir = None, manual_additions = {}):
    """ Returns a mapping {PDB ID -> List(UniParcEntry)}
        The UniParcEntry objects have a to_dict() method which may be useful.
    """

    # Map PDB IDs to UniProtKB AC
    if not silent:
        colortext.write("Retrieving PDB to UniProtKB AC mapping: ", 'cyan')
    pdb_ac_mapping = uniprot_map('PDB_ID', 'ACC', pdb_ids, cache_dir = cache_dir, silent = silent)

    for k, v in manual_additions.iteritems():
        if k in pdb_ids:
            if pdb_ac_mapping.get(k):
                pdb_ac_mapping[k].extend(v)
                pdb_ac_mapping[k] = list(set(pdb_ac_mapping[k]))
            else:
                pdb_ac_mapping[k] = v

    if not silent:
        colortext.write("done\n", 'green')

    # Get a list of AC_IDs
    if not silent:
        colortext.write("Retrieving UniProtKB AC to UniProtKB ID mapping: ", 'cyan')
    AC_IDs = set()
    for k, v in pdb_ac_mapping.iteritems():
        AC_IDs = AC_IDs.union(set(v))
    AC_IDs = list(AC_IDs)
    if not silent:
        colortext.write("done\n", 'green')

    # Map UniProtKB ACs to UniParc IDs
    if not silent:
        colortext.write("Retrieving UniProtKB AC to UniParc ID mapping: ", 'cyan')
    ac_uniparc_mapping = uniprot_map('ACC', 'UPARC', AC_IDs, cache_dir = cache_dir, silent = silent)
    for k, v in ac_uniparc_mapping.iteritems():
        assert(len(v) == 1)
        ac_uniparc_mapping[k] = v[0]
    if not silent:
        colortext.write("done\n", 'green')

    # Map UniProtKB ACs to UniProtKB IDs
    ac_id_mapping = uniprot_map('ACC', 'ID', AC_IDs, cache_dir = cache_dir, silent = silent)

    for k, v in ac_id_mapping.iteritems():
        assert(len(v) == 1)
        ac_id_mapping[k] = v[0]

    # Create mapping from PDB IDs to UniParcEntry objects
    m = {}
    if not silent:
        colortext.message("\nRetrieving FASTA sequences for the %d PDB IDs." % len(pdb_ids))
    for pdb_id, ACs in pdb_ac_mapping.iteritems():
        if not silent:
            colortext.write("%s: " % pdb_id, "orange")
        m[pdb_id] = []
        for AC in ACs:
            entry = UniParcEntry(ac_uniparc_mapping[AC], [AC], [ac_id_mapping[AC]], cache_dir = cache_dir)
            m[pdb_id].append(entry)
            if not silent:
                colortext.write(".", "green")
        if not silent:
            print("")
    return m

def pdb_to_uniparc(pdb_ids, silent = True, cache_dir = None, manual_additions = {}):
    """ Returns a mapping {PDB ID -> List(UniParcEntry)}
        The UniParcEntry objects have a to_dict() method which may be useful.
    """
    if cache_dir is None:
        cache_dir = os.path.join(os.path.dirname(__file__), 'cache')
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)
    cache_file = os.path.join(cache_dir, 'pdb_to_uniparc.json')
    if os.path.exists(cache_file):
        with open(cache_file) as f:
            return json.load(f)
    pdb_to_uniparc = {}
    for pdb_id in pdb_ids:
        pdb_to_uniparc[pdb_id] = []
        if not silent:
            print('Getting UniParc entries for PDB ID %s' % pdb_id)
        for entry in get_uniparc_entries_for_pdb(pdb_id, manual_additions = manual_additions):
            pdb_to_uniparc[pdb_id].append(entry)
    with open(cache_file, 'w') as f:
        json.dump(pdb_to_uniparc, f)
    return pdb_to_uniparc

