def walk(self, node: dict):
        """
        Walk thru schema and dereferencing ``id`` and ``$ref`` instances
        """
        if isinstance(node, bool):
            pass
        elif '$ref' in node and isinstance(node['$ref'], str):
            ref = node['$ref']
            node['$ref'] = urlparse.urljoin(self.resolution_scope, ref)
        elif 'id' in node and isinstance(node['id'], str):
            with self.in_scope(node['id']):
                self.store[normalize(self.resolution_scope)] = node
                for _, item in node.items():
                    if isinstance(item, dict):
                        self.walk(item)
        else:
            for _, item in node.items():
                if isinstance(item, dict):
                    self.walk(item)

def walk(self, node: dict):
        """
        Walk thru schema and dereferencing ``id`` and ``$ref`` instances
        """
        if '$ref' in node:
            # dereference
            node = self.dereference(node)

        if 'id' in node:
            # dereference
            node = self.dereference(node)

        if 'properties' in node:
            for prop in node['properties']:
                self.walk(node['properties'][prop])

        if 'items' in node:
            self.walk(node['items'])

        if 'additionalProperties' in node:
            self.walk(node['additionalProperties'])

        if 'allOf' in node:
            for item in node['allOf']:
                self.walk(item)

        if 'anyOf' in node:
            for item in node['anyOf']:
                self.walk(item)

        if 'oneOf' in node:
            for item in node['oneOf']:
                self.walk(item)

        if 'not' in node:
            self.walk(node['not'])

        if 'definitions' in node:
            for item in node['definitions']:
                self.walk(node['definitions'][item])

def _makedirs(path):
    """
    Create a base directory of the provided path and return None.

    :param path: A string containing a path to be deconstructed and basedir
     created.
    :return: None
    """
    dirname, _ = os.path.split(path)
    try:
        os.makedirs(dirname)
    except OSError as exc:
        if exc.errno == errno.EEXIST:
            pass
        else:
            raise

def get_relname_and_parent(self, treepos):
        """Return the (relation name, parent ID) tuple that a node is in.
        Return None if this node is not in a relation.
        """
        if treepos.parent is None:
            return None
        parent_relname = self.get_relname_and_parent(treepos.parent)[0]
        return (parent_relname, treepos.parent.id)

def get_domain_workgroup():
    """
    Get the domain or workgroup the computer belongs to.

    .. versionadded:: 2015.5.7
    .. versionadded:: 2015.8.2

    Returns:
        str: The name of the domain or workgroup

    CLI Example:

    .. code-block:: bash

        salt 'minion-id' system.get_domain_workgroup
    """
    with salt.utils.winapi.Com():
        conn = wmi.WMI()
        for computer in conn.Win32_ComputerSystem():
            if computer.PartOfDomain:
                return {'Domain': computer.Domain}
            else:
                return {'Workgroup': computer.Workgroup}

def update_class_by_type(old, new):
    """ Update declarative classes or fallback on default """
    autoreload.update_class(old, new)
    if isinstance2(old, new, AtomMeta):
        update_atom_members(old, new)

def update_class_by_type(old, new):
    """ Update declarative classes or fallback on default """
    if old is None:
        return new
    if new is None:
        return old
    if old.__name__!= new.__name__:
        raise ValueError("Cannot update class %s with %s" % (old, new))
    return old

def _ValidateFSM(self):
    """Checks state names and destinations for validity.

    Each destination state must exist, be a valid name and
    not be a reserved name.
    There must be a 'Start' state and if 'EOF' or 'End' states are specified,
    they must be empty.

    Returns:
      True if FSM is valid.

    Raises:
      TextFSMTemplateError: If any state definitions are invalid.
    """
    # Check for duplicate state names.
    state_names = set()
    for state in self.states:
      if state.name in state_names:
        raise TextFSMTemplateError('Duplicate state name: %s' % state.name)
      state_names.add(state.name)

    # Check for duplicate destination state names.
    dest_state_names = set()
    for state in self.states:
      for dest_state in state.destinations:
        if dest_state.name in dest_state_names:
          raise TextFSMTemplateError(
              'Duplicate destination state name: %s' % dest_state.name)
        dest_state_names.add(dest_state.name)

    # Check for invalid destination state names.
    for state in self.states:
      for dest_state in state.destinations:
        if dest_state.name not in state_names:
          raise TextFSMTemplateError(
              'Invalid destination state name: %s' % dest_state.name)

    # Check for 'Start' state.
    if 'Start' not in state_names:
      raise TextFSMTemplateError('Missing Start state.')

    # Check for 'EOF' state.
    if 'EOF' in state_names:
      if len(self.states['EOF'].destinations)!= 0:
        raise TextFSMTemplateError('EOF state must have no destinations.')

    # Check for 'End' state.
    if 'End' in state_names:
      if len(self.states['End'].destinations)!= 0:
        raise TextFSMTemplateError('End state must have no destinations.')

    return True

def _get_close_args(self, data):
        """ this functions extracts the code, reason from the close body
        if they exists, and if the self.on_close except three arguments """
        # if the on_close callback is "old", just return empty list
        if sys.version_info < (3, 0):
            if not self.on_close or len(inspect.getargspec(self.on_close).args) != 3:
                return []
        else:
            if not self.on_close or len(inspect.getfullargspec(self.on_close).args) != 3:
                return []

        if data and len(data) >= 2:
            code = 256 * six.byte2int(data[0:1]) + six.byte2int(data[1:2])
            reason = data[2:].decode('utf-8')
            return [code, reason]

        return [None, None]

def _get_close_args(self, data):
        """ this functions extracts the code, reason from the close body
        if they exists, and if the self.on_close except three arguments """
        code = None
        reason = None
        if data:
            if data.startswith('HTTP/1.1'):
                code, reason = data.split(' ', 1)
                code = int(code)
            else:
                reason = data
        return code, reason

def _initialize_if_needed():
    """Initialize ``TENSOR_SPACE_IMPLS`` if not already done."""
    global IS_INITIALIZED, TENSOR_SPACE_IMPLS
    if not IS_INITIALIZED:
        # pkg_resources has long import time
        from pkg_resources import iter_entry_points
        for entry_point in iter_entry_points(group='odl.space', name=None):
            try:
                module = entry_point.load()
            except ImportError:
                pass
            else:
                TENSOR_SPACE_IMPLS.update(module.tensor_space_impls())
        IS_INITIALIZED = True

