def get_objects(self, ids, **args):
        """Fetches all of the given object from the graph.

        We return a map from ID to object. If any of the IDs are
        invalid, we raise an exception.
        """
        if not ids:
            return {}
        if isinstance(ids, six.string_types):
            ids = [ids]
        if not isinstance(ids, list):
            raise TypeError("ids must be a list or a string")
        if not all(isinstance(id, six.string_types) for id in ids):
            raise TypeError("ids must be a list of strings")

        objects = {}
        for id in ids:
            objects[id] = self.get_object(id, **args)
        return objects

def get_device_tree(self):
        """Get a tree of all devices."""
        root = DevNode(None, None, [], None)
        device_nodes = {
            dev.object_path: DevNode(dev, dev.parent_object_path, [],
                                     self._ignore_device(dev))
            for dev in self.udisks
        }
        for node in device_nodes.values():
            device_nodes.get(node.root, root).children.append(node)
        device_nodes['/'] = root
        for node in device_nodes.values():
            node.children.sort(key=DevNode._sort_key)

        # use parent as fallback, update top->down:
        def propagate_ignored(node):
            for child in node.children:
                if child.ignored is None:
                    child.ignored = node.ignored
                propagate_ignored(child)
        propagate_ignored(root)
        return device_nodes

def get_device_tree(self):
        """Get a tree of all devices."""
        return self.device_tree

def parse_template(self):
        """Parse the template string into a dict.

        Find the (large) inner sections first, save them, and remove them from
        a modified string. Then find the template attributes in the modified
        string.

        :returns: dictionary of parsed template
        """
        template = self.template
        # Find the inner sections first, save them, and remove them from
        # a modified string.
        inner_sections = {}
        while True:
            # Find the next section
            start = template.find(self.section_start)
            if start == -1:
                break
            end = template.find(self.section_end, start)
            if end == -1:
                raise ValueError("Unclosed section: %s" % template[start:])
            # Save the section
            section_name = template[start + len(self.section_start):end]
            inner_sections[section_name] = template[start:end + len(self.section_end)]
            # Remove the section from the template
            template = template[:start] + template[end + len(self.section_end):]
        # Find the template attributes in the modified string.
        attributes = {}
        for match in re.finditer(self.attribute_pattern, template):
            attributes[match.group(1)] = match.group(2)
        # Return the parsed template
        return {'attributes': attributes, 'inner_sections': inner_sections}

def T8(word, rules):
    """Join /ie/, /uo/, or /yö/ sequences in syllables that take primary
    stress."""
    for i in range(len(word) - 1):
        if word[i] in rules and word[i + 1] in rules:
            if word[i] == 'i' and word[i + 1] == 'e':
                word[i] = 'ie'
                word[i + 1] = ''
            elif word[i] == 'u' and word[i + 1] == 'o':
                word[i] = 'uo'
                word[i + 1] = ''
            elif word[i] == 'y' and word[i + 1] == 'ö':
                word[i] = 'yö'
                word[i + 1] = ''
    return word

