def muc(clusters, mention_to_gold):
        """
        Counts the mentions in each predicted cluster which need to be re-allocated in
        order for each predicted cluster to be contained by the respective gold cluster.
        <http://aclweb.org/anthology/M/M95/M95-1005.pdf>
        """
        muc = 0
        for cluster in clusters:
            gold_cluster = mention_to_gold[cluster[0]]
            for mention in cluster:
                if mention not in gold_cluster:
                    muc += 1
        return muc

def uint16_gte(a: int, b: int) -> bool:
    """
    Return a >= b.
    """
    return (a == b) or uint16_gt(a, b)

def validate(self, value, redis):
        """
        Validates data obtained from a request in ISO 8061 and returns it in Datetime data type
        """

        value = self.value_or_default(value)

        self.validate_required(value)

        if value is None:
            return None

        if type(value) == str:
            try:
                value = datetime.datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
            except ValueError:
                raise InvalidFieldError(self.name)

        return value

def validate(self, value, redis):
        """
        Validates data obtained from a request in ISO 8061 and returns it in Datetime data type
        """
        try:
            return datetime.strptime(value, '%Y-%m-%dT%H:%M:%S.%fZ')
        except ValueError:
            raise ValidationError('Incorrect date format, should be YYYY-MM-DDTHH:MM:SS.SSSZ')

