def _validate_schema(self, schema, field, value):
        """ {'type': ['dict', 'string'],
             'anyof': [{'validator': 'schema'},
                       {'validator': 'bulk_schema'}]} """
        if schema is None:
            return

        if isinstance(value, Sequence) and not isinstance(value, _str_type):
            self.__validate_schema_sequence(field, schema, value)
        elif isinstance(value, Mapping):
            self.__validate_schema_mapping(field, schema, value)

def _validate_schema(self, schema, field, value):
        """ {'type': ['dict', 'string'],
             'anyof': [{'validator': 'schema'},
                       {'validator': 'bulk_schema'}]} """
        if isinstance(value, dict):
            if 'type' in schema:
                if schema['type'] == 'dict':
                    if 'anyof' in schema:
                        for validator in schema['anyof']:
                            if validator['validator'] =='schema':
                                self._validate_schema(validator['schema'], field, value)
                            elif validator['validator'] == 'bulk_schema':
                                self._validate_bulk_schema(validator['schema'], field, value)
                            else:
                                raise ValueError('Unknown validator: %s' % validator['validator'])
                    else:
                        raise ValueError('Schema must have an anyof key')
                elif schema['type'] =='string':
                    if 'anyof' in schema:
                        for validator in schema['anyof']:
                            if validator['validator'] =='schema':
                                self._validate_schema(validator['schema'], field, value)
                            elif validator['validator'] == 'bulk_schema':
                                self._validate_bulk_schema(validator['schema'], field, value)
                            else:
                                raise ValueError('Unknown validator: %s' % validator['validator'])
                    else:
                        raise ValueError('Schema must have an anyof key')
                else:
                    raise ValueError('Unknown type: %s' % schema['type'])
            else:
                raise ValueError('Schema must have a type key')
        elif isinstance(value, str):
            if 'type' in schema:
                if schema['type'] == 'dict':
                    raise ValueError('Schema must have a type key')
                elif schema['type'] =='string':
                    if 'anyof' in schema:
                        for validator in schema['anyof']:
                            if validator['validator'] =='schema':
                                self._validate_schema(validator['schema'], field, value)
                            elif validator['validator'] == 'bulk_schema':
                                self._validate_bulk_schema(validator['schema'], field, value)
                            else:
                                raise ValueError('Unknown validator: %s' % validator['validator'])
                    else:
                        raise ValueError('Schema must have an anyof key')
                else:
                    raise ValueError('Unknown type: %s' % schema['type'])
            else:
                raise ValueError('Schema must have a type key')
        else:
            raise ValueError('Unknown type: %s' % type(value))

