def insert_id(self, sname, skind, skinds, stype):
        """Inserts a new identifier at the end of the symbol table, if possible.
           Returns symbol index, or raises an exception if the symbol alredy exists
           sname   - symbol name
           skind   - symbol kind
           skinds  - symbol kinds to check for
           stype   - symbol type
        """
        if sname in self.symbols:
            if skind in skinds:
                if self.symbols[sname][0] == skind:
                    if self.symbols[sname][1] == stype:
                        return self.symbols[sname][2]
            raise Exception("Symbol %s already exists" % sname)
        self.symbols[sname] = [skind, stype, len(self.symbols)]
        return self.symbols[sname][2]

def _jks_keystream(iv, password):
    """Helper keystream generator for _jks_pkey_decrypt"""
    cur = iv
    while 1:
        xhash = hashlib.sha1(bytes(password + cur)) # hashlib.sha1 in python 2.6 does not accept a bytearray argument
        cur = bytearray(xhash.digest()) # make sure we iterate over ints in both Py2 and Py3
        for byte in cur:
            yield byte

