def encode_b64(data):
    """Wrapper for b64encode, without having to struggle with bytestrings."""
    byte_string = data.encode('utf-8')
    encoded = base64.b64encode(byte_string)
    return encoded.decode('utf-8')

def encode_b64(data):
    """Wrapper for b64encode, without having to struggle with bytestrings."""
    return b64encode(data).decode('ascii')

def page_erase(addr):
    """Erases a single page."""
    if __verbose:
        print("Erasing page: 0x%x..." % (addr))

    # Send DNLOAD with first byte=0x41 and page address
    buf = struct.pack("<BI", 0x41, addr)
    __dev.ctrl_transfer(0x21, __DFU_DNLOAD, 0, __DFU_INTERFACE, buf, __TIMEOUT)

    # Execute last command
    if get_status() != __DFU_STATE_DFU_DOWNLOAD_BUSY:
        raise Exception("DFU: erase failed")

    # Check command state
    if get_status() != __DFU_STATE_DFU_DOWNLOAD_IDLE:

        raise Exception("DFU: erase failed")

def download_genome(self, name, genome_dir, localname=None, mask="soft", regex=None, invert_match=False, version=None):
        """
        Download a (gzipped) genome file to a specific directory

        Parameters
        ----------
        name : str
            Genome / species name

        genome_dir : str
            Directory to install genome

        mask: str , optional
            Masking, soft, hard or none (all other strings)
        """
        if localname is None:
            localname = name
        if version is None:
            version = self.version
        if regex is None:
            regex = self.regex
        if invert_match is None:
            invert_match = self.invert_match
        if mask is None:
            mask = self.mask
        if not os.path.exists(genome_dir):
            os.makedirs(genome_dir)
        if not os.path.exists(os.path.join(genome_dir, localname)):
            self.download_genome_file(name, genome_dir, localname, mask, regex, invert_match, version)
        else:
            print("Genome already downloaded")

