    return hash(tuple(arg_list))

def p_function_body(p):
    """ function_body : program_co END FUNCTION
                      | program_co END SUB
                      | statements_co END FUNCTION
                      | statements_co END SUB
                      | co_statements_co END FUNCTION
                      | co_statements_co END SUB
                      | END FUNCTION
                      | END SUB
    """
    if p[1] == 'END':
        if p[2] == 'FUNCTION':
            p[0] = ast.FunctionBody(p[3], None)
        elif p[2] == 'SUB':
            p[0] = ast.FunctionBody(None, p[3])
        else:
            raise SyntaxError('Expected END FUNCTION or END SUB')
    else:
        if p[1] == 'program_co':
            p[0] = ast.FunctionBody(p[1], None)
        elif p[1] =='statements_co':
            p[0] = ast.FunctionBody(None, p[1])
        elif p[1] == 'co_statements_co':
            p[0] = ast.FunctionBody(p[1], None)
        else:
            raise SyntaxError('Expected END FUNCTION or END SUB')

