def blue(self, memo=None):
        """
        Constructs a Blueprint out of the current object.

        :param memo:
            A dictionary to cache Blueprints.
        :type memo: dict[T,schedula.utils.blue.Blueprint]

        :return:
            A Blueprint of the current object.
        :rtype: schedula.utils.blue.Blueprint
        """
        if memo is None:
            memo = {}

        if self in memo:
            return memo[self]

        if isinstance(self, (list, tuple)):
            return Blueprint(self, [self.blue(memo) for _ in self])

        if isinstance(self, dict):
            return Blueprint(self, {k: v.blue(memo) for k, v in self.items()})

        if isinstance(self, set):
            return Blueprint(self, {v.blue(memo) for v in self})

        if isinstance(self, (int, float, str, bool, type(None))):
            return Blueprint(self)

        if isinstance(self, (datetime, date, time)):
            return Blueprint(self, self.isoformat())

        if isinstance(self, (timedelta,)):
            return Blueprint(self, self.total_seconds())

        if isinstance(self, (uuid.UUID,)):
            return Blueprint(self, str(self))

        if isinstance(self, (bytes, bytearray)):
            return Blueprint(self, self.hex())

        if isinstance(self, (range,)):
            return Blueprint(self, [self.start, self.stop, self.step])

        if isinstance(self, (complex,)):
            return Blueprint(self, [self.real, self.imag])

        if isinstance(self, (type,)):
            return Blueprint(self, self.__name__)

        if isinstance(self, (staticmethod, classmethod)):
            return Blueprint(self, self.__func__.__name__)

        if isinstance(self, (property,)):
            return Blueprint(self, self.fget.__name__)

        if isinstance(self, (type(self),)):
            return Blueprint(self, self.__name__)

        if isinstance(self, (object,)):
            return Blueprint(self, self.__class__.__name__)

        raise TypeError("Cannot blue %s" % type(self))

