def _set_names(self, values, level=None):
        """
        Set new names on index. Each name has to be a hashable type.

        Parameters
        ----------
        values : str or sequence
            name(s) to set
        level : int, level name, or sequence of int/level names (default None)
            If the index is a MultiIndex (hierarchical), level(s) to set (None
            for all levels).  Otherwise level must be None

        Raises
        ------
        TypeError if each name is not hashable.
        """
        if level is None:
            if self.name is None:
                self.name = values
            else:
                self.name = tuple(values)
        else:
            if isinstance(level, str):
                level = self.get_level_number(level)
            elif isinstance(level, (list, tuple)):
                level = [self.get_level_number(l) for l in level]
            else:
                level = [level]

            if len(level) == 1:
                level = level[0]

            if not isinstance(values, (list, tuple)):
                values = [values]

            if len(values)!= len(level):
                raise ValueError("Must provide as many names as levels")

            for l, v in zip(level, values):
                self.levels[l] = v

