def _render(item: ConfigItem, indent: str = "") -> str:
    """
    Render a single config item, with the provided indent
    """
    if item.type == ConfigItemType.SECTION:
        return f"{indent}{item.name}:\n"
    elif item.type == ConfigItemType.VALUE:
        return f"{indent}{item.name} = {item.value}\n"
    elif item.type == ConfigItemType.COMMENT:
        return f"{indent}{item.name}\n"
    elif item.type == ConfigItemType.GROUP:
        return f"{indent}{item.name}:\n"
    else:
        raise ValueError(f"Unknown config item type: {item.type}")

