def call(self, obj, method, *args, **selectors):
        """
        This keyword can use object method from original python uiautomator

        See more details from https://github.com/xiaocong/uiautomator

        Example:

        | ${accessibility_text} | Get Object            | text=Accessibility | # Get the UI object                        |
        | Call                  | ${accessibility_text} | click              | # Call the method of the UI object 'click' |
        """
        func = getattr(obj, method)
        return func(**selectors)

def compare_root_path(path_cost1, path_cost2, bridge_id1, bridge_id2,
                          port_id1, port_id2):
        """ Decide the port of the side near a root bridge.
            It is compared by the following priorities.
             1. root path cost
             2. designated bridge ID value
             3. designated port ID value """
        if path_cost1 < path_cost2:
            return 1
        elif path_cost1 > path_cost2:
            return -1
        elif bridge_id1 < bridge_id2:
            return 1
        elif bridge_id1 > bridge_id2:
            return -1
        elif port_id1 < port_id2:
            return 1
        elif port_id1 > port_id2:
            return -1
        else:
            return 0

