def tracedb(args):
    """
    %prog tracedb <xml|lib|frg>

    Run `tracedb-to-frg.pl` within current folder.
    """
    p = OptionParser(tracedb.__doc__)
    p.add_option("--verbose", default=False, action="store_true",
                 help="Print more information")
    p.set_defaults(verbose=False)
    opts, args = p.parse_args(args)

    if len(args)!= 1:
        sys.exit(not p.print_help())

    if opts.verbose:
        print("Running tracedb-to-frg.pl")

    if args[0] == "xml":
        cmd = "tracedb-to-frg.pl"
    elif args[0] == "lib":
        cmd = "tracedb-to-frg.pl -lib"
    elif args[0] == "frg":
        cmd = "tracedb-to-frg.pl -frg"
    else:
        sys.exit("Unknown type: %s" % args[0])

    if os.system(cmd):
        sys.exit("Failed to run %s" % cmd)

    if opts.verbose:
        print("Done")

def process_signal(self, signum):
        """Invoked whenever a signal is added to the stack.

        :param int signum: The signal that was added

        """
        if signum == signal.SIGTERM:
            LOGGER.info('Received SIGTERM, initiating shutdown')
            self.stop()
        elif signum == signal.SIGHUP:
            LOGGER.info('Received SIGHUP')
            if self.config.reload():
                LOGGER.info('Configuration reloaded')
                logging.config.dictConfig(self.config.logging)
                self.on_configuration_reloaded()
        elif signum == signal.SIGUSR1:
            self.on_sigusr1()
        elif signum == signal.SIGUSR2:
            self.on_sigusr2()

