def _check_arguments(self):
        """verify the argument of the default symbol and user provided parameters"""
        if self.argument_checked:
            return

        assert(self.symbol is not None)
        self.argument_checked = True

        # check if symbol contain duplicated names.
        _check_arguments(self.symbol)
        # rematch parameters to delete useless ones
        if self.allow_extra_params:
            if self.arg_params:
                arg_names = set(self.symbol.list_arguments())
                self.arg_params = {k : v for k, v in self.arg_params.items()
                                   if k in arg_names}
            if self.aux_params:
                aux_names = set(self.symbol.list_auxiliary_states())
                self.aux_params = {k : v for k, v in self.aux_params.items()
                                   if k in aux_names}

def _check_arguments(self):
        """verify the argument of the default symbol and user provided parameters"""
        if self.symbol is None:
            raise ValueError("symbol is None")
        if self.symbol not in self.symbol_list:
            raise ValueError("symbol is not in symbol_list")
        if self.interval is None:
            raise ValueError("interval is None")
        if self.interval not in self.interval_list:
            raise ValueError("interval is not in interval_list")
        if self.start_date is None:
            raise ValueError("start_date is None")
        if self.end_date is None:
            raise ValueError("end_date is None")
        if self.start_date > self.end_date:
            raise ValueError("start_date is greater than end_date")
        if self.start_date < self.start_date_limit:
            raise ValueError("start_date is less than start_date_limit")
        if self.end_date > self.end_date_limit:
            raise ValueError("end_date is greater than end_date_limit")

def _is_match(self, response, answer):
        """For MC, can call through to MultiChoice Item Record?"""
        # TODO: this varies depending on question type
        if self._only_generic_right_feedback():
            return str(answer.genus_type) == str(RIGHT_ANSWER_GENUS)
        elif self._is_multiple_choice():
            return MultiChoiceItemRecord._is_match(self, response, answer)
        elif self._is_image_sequence() or self._is_mw_sentence():
            return OrderedChoiceItemRecord._is_match(self, response, answer)
        elif self._is_numeric_response():
            return CalculationInteractionItemRecord._is_match(self, response, answer)
        elif self._is_fitb():
            return MagicRandomizedInlineChoiceItemRecord._is_match(self, response, answer)
        return False

def _is_match(self, response, answer):
        """For MC, can call through to MultiChoice Item Record?"""
        return self._is_match_mc(response, answer)

def add_or_update(self, app_id, value):
        """
        Adding or updating the evalution.
        :param app_id:  the ID of the post.
        :param value: the evaluation
        :return:  in JSON format.
        """
        MEvaluation.add_or_update(self.userinfo.uid, app_id, value)

        out_dic = {
            'eval0': MEvaluation.app_evaluation_count(app_id, 0),
            'eval1': MEvaluation.app_evaluation_count(app_id, 1)
        }

        return json.dump(out_dic, self)

def fveq(z,R,dR,P,dP):
    """z=veq in km/s.  
    """
    return 1.0/np.sqrt(1.0-z**2/R**2) - 1.0/np.sqrt(1.0-z**2/(R+dR)**2) + P/np.sqrt(1.0-z**2/(R+dR)**2) - P/np.sqrt(1.0-z**2/R**2)

def board_links_to_ids(self):
        """ Convert board links to ids """
        for board in self.boards:
