def initiate_session(config):
    """
    Initiate a session globally used in prof :
      + Retrive the cookie
      + Log to prof

    Returns an initiated session
    """
    global baseurl
    baseurl = config['DEFAULT']['baseurl']
    if 'session' in config['DEFAULT']:
        cookies = {
            'PHPSESSID': config['DEFAULT']['session']
        }
        prof_session.cookies = requests.utils.cookiejar_from_dict(cookies)
    try:
        valid = verify_session(prof_session, baseurl)
        if not valid:
            # Looks like this session is not valid anymore, try to get a new one
            get_session(prof_session, baseurl, config)
        return prof_session
    except:
        print("{baseurl} not reachable. Verify your connection".format(baseurl=baseurl))
        exit(1)

def _find_library(lib, path):
    """Find a library"""
    for d in path[::-1]:
        real_lib = os.path.join(d, lib)
        if os.path.exists(real_lib):
            return real_lib

def _find_library(lib, path):
    """Find a library"""
    for p in path:
        if os.path.exists(os.path.join(p, lib)):
            return os.path.join(p, lib)
    return None

def status_to_string(dbus_status):
    """
    Converts a numeric dbus snapper status into a string

    CLI Example:

    .. code-block:: bash

        salt '*' snapper.status_to_string <dbus_status>
    """
    if dbus_status == 1:
        return "active"
    elif dbus_status == 2:
        return "inactive"
    elif dbus_status == 3:
        return "failed"
    elif dbus_status == 4:
        return "unknown"
    else:
        return "invalid"

def _frame_structure_check(structure_description):
        """
        check if the structure of the frame is conform to the basic
        frame structure defined by the standard
        :param structure_description: string-list reflecting LLDP-msg structure
        """
        if len(structure_description)!= 11:
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[0]!= "LLDP":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[1]!= "CHASSIS":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[2]!= "PORT":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[3]!= "TTL":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[4]!= "PORT_ID":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[5]!= "TTL":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[6]!= "PORT_ID":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[7]!= "TTL":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[8]!= "PORT_ID":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[9]!= "TTL":
            raise ValueError("structure description is not conform to the basic frame structure")
        if structure_description[10]!= "PORT_ID":
            raise ValueError("structure description is not conform to the basic frame structure")

def message(self, category, subject, msg_file):
        """Send message to all users in `category`."""
        users = getattr(self.sub, category)
        if not users:
            print('There are no {} users on {}.'.format(category, self.sub))
            return

        if msg_file:
            try:
                msg = open(msg_file).read()
            except IOError as error:
                print(str(error))
                return
        else:
            print('Enter message:')
            msg = sys.stdin.read()

        print('You are about to send the following message to the users {}:'
              .format(', '.join([str(x) for x in users])))
        print('---BEGIN MESSAGE---\n{}\n---END MESSAGE---'.format(msg))
        if input('Are you sure? yes/[no]: ').lower() not in ['y', 'yes']:
            print('Message sending aborted.')
            return
        for user in users:
            user.send_message(subject, msg)
            print('Sent to: {}'.format(user))

def message(self, category, subject, msg_file):
        """Send message to all users in `category`."""
        msg = open(msg_file, 'r').read()
        for user in self.get_users(category):
            self.send_message(user, subject, msg)

def _process_data_var(string):
    """Transform datastring to key, values pair.

    All values are transformed to floating point values.

    Parameters
    ----------
    string : str

    Returns
    -------
    Tuple[Str, Str]
        key, values pair
    """
    key, var = string.split("<-")
    if "structure" in var:
        var, dim = var.replace("structure(", "").replace(",", "").split(".Dim")
        # dtype = int if '.' not in var and 'e' not in var.lower() else float
        dtype = float
        var = var.replace("c(", "").replace(")", "").strip().split()
        dim = dim.replace("=", "").replace("c(", "").replace(")", "").strip().split()
        dim = tuple(map(int, dim))
        var = np.fromiter(map(dtype, var), dtype).reshape(dim, order="F")
    elif "c(" in var:
        # dtype = int if '.' not in var and 'e' not in var.lower() else float
        dtype = float
        var = var.replace("c(", "").replace(")", "").split(",")
        var = np.fromiter(map(dtype, var), dtype)
    else:
        # dtype = int if '.' not in var and 'e' not in var.lower() else float
        dtype = float
        var = dtype(var)
    return key.strip(), var

