def squeeze(attrs, inputs, proto_obj):
    """Remove single-dimensional entries from the shape of a tensor."""
    if not isinstance(inputs, list):
        inputs = [inputs]
    for i, input in enumerate(inputs):
        if isinstance(input, tuple):
            inputs[i] = (input[0], tf.squeeze(input[1], attrs.get('squeeze_dims', [])))
        else:
            inputs[i] = tf.squeeze(input, attrs.get('squeeze_dims', []))
    return inputs

def bokeh_issue(name, rawtext, text, lineno, inliner, options=None, content=None):
    """ Link to a Bokeh Github issue.

    Returns 2 part tuple containing list of nodes to insert into the
    document and a list of system messages.  Both are allowed to be
    empty.

    """
    if content is None:
        content = []
    if options is None:
        options = {}
    if name == 'bokeh_issue':
        if len(content)!= 1:
            raise ValueError('bokeh_issue directive takes one argument')
        issue = content[0]
        if not issue.isdigit():
            raise ValueError('bokeh_issue directive takes an integer argument')
        issue = int(issue)
        url = 'https://github.com/bokeh/bokeh/issues/%d' % issue
        text = 'issue %d' % issue
        node = nodes.reference(rawtext, text, refuri=url, **options)
        return [node], []
    else:
        raise ValueError('Unknown directive name %r' % name)

def plural(self):
		""" Tries to scrape the plural version from pons.eu. """

		element = self._first('NN')
		if element:
			if 'kein Plur' in element:
				# There is no plural
				return ['']
			if re.search(', ([\w|\s|/]+)>', element, re.U):
				# Plural form is provided
				return re.findall(', ([\w|\s|/]+)>', element, re.U)[0].split('/')
			if re.search(', -(\w+)>', element, re.U):
				# Suffix is provided
				suffix = re.findall(', -(\w+)>', element, re.U)[0]
				return [self.word + suffix]
			if element.endswith('->'):
				# Plural is the same as singular
				return [self.word]
		return [None]

def plural(self):
		""" Tries to scrape the plural version from pons.eu. """
		if self.plural is None:
			url = "http://pons.eu/pons/search.php?q=%s&l=en" % self.word
			soup = BeautifulSoup(urllib.urlopen(url).read())
			try:
				self.plural = soup.find("div", {"class": "word-form"}).find("span").text
			except AttributeError:
				self.plural = self.word
		return self.plural

def parse_single_value(value):
    """
    Tries to convert to int, float and then gives up and assumes the value
    is of type string. Useful when excepting values that may be string
    representations of numerical values
    """
    if isinstance(value, basestring):
        try:
            if value.startswith('"') and value.endswith('"'):
                value = str(value[1:-1])
            elif '.' in value:
                value = float(value)
            else:
                value = int(value)
        except ValueError:
            value = str(value)
    elif not isinstance(value, (int, float)):
        raise ArcanaUsageError(
            "Unrecognised type for single value {}".format(value))
    return value

def parse_single_value(value):
    """
    Tries to convert to int, float and then gives up and assumes the value
    is of type string. Useful when excepting values that may be string
    representations of numerical values
    """
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value

def getargnames(argspecs, with_unbox=False):
    """Resembles list of arg-names as would be seen in a function signature, including
    var-args, var-keywords and keyword-only args.
    """
    # todo: We can maybe make use of inspect.formatargspec
    args = argspecs.args
    vargs = argspecs.varargs
    try:
        kw = argspecs.keywords
    except AttributeError:
        kw = argspecs.varkw
    try:
        kwonly = argspecs.kwonlyargs
    except AttributeError:
        kwonly = None
    res = []
    if not args is None:
        res.extend(args)
    if not vargs is None:
        res.append('*'+vargs if with_unbox else vargs)
    if not kwonly is None:
        res.extend(kwonly)
    if not kw is None:
        res.append('**'+kw if with_unbox else kw)
    return res

def getargnames(argspecs, with_unbox=False):
    """Resembles list of arg-names as would be seen in a function signature, including
    var-args, var-keywords and keyword-only args.
    """
    if argspecs.args:
        names = argspecs.args
    else:
        names = []
    if argspecs.varargs:
        names.append('*' + argspecs.varargs)
    if argspecs.keywords:
        names.append('**' + argspecs.keywords)
    if argspecs.defaults:
        if with_unbox:
            names.extend(
                ['%s=%s' % (name, unbox(value)) for name, value in zip(names[-len(argspecs.defaults):], argspecs.defaults)]
            )
        else:
            names.extend(
                ['%s=%s' % (name, value) for name, value in zip(names[-len(argspecs.defaults):], argspecs.defaults)]
            )
    if argspecs.kwonlyargs:
        names.extend(argspecs.kwonlyargs)
    if argspecs.kwonlydefaults:
        if with_unbox:
            names.extend(
                ['%s=%s' % (name, unbox(value)) for name, value in zip(names[-len(argspecs.kwonlydefaults):], argspecs.kwonlydefaults)]
            )
        else:
            names.extend(
                ['%s=%s' % (name, value) for name, value in zip(names[-len(argspecs.kwonlydefaults):], argspecs.kwonlydefaults)]
            )
    return names

def transform(self):
        """Return a new transformed matrix.

        :return:    Returns a new transformed Matrix
        :rtype:     Matrix
        """
        t_matrix = Matrix(self._rows, self._columns)
        for col_i, col in enumerate(self.matrix):
            for row_i, entry in enumerate(col):
                t_matrix.set_value(row_i, col_i, entry)
        return t_matrix

def transform(self):
        """Return a new transformed matrix.

        :return:    Returns a new transformed Matrix
        :rtype:     Matrix
        """
        return Matrix(self.matrix)

def _uniquewords(*args):
    """Dictionary of words to their indices.  Helper function to `encode.`"""
    words = {}
    n = 0
    for word in itertools.chain(*args):
        if word not in words:
            words[word] = n
            n += 1
    return words

def _uniquewords(*args):
    """Dictionary of words to their indices.  Helper function to `encode.`"""
    words = set()
    for arg in args:
        words.update(arg)
    return {w: i for i, w in enumerate(words)}

def redirect_response(self, url, permanent=False):
