def get_md5sum(src_file):
    """Returns md5sum of file"""
    with open(src_file, 'rb') as src_data:
        src_content = src_data.read()
        return hashlib.md5(src_content).hexdigest()

def get_md5sum(src_file):
    """Returns md5sum of file"""
    md5 = hashlib.md5()
    with open(src_file, 'rb') as f:
        for chunk in iter(lambda: f.read(128 * md5.block_size), b''):
            md5.update(chunk)
    return md5.hexdigest()

def permissions(self, actor, inherited=None):
        """
        Permissions for this model, plus permissions inherited from the parent.
        """
        if inherited is not None:
            return inherited | super(BaseScopedNameMixin, self).permissions(actor)
        elif self.parent is not None and isinstance(self.parent, PermissionMixin):
            return self.parent.permissions(actor) | super(BaseScopedNameMixin, self).permissions(actor)
        else:
            return super(BaseScopedNameMixin, self).permissions(actor)

def permissions(self, actor, inherited=None):
        """
        Permissions for this model, plus permissions inherited from the parent.
        """
        if inherited is None:
            inherited = self.parent and self.parent.permissions(actor)
        return self.permissions_class(self, actor, inherited)

def angle_v2_rad(vec_a, vec_b):
    """Returns angle between vec_a and vec_b in range [0, PI].  This does not
    distinguish if a is left of or right of b.
    """
    # cos(x) = A * B / |A| * |B|
    return math.acos(vec_a.dot(vec_b) / (vec_a.length() * vec_b.length()))

def angle_v2_rad(vec_a, vec_b):
    """Returns angle between vec_a and vec_b in range [0, PI].  This does not
    distinguish if a is left of or right of b.
    """
    return np.arccos(np.dot(vec_a, vec_b) / (np.linalg.norm(vec_a) * np.linalg.norm(vec_b)))

def stash(self, stash_name: str):
        """
        Stashes the current working tree changes

        :param stash_name: name of the stash
        :type stash_name: str
        """
        if self.stashed:
            LOGGER.error('already stashed')
            sys.exit(-1)
        else:
            if not self.index_is_empty():
                LOGGER.error('cannot stash; index is not empty')
                sys.exit(-1)
            if self.untracked_files():
                LOGGER.error('cannot stash; there are untracked files')
                sys.exit(-1)
            if self.changed_files():
                LOGGER.info('stashing changes')
                self.repo.git.stash('push', '-u', '-k', '-m', f'"{stash_name}"')
                self.stashed = True
            else:
                LOGGER.info('no changes to stash')

