        """Returns the proper list of catalog idstrs based on catalog view"""
        if self.catalog_view == 'all':
            return self.catalog_idstrs
        elif self.catalog_view == 'active':
            return self.catalog_idstrs.filter(active=True)
        elif self.catalog_view == 'inactive':
            return self.catalog_idstrs.filter(active=False)
        else:
            raise ValueError("Invalid catalog view: %s" % self.catalog_view)

def setData(self, index, value, role=Qt.EditRole):
        """ Set the data for the item at the given index to the given value.

        """
        item = self.itemAt(index)
        if not item:
            return False
        d = item.declaration
        if role == Qt.CheckStateRole:
            checked = value == Qt.Checked
            if checked != d.checked:
                d.checked = checked
                d.toggled(checked)
            return True
        elif role == Qt.EditRole:
            if value != d.text:
                d.text = value
            return True
        return super(QAbstractAtomItemModel, self).setData(index, value, role)

def drop_message(self, message):
        """Drop the given message object from the appropriate message list.

        Returns True if the message was found, otherwise False."""

        for type_ in 'errors', 'warnings', 'notices':
            list_ = getattr(self, type_)
            if message in list_:
                list_.remove(message)
                if 'signing_severity' in message:
                    self.signing_summary[message['signing_severity']] -= 1
                return True

        return False

def get_unicode_property(self, i):
        """Get Unicode property."""

        index = i.index
        prop = []
        value = []
        try:
            c = next(i)
            if c.upper() in _ASCII_LETTERS:
                prop.append(c)
            elif c != '{':
                raise SyntaxError("Unicode property missing '{' at %d!" % (i.index - 1))
            else:
                c = next(i)
                if c == '^':
                    prop.append(c)
                    c = next(i)
                while c not in (':', '=', '}'):
                    if c not in _PROPERTY:
                        raise SyntaxError('Invalid Unicode property character at %d!' % (i.index - 1))
                    if c not in _PROPERTY_STRIP:
                        prop.append(c)
                    c = next(i)
                if c in (':', '='):
                    c = next(i)
                    while c != '}':
                        if c not in _PROPERTY:
                            raise SyntaxError('Invalid Unicode property character at %d!' % (i.index - 1))
                        if c not in _PROPERTY_STRIP:
                            value.append(c)
                        c = next(i)
                    if not value:
                        raise SyntaxError('Invalid Unicode property!')
        except StopIteration:
            raise SyntaxError("Missing or unmatched '{' at %d!" % index)

        return ''.join(prop).lower(), ''.join(value).lower()

def get_unicode_property(self, i):
        """Get Unicode property."""
        return self.get_property(i, 0)

def print_conf(self):
        """write a config file to the pathname specified in the parameter.  The
        file extention determines the type of file written and must match a
        registered type.

        parameters:
            config_pathname - the full path and filename of the target config
                               file."""
        if self.config_pathname is None:
            raise ValueError("config_pathname is not set")
        if self.config_pathname == "":
            raise ValueError("config_pathname is empty")
        if self.config_pathname.endswith(".conf"):
            self.write_conf()
        elif self.config_pathname.endswith(".json"):
            self.write_json()
        elif self.config_pathname.endswith(".yaml"):
            self.write_yaml()
        else:
            raise ValueError("config_pathname does not end with a valid file "
                             "extension")

def getText(page, output = "text"):
    """ Extract a document page's text.

    Args:
        output: (str) text, html, dict, json, rawdict, xhtml or xml.

    Returns:
        the output of TextPage methods extractText, extractHTML, extractDICT, extractJSON, extractRAWDICT, extractXHTML or etractXML respectively. Default and misspelling choice is "text".
    """
    if output == "text":
        return page.extractText()
    elif output == "html":
        return page.extractHTML()
    elif output == "dict":
        return page.extractDICT()
    elif output == "json":
        return page.extractJSON()
    elif output == "rawdict":
        return page.extractRAWDICT()
    elif output == "xhtml":
        return page.extractXHTML()
    elif output == "xml":
        return page.extractXML()
    else:
        raise ValueError("Output type not recognised")

def _check_valid_cf_units(self, ds, variable_name):
        """
        Checks that the variable contains units attribute, the attribute is a
        string and the value is not deprecated by CF

        :param netCDF4.Dataset ds: An open netCDF dataset
        :param str variable_name: Name of the variable to be checked
        :rtype:
        :return: List of results
        """
        results = []
        try:
            variable = ds.variables[variable_name]
        except KeyError:
            results.append(
                {
                    "variable": variable_name,
                    "result": "Variable does not exist",
                    "status": "failed",
                }
            )
            return results

        if "units" not in variable.ncattrs():
            results.append(
                {
                    "variable": variable_name,
                    "result": "Variable does not have units attribute",
                    "status": "failed",
                }
            )
            return results

        units = variable.units
        if not isinstance(units, str):
            results.append(
                {
                    "variable": variable_name,
                    "result": "Units attribute is not a string",
                    "status": "failed",
                }
            )
            return results

        if units in CF_UNITS_DEPRECATED:
            results.append(
                {
                    "variable": variable_name,
                    "result": "Units attribute is deprecated by CF",
                    "status": "failed",
                }
            )
            return results

        results.append(
            {
                "variable": variable_name,
                "result": "Units attribute is valid",
                "status": "passed",
            }
        )
        return results

def keys_values(self):
        """Key values might be a list or not, always return a list."""
        keys_values = []
        for value in self.keys.values():
            if isinstance(value, list):
                keys_values += value
            elif isinstance(value, basestring) and not value.startswith('-'):
                # Avoid -99. Should be fixed in geozones
                keys_values.append(value)
            elif isinstance(value, int) and value >= 0:
                # Avoid -99. Should be fixed in geozones
                keys_values.append(str(value))
        return keys_values

def keys_values(self):
        """Key values might be a list or not, always return a list."""
        if isinstance(self.key_values, list):
            return self.key_values
        else:
            return [self.key_values]

def parse_hstring(hs):
    """
    Parse a single item from the telescope server into name, value, comment.
    """
    # split the string on = and /, also stripping whitespace and annoying quotes
    name, value, comment = yield_three(
        [val.strip().strip("'") for val in filter(None, re.split("[=/]+", hs))]
    )

    # if comment has a slash in it, put it back together
    try:
        len(comment)
    except:
        pass
    else:
        comment = '/'.join(comment)
    return name, value, comment

def data_find_all(data, path, dyn_cls=False):
    """Find and return all element-as-tuples in tuple ``data`` using simplified
    XPath ``path``.
    """
    path_parts = path.split("/")
    try:
        sub_elms = tuple(
            el
            for el in data
            if isinstance(el, (tuple, list)) and el[0] == path_parts[0]
        )
    except IndexError:
        return None
    if len(path_parts) > 1:
        ret = []
        for sub_elm in sub_elms:
            for x in data_find_all(sub_elm, "/".join(path_parts[1:])):
                ret.append(x)
        ret = tuple(ret)
    else:
        ret = sub_elms
    if ret and dyn_cls:
        cls = generate_element_class(ret[0])
        return tuple(cls(data=tuple_) for tuple_ in ret)
    return ret

def data_find_all(data, path, dyn_cls=False):
    """Find and return all element-as-tuples in tuple ``data`` using simplified
    XPath ``path``.
    """
    if not path:
        return data
    if not isinstance(data, tuple):
        data = (data,)
    if not dyn_cls:
        return tuple(
            (
                tuple(
                    data_find_all(
                        item,
                        path[1:],
                        dyn_cls=dyn_cls,
                    )
                )
                if isinstance(item, tuple)
                else item
                for item in data
            )
            if path[0] == '*'
            else tuple(
                data_find_all(
                    item,
                    path[1:],
                    dyn_cls=dyn_cls,
                )
                for item in data
                if isinstance(item, tuple) and item[0] == path[0]
            )
            if path[0] in data[0]
            else tuple()
        )
    else:
        return tuple(
            (
                tuple(
                    data_find_all(
                        item,
                        path[1:],
                        dyn_cls=dyn_cls,
                    )
                )
                if isinstance(item, tuple)
                else item
                for item in data
            )
            if path[0] == '*'
            else tuple(
                data_find_all(
                    item,
                    path[1:],
                    dyn_cls=dyn_cls,
                )
                for item in data
                if isinstance(item, tuple) and isinstance(item[0], type) and issubclass(item[0], path[0])
            )
            if path[0] in data[0]
            else tuple()
        )

