def getWindowTitle(self, hwnd):
        """ Gets the title for the specified window """
        length = User32.GetWindowTextLengthW(hwnd)
        if length > 0:
            buffer = ctypes.create_unicode_buffer(length + 1)
            User32.GetWindowTextW(hwnd, buffer, length + 1)
            return buffer.value
        else:
            return None

def _append_filename_extension(self, response: BaseResponse):
        """Append an HTML/CSS file suffix as needed."""
        if response.status_code == 200:
            if response.content_type == "text/html":
                response.content_type = "text/html; charset=utf-8"
                response.filename = response.filename + ".html"
            elif response.content_type == "text/css":
                response.content_type = "text/css; charset=utf-8"
                response.filename = response.filename + ".css"

