def pdb_to_structure(filename):
    """Import a structure object from a PDB file.
    """

    try:
        from Bio.PDB import PDB
    except ImportError:
        print("I can't import Biopython which is needed to handle PDB files.")
        raise
    p = PDB.PDBParser()
    structure = p.get_structure('S', filename)
    for _ in structure.get_chains():
        atoms = [np.array(atom.get_coord()) for atom in structure.get_atoms()]
    return atoms

def from_local_name(acs, attr, name_format):
    """
    :param acs: List of AttributeConverter instances
    :param attr: attribute name as string
    :param name_format: Which name-format it should be translated to
    :return: An Attribute instance
    """
    for aconv in acs:
        #print(ac.format, name_format)
        if aconv.name_format == name_format:
            #print("Found a name_form converter")
            return aconv.to_format(attr)
    return attr

def find_parameter(parameters, **kwargs):
    """
    Given a list of parameters, find the one with the given name.
    """
    matching_parameters = filter_parameters(parameters, **kwargs)
    if len(matching_parameters) == 1:
        return matching_parameters[0]
    elif len(matching_parameters) > 1:
        raise MultipleParametersFound()
    raise NoParameterFound()

def find_parameter(parameters, **kwargs):
    """
    Given a list of parameters, find the one with the given name.
    """
    for parameter in parameters:
        if parameter.name == kwargs['name']:
            return parameter
    return None

def configure_timeindex(self):
        """ Construct a DateTimeIndex with the queried temporal resolution,
        start- and end_snapshot. """
        if self.start_snapshot is None:
            self.start_snapshot = self.snapshots[0]
        if self.end_snapshot is None:
            self.end_snapshot = self.snapshots[-1]
        self.timeindex = pd.date_range(
            start=self.start_snapshot,
            end=self.end_snapshot,
            freq=self.temporal_resolution,
            closed='left'
        )

def _to_r(o, as_data=False, level=0):
    """Helper function to convert python data structures to R equivalents

    TODO: a single model for transforming to r to handle
    * function args
    * lists as function args
    """
    if o is None:
        return "NA"
    if isinstance(o, basestring):
        return o
    if hasattr(o, "r"):
        # bridge to @property r on GGStatement(s)
        return o.r
    elif isinstance(o, bool):
        return "TRUE" if o else "FALSE"
    elif isinstance(o, (list, tuple)):
        inner = ",".join([_to_r(x, True, level+1) for x in o])
        return "c({})".format(inner) if as_data else inner
    elif isinstance(o, dict):
        inner = ",".join(["{}={}".format(k, _to_r(v, True, level+1))
                         for k, v in sorted(o.iteritems(), key=lambda x: x[0])])
        return "list({})".format(inner) if as_data else inner
    return str(o)

def _to_r(o, as_data=False, level=0):
    """Helper function to convert python data structures to R equivalents

    TODO: a single model for transforming to r to handle
    * function args
    * lists as function args
    """
    if isinstance(o, (int, float, str)):
        return o
    elif isinstance(o, list):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, dict):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, tuple):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, np.ndarray):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.DataFrame):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.Series):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.Index):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.MultiIndex):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.Categorical):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.Timestamp):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.Timedelta):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.Period):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.Interval):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.SparseDataFrame):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.SparseSeries):
        return _to_r(o, as_data=True, level=level+1)
    elif isinstance(o, pd.SparseArray):
        return _to_r(o, as_data=True, level=level+1)

def getaddrlist(self):
        """Parse all addresses.

        Returns a list containing all of the addresses.
        """
        result = []
        while self.pos < len(self.field):
            ad = self.getaddress()
            if ad:
                result += ad
            else:
                result.append(('', ''))
        return result

