def CheckDataReceived(self):
        """Tries to extract a Message from the data buffer and process it."""
        if self.data_buffer:
            try:
                msg = Message.from_bytes(self.data_buffer)
                self.data_buffer = b''
                self.process_message(msg)
            except ValueError:
                self.data_buffer = b''

def find_a_system_python(line):
    """Find a Python installation from a given line.

    This tries to parse the line in various of ways:

    * Looks like an absolute path? Use it directly.
    * Looks like a py.exe call? Use py.exe to get the executable.
    * Starts with "py" something? Looks like a python command. Try to find it
      in PATH, and use it directly.
    * Search for "python" and "pythonX.Y" executables in PATH to find a match.
    * Nothing fits, return None.
    """
    if os.path.isabs(line):
        return line

    # Try to find a python.exe in the path.
    if line.startswith("py"):
        return which(line)

    # Try to find a python executable in the path.
    if line.startswith("python"):
        return which(line)

    return None

def get_cached_moderated_reddits(self):
        """Return a cached dictionary of the user's moderated reddits.

        This list is used internally. Consider using the `get_my_moderation`
        function instead.

        """
        if self._mod_subs is None:
            self._mod_subs = {'mod': self.reddit_session.get_subreddit('mod')}
            for sub in self.reddit_session.get_my_moderation(limit=None):
                self._mod_subs[six.text_type(sub).lower()] = sub
        return self._mod_subs

def generate_table_results(output=None, without_header=None):
    """Convert returned data from non-list actions into a nice table for command line usage"""
    array = []
    str_output = str(output)

    if not without_header:
        array.append('RESULT')
        array.append('-' * max(6, len(str_output)))

    array.append(str_output)
    return os.linesep.join(array)

def generate_table_results(output=None, without_header=None):
    """Convert returned data from non-list actions into a nice table for command line usage"""
    if not output:
        output = []
    if not without_header:
        without_header = []
    if not isinstance(output, list):
        output = [output]
    if not isinstance(without_header, list):
        without_header = [without_header]
    if not output:
        return
    if not without_header:
        return
    if len(output)!= len(without_header):
        raise Exception("Output and without_header lists must be the same length")
    for i in range(len(output)):
        if output[i] is None:
            output[i] = ""
        if output[i] == "None":
            output[i] = ""
        if output[i] == "True":
            output[i] = "True"
        if output[i] == "False":
            output[i] = "False"
    print(tabulate([output], headers=without_header))

