def path(append=None, prepend=None, replace=None, on=os):
    """Update the PATH environment variable.

    Can append, prepend, or replace the path.  Each of these expects a string
    or a list of strings (for multiple path elements) and can operate on remote
    connections that offer an @environ@ attribute using the @on@ argument.
    """

    original = on.environ['PATH']

    if replace and (append or prepend):
        raise ValueError("You can not combine append or prepend with replace.")

    if replace:
        if not isinstance(replace, list):
            replace = list(replace)

        on.environ['PATH'] = ':'.join(replace)

    else:
        if append:
            if not isinstance(append, list):
                append = list(append)

            append.insert(0, on.environ['PATH'])
            on.environ['PATH'] = ':'.join(append)

        if prepend:
            if not isinstance(prepend, list):
                prepend = list(prepend)

            prepend.append(on.environ['PATH'])
            on.environ['PATH'] = ':'.join(prepend)

    yield

    on.environ['PATH'] = original

def path(append=None, prepend=None, replace=None, on=os):
    """Update the PATH environment variable.

    Can append, prepend, or replace the path.  Each of these expects a string
    or a list of strings (for multiple path elements) and can operate on remote
    connections that offer an @environ@ attribute using the @on@ argument.
    """
    if on is None:
        on = os
    if on.environ is None:
        return
    if append is not None:
        if isinstance(append, str):
            append = [append]
        on.environ['PATH'] += os.pathsep + os.pathsep.join(append)
    if prepend is not None:
        if isinstance(prepend, str):
            prepend = [prepend]
        on.environ['PATH'] = os.pathsep.join(prepend) + os.pathsep + on.environ['PATH']
    if replace is not None:
        if isinstance(replace, str):
            replace = [replace]
        on.environ['PATH'] = os.pathsep.join(replace)

def get_user_of_group(config, fas, groupname):
    """ Return the list of users in the specified group.

    :arg config: a dict containing the fedmsg config
    :arg fas: a fedora.client.fas2.AccountSystem object instanciated and loged
        into FAS.
    :arg groupname: the name of the group for which we want to retrieve the
        members.
    :return: a list of FAS user members of the specified group.
    """

    if not _cache.is_configured:
        _cache.configure(**config['fmn.rules.cache'])

    key = cache_key_generator(get_user_of_group, groupname)
    def creator():
        if not fas:
            return set()
        return set([u.username for u in fas.group_members(groupname)])
    return _cache.get_or_create(key, creator)

