def align(self, alignraster, how=np.mean, cxsize=None, cysize=None):
        """
        geo.align(geo2, how=np.mean)

        Returns both georasters aligned and with the same pixelsize
        """
        if cxsize is None:
            cxsize = self.cxsize
        if cysize is None:
            cysize = self.cysize
        if cxsize!= alignraster.cxsize or cysize!= alignraster.cysize:
            alignraster = alignraster.resample(cxsize, cysize)
        return self.resample(cxsize, cysize), alignraster

