def send(self, encoded_frame):
        """
        :param bytes encoded_frame:
        """
        if self.socket is not None:
            try:
                with self.__socket_semaphore:
                    self.socket.sendall(encoded_frame)
            except Exception:
                _, e, _ = sys.exc_info()
                log.error("Error sending frame", exc_info=1)
                raise e
        else:
            raise exception.NotConnectedException()

def history(directory=None, rev_range=None, verbose=False, indicate_current=False):
    """List changeset scripts in chronological order."""
    config = current_app.extensions['migrate'].migrate.get_config(directory)
    if alembic_version >= (0, 9, 9):
        command.history(config, rev_range, verbose=verbose, indicate_current=indicate_current)
    elif alembic_version >= (0, 7, 0):
        command.history(config, rev_range, verbose=verbose)
    else:
        command.history(config, rev_range)

def history(directory=None, rev_range=None, verbose=False, indicate_current=False):
    """List changeset scripts in chronological order."""
    if directory is None:
        directory = os.path.join(os.getcwd(),'scripts')
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)
    if not os.path.exists(os.path.join(directory, 'current')):
        raise NotADirectoryError(directory)
    if rev_range is None:
        rev_range = '0:0'
    if verbose:
        print('Listing scripts in %s' % directory)
    for rev in range(int(rev_range.split(':')[0]), int(rev_range.split(':')[1]) + 1):
        script_path = os.path.join(directory, str(rev))
        if os.path.exists(script_path):
            if verbose:
                print('  %s' % script_path)
            if indicate_current and os.path.exists(os.path.join(directory, 'current')):
                if os.path.realpath(script_path) == os.path.realpath(os.path.join(directory, 'current')):
                    print('  %s' % script_path)
                else:
                    print('  %s' % script_path)
            else:
                print('  %s' % script_path)
        else:
            if verbose:
                print('  %s' % script_path)

def get(self, name, failobj=None):
        """Get a header value.

        Like __getitem__() but return failobj instead of None when the field
        is missing.
        """
        name = name.lower()
        for k, v in self._headers:
            if k.lower() == name:
                return self.policy.header_fetch_parse(k, v)
        return failobj

def get(self, name, failobj=None):
        """Get a header value.

        Like __getitem__() but return failobj instead of None when the field
        is missing.
        """
        try:
            return self[name]
        except KeyError:
            return failobj

