def fastFilter(arr, ksize=30, every=None, resize=True, fn='median',
                  interpolation=cv2.INTER_LANCZOS4,
                  smoothksize=0,
                  borderMode=cv2.BORDER_REFLECT):
    """
    fn['nanmean', 'mean', 'nanmedian', 'median']

    a fast 2d filter for large kernel sizes that also 
    works with nans
    the computation speed is increased because only 'every'nsth position 
    within the median kernel is evaluated
    """
    if every is None:
        every = ksize
    if resize:
        arr = cv2.resize(arr, (arr.shape[1] // every, arr.shape[0] // every),
                         interpolation=interpolation)
    if smoothksize > 0:
        arr = cv2.GaussianBlur(arr, (smoothksize, smoothksize), 0)
    if fn == 'nanmean':
        arr = np.nanmean(arr, axis=0)
    elif fn =='mean':
        arr = np.mean(arr, axis=0)
    elif fn == 'nanmedian':
        arr = np.nanmedian(arr, axis=0)
    elif fn =='median':
        arr = np.median(arr, axis=0)
    else:
        raise ValueError('unknown fn')
    if resize:
        arr = cv2.resize(arr, (arr.shape[1] * every, arr.shape[0] * every),
                         interpolation=interpolation)
    if smoothksize > 0:
        arr = cv2.GaussianBlur(arr, (smoothksize, smoothksize), 0)
    return arr

def key_from_password(password):
    """This method just hashes self.password."""
    if isinstance(password, unicode):
        password = password.encode('utf-8')
    if not isinstance(password, bytes):
        raise TypeError("password must be byte string, not %s" % type(password))

    sha = SHA256.new()
    sha.update(password)
    return sha.digest()

def key_from_password(password):
    """This method just hashes self.password."""
    return hashlib.sha256(password.encode('utf-8')).hexdigest()

def ensureExists(cls, values, defaults=None, **context):
        """
        Defines a new record for the given class based on the
        inputted set of keywords.  If a record already exists for
        the query, the first found record is returned, otherwise
        a new record is created and returned.

        :param      values | <dict>
        """
        if defaults is None:
            defaults = {}

        # If the record already exists, return it
        if values.get('id'):
            return cls.get(values.get('id'))

        # Otherwise, create a new record
        return cls.create(values, defaults=defaults, **context)

