def dot(*values: Union[float, complex, np.ndarray]
        ) -> Union[float, complex, np.ndarray]:
    """Computes the dot/matrix product of a sequence of values.

    A *args version of np.linalg.multi_dot.

    Args:
        *values: The values to combine with the dot/matrix product.

    Returns:
        The resulting value or matrix.
    """
    if len(values) == 1:
        if isinstance(values[0], np.ndarray):
            return np.array(values[0])
        return values[0]
    return np.linalg.multi_dot(values)

def get_time_period(value):
        """Get the corresponding TimePeriod from the value.

        Example values: 'all', 'hour', 'day', 'week', or 'month'.
        """
        for time_period in TimePeriod:
            if time_period.period == value:
                return time_period
        raise ValueError('{} is not a valid TimePeriod'.format(value))

def get_time_period(value):
        """Get the corresponding TimePeriod from the value.

        Example values: 'all', 'hour', 'day', 'week', or 'month'.
        """
        if value == 'all':
            return TimePeriod.ALL
        elif value == 'hour':
            return TimePeriod.HOUR
        elif value == 'day':
            return TimePeriod.DAY
        elif value == 'week':
            return TimePeriod.WEEK
        elif value =='month':
            return TimePeriod.MONTH
        else:
            raise ValueError('Invalid time period: {}'.format(value))

