def deserialize(self, d):
        """
        De-serialize a Q object from a (possibly nested) dict.
        """
        if isinstance(d, dict):
            return self.__class__(**d)
        elif isinstance(d, list):
            return [self.deserialize(x) for x in d]
        else:
            return d

def exclude(self, pattern):
        """Exclude files that match 'pattern'."""
        match = translate_pattern(pattern)
        return self._remove_files(match.match)

def exclude(self, pattern):
        """Exclude files that match 'pattern'."""
        self.excludes.append(pattern)

def unsetNsProp(self, ns, name):
        """Remove an attribute carried by a node. """
        if ns not in self.nsProps:
            return
        if name not in self.nsProps[ns]:
            return
        del self.nsProps[ns][name]

def get_element_id(self, complete_name):
        """Get the TocElement element id-number of the element with the
        supplied name."""
        [group, name] = complete_name.split('.')
        element = self.get_element(group, name)
        if element:
            return element.ident
        else:
            logger.warning('Unable to find variable [%s]', complete_name)
            return None

def get_element_id(self, complete_name):
        """Get the TocElement element id-number of the element with the
        supplied name."""
        for element in self.toc_elements:
            if element.name == complete_name:
                return element.id
        return None

def ttl_cache(maxage, maxsize=128):
    """ A time-to-live caching decorator that follows after the style of
    lru_cache.  The `maxage` argument is time-to-live in seconds for each
    cache result.  Any cache entries over the maxage are lazily replaced. """

    def decorator(inner_func):
        wrapper = make_ttl_cache_wrapper(inner_func, maxage, maxsize)
        return functools.update_wrapper(wrapper, inner_func)
    return decorator

def fetch(self, _filter=None, ignore_incremental=False):
        """ Fetch the items from raw or enriched index. An optional _filter
        could be provided to filter the data collected """
        if not self.raw_index:
            raise RuntimeError("Raw index is not set")

        if not self.enriched_index:
            raise RuntimeError("Enriched index is not set")

        if not _filter:
            _filter = {}

        # Fetch the raw data
        raw_data = self.raw_index.fetch(_filter)

        # Fetch the enriched data
        enriched_data = self.enriched_index.fetch(_filter)

        # Merge the data
        data = {}
        for item in raw_data:
            data[item["_id"]] = item

        for item in enriched_data:
            data[item["_id"]] = item

        # Return the data
        return data

def enqueue(self, future):
    """
    Enqueue a future to be processed by one of the threads in the pool.
    The future must be bound to a worker and not have been started yet.
    """
    if not future.worker:
      raise ValueError("Future must be bound to a worker")
    if future.started:
      raise ValueError("Future must not have been started yet")
    self._queue.put(future)

def _get_cookie(self, name, domain):
        """ Return the cookie "name" for "domain" if found
            If there are mote than one, only the first is returned
        """
        for c in self.session.cookies:
            if c.name==name and c.domain==domain:
                return c
        return None

def _get_cookie(self, name, domain):
        """ Return the cookie "name" for "domain" if found
            If there are mote than one, only the first is returned
        """
        for cookie in self.cookies:
            if cookie.domain == domain and cookie.name == name:
                return cookie
        return None

def ArgSpec(*args, **kwargs):
    """
    Validate a function based on the given argspec.

    # Example:
        validations = {
            "foo": [ArgSpec("a", "b", c", bar="baz")]
        }
        def pass_func(a, b, c, bar="baz"):
            pass
        def fail_func(b, c, a, baz="bar"):
            pass
        passes = {"foo": pass_func}
        fails = {"foo": fail_func}

    """

    def argspec_lambda(value):
        argspec = getargspec(value)
        argspec_kw_vals = ()
        if argspec.defaults is not None:
            argspec_kw_vals = argspec.defaults
        kw_vals = {}
        arg_offset = 0
        arg_len = len(argspec.args) - 1
        for val in argspec_kw_vals[::-1]:
            kw_vals[argspec.args[arg_len - arg_offset]] = val
            arg_offset += 1
        if kwargs == kw_vals:
            if len(args) != arg_len - arg_offset + 1:
                return False
            index = 0
            for arg in args:
                if argspec.args[index] != arg:
                    return False
                index += 1
            return True
        return False
    argspec_lambda.err_message = "must match argspec ({0}) {{{1}}}".format(args, kwargs)
    # as little sense as negating this makes, best to just be consistent.
    argspec_lambda.not_message = "must not match argspec ({0}) {{{1}}}".format(args, kwargs)
    return argspec_lambda

