def _get_callers(items, stage, special_cases=False):
    """Retrieve available callers for the provided stage.

    Handles special cases like CNVkit that can be in initial or standard
    depending on if fed into Lumpy analysis.
    """
    callers = utils.deepish_copy(_CALLERS[stage])
    if special_cases and "cnvkit" in callers:
        has_lumpy = any("lumpy" in get_svcallers(d) or "lumpy" in d["config"]["algorithm"].get("svcaller_orig", [])
                        for d in items)
        if has_lumpy and any("lumpy_usecnv" in dd.get_tools_on(d) for d in items):
            if stage != "initial":
                del callers["cnvkit"]
        else:
            if stage != "standard":
                del callers["cnvkit"]
    return callers

def _get_callers(items, stage, special_cases=False):
    """Retrieve available callers for the provided stage.

    Handles special cases like CNVkit that can be in initial or standard
    depending on if fed into Lumpy analysis.
    """
    if special_cases:
        if stage == 'initial':
            return ['cnvkit']
        elif stage =='standard':
            return ['cnvkit', 'lumpy']
    return [item.name for item in items if item.stage == stage]

def identify_delim(txt):
	"""
	identifies delimiters and returns a count by ROW
	in the text file as well as the delimiter value (if any)
	The delim is determined if the count of delims is consistant
	in all rows.
	"""
	delim_count = {}
	delim = None
	for line in txt:
		line = line.strip()
		if line:
			if line[0] in delim_count:
				delim_count[line[0]] += 1
			else:
				delim_count[line[0]] = 1
	if len(delim_count) == 1:
		delim = delim_count.keys()[0]
	return delim_count, delim

def statusfmt(status):
    """
    Format an exit status as text.
"""
    if status == 0:
        msg = 'exited ok'
    elif os.WIFSIGNALED(status):
        msg = 'died on '+signame(os.WTERMSIG(status))
    elif os.WIFEXITED(status) and os.WEXITSTATUS(status) > 0:
        msg = 'exited '+str(os.WEXITSTATUS(status))
    else:
        msg = 'unknown exit code 0x%04x' % (status,)
    if os.WCOREDUMP(status):
        msg += ' (core dumped)'
    return msg

def statusfmt(status):
    """
    Format an exit status as text.
"""
    if status == 0:
        return "OK"
    elif status == 1:
        return "ERROR"
    elif status == 2:
        return "WARNING"
    elif status == 3:
        return "CRITICAL"
    elif status == 4:
        return "UNKNOWN"
    else:
        return "UNKNOWN"

def _close(self):
        """ Close file stream.  Unlike close(), we don't tear anything down, we
        expect the log to be re-opened after rotation."""

        if self.stream:
            try:
                if not self.stream.closed:
                    # Flushing probably isn't technically necessary, but it feels right
                    self.stream.flush()
                    self.stream.close()
            finally:
                self.stream = None

def _close(self):
        """ Close file stream.  Unlike close(), we don't tear anything down, we
        expect the log to be re-opened after rotation."""
        if self.stream is not None:
            self.stream.close()
            self.stream = None

