def normalize_species_name(name):
    """
    If species name was "Homo sapiens" then replace spaces with underscores
    and return "homo_sapiens". Also replace common names like "human" with
    "homo_sapiens".
    """
    if name == "Homo sapiens":
        return "homo_sapiens"
    elif name == "human":
        return "homo_sapiens"
    else:
        return name.replace(" ", "_").lower()

def rmtree_errorhandler(func, path, exc_info):
    """On Windows, the files in .svn are read-only, so when rmtree() tries to
    remove them, an exception is thrown.  We catch that here, remove the
    read-only attribute, and hopefully continue without problems."""
    # if file type currently read only
    if os.stat(path).st_mode & stat.S_IREAD:
        # convert to read/write
        os.chmod(path, stat.S_IWRITE)
        # use the original function to repeat the operation
        func(path)
        return
    else:
        raise

def rmtree_errorhandler(func, path, exc_info):
    """On Windows, the files in .svn are read-only, so when rmtree() tries to
    remove them, an exception is thrown.  We catch that here, remove the
    read-only attribute, and hopefully continue without problems."""
    if not is_windows:
        raise

    import stat
    import os
    import errno

    if not os.access(path, os.W_OK):
        # It's read-only, so try to remove the read-only attribute
        os.chmod(path, stat.S_IWRITE)
        func(path)
    else:
        # It's not read-only, so re-raise the error
        raise

