        Args:
            left: the left variable of the ICONS to return; if `None`,
                return all ICONS
        """
        if left is not None:
            return self._icons[left]
        else:
            return list(chain.from_iterable(self._icons.values()))

def _get_key_info(self):
        """Get key info appropriate for signing."""
        if self._key_info_cache is None:
            self._key_info_cache = agent_key_info_from_key_id(self.key_id)
        return self._key_info_cache

def _get_key_info(self):
        """Get key info appropriate for signing."""
        if self.key_type == 'rsa':
            return self.key.publickey().exportKey(format='DER')
        else:
            return self.key.exportKey(format='DER')

def sample_hull(hull,domain,isDomainFinite):
    """sample_hull: Sample the upper hull

    Input:
       hull       - hull structure (see setup_hull for a definition of this)
       domain          - [.,.] upper and lower limit to the domain
       isDomainFinite  - [.,.] is there a lower/upper limit to the domain?

    Output:
       a sample from the hull

    History:
       2009-05-21 - Written - Bovy
    """
    u= stats.uniform.rvs()
    #Find largest zs[jj] such that scum[jj] < u
    #The first bin is a special case
    if hull[5][0] >= u:
        if hull[3][0] == 0:
            if isDomainFinite[0]:
                thissample= domain[0]+u/hull[5][0]*(hull[4][0]-domain[0])
            else:
                thissample= 100000000 #Throw some kind of error
        else:
            thissample= hull[4][0]+1./hull[3][0]*m.log(1.-hull[3][0]*hull[0]*(hull[5][0]-u)/m.exp(hull[6][0]))
    else:
        if len(hull[5]) == 1:
            indx= 0
        else:
            indx= 1
            while indx < len(hull[5]) and hull[5][indx] < u:
                indx= indx+1
            indx= indx-1
        if m.fabs(hull[3][indx+1]) == 0:
            if indx != (len(hull[5])-1):
                thissample= hull[4][indx]+(u-hull[5][indx])/(hull[5][indx+1]-hull[5][indx])*(hull[4][indx+1]-hull[4][indx])
            else:
                if isDomainFinite[1]:
                    thissample= hull[4][indx]+(u-hull[5][indx])/(1.-hull[5][indx])*(domain[1]-hull[4][indx])
                else:
                    thissample= 100000 #Throw some kind of error
        else:
            thissample= hull[4][indx]+1./hull[3][indx+1]*m.log(1.+hull[3][indx+1]*hull[0]*(u-hull[5][indx])/m.exp(hull[6][indx]))
    return thissample

def sample_hull(hull,domain,isDomainFinite):
    """sample_hull: Sample the upper hull

    Input:
       hull       - hull structure (see setup_hull for a definition of this)
       domain          - [.,.] upper and lower limit to the domain
       isDomainFinite  - [.,.] is there a lower/upper limit to the domain?

    Output:
       a sample from the hull

    History:
       2009-05-21 - Written - Bovy
    """
    if isDomainFinite[0]:
        if isDomainFinite[1]:
            return numpy.random.uniform(domain[0],domain[1])
        else:
            return numpy.random.uniform(domain[0],domain[1])
    else:
        if isDomainFinite[1]:
            return numpy.random.uniform(domain[0],domain[1])
        else:
            return numpy.random.uniform(domain[0],domain[1])

def inner_parser(self) -> BaseParser:
        """
        Prepares inner config parser for config stored at ``endpoint``.

        :return: an instance of :class:`~django_docker_helpers.config.backends.base.BaseParser`

        :raises config.exceptions.KVStorageValueIsEmpty: if specified ``endpoint`` does not contain a config
        """
        if not self.endpoint:
            raise KVStorageValueIsEmpty("endpoint")

        return self.parser_class(self.endpoint)

def get_dir(path, dest, saltenv='base', template=None, gzip=None, **kwargs):
    """
    Used to recursively copy a directory from the salt master

    CLI Example:

    .. code-block:: bash

        salt '*' cp.get_dir salt://path/to/dir/ /minion/dest

    get_dir supports the same template and gzip arguments as get_file.
    """
    if template is None:
        template = __salt__['config.option']('file_client')
    if gzip is None:
        gzip = __salt__['config.option']('gzip_compress')
    if not os.path.isdir(dest):
        os.makedirs(dest)
    for root, dirs, files in os.walk(path):
        for f in files:
            src = os.path.join(root, f)
            dest = os.path.join(dest, os.path.relpath(src, path))
            if os.path.exists(dest):
                continue
            __salt__['cp.get_file'](src, dest, saltenv=saltenv, template=template, gzip=gzip, **kwargs)

def _plot_time_list(sdat, lovs, tseries, metas, times=None):
    """Plot requested profiles"""
    if times is None:
        times = {}
    for vfig in lovs:
        fig, axes = plt.subplots(nrows=len(vfig), sharex=True,
                                 figsize=(12, 2 * len(vfig)))
        axes = [axes] if len(vfig) == 1 else axes
        fname = ['time']
        for iplt, vplt in enumerate(vfig):
            ylabel = None
            for ivar, tvar in enumerate(vplt):
                fname.append(tvar)
                time = times[tvar] if tvar in times else tseries['t']
                axes[iplt].plot(time, tseries[tvar],
                                conf.time.style,
                                label=metas[tvar].description)
                lbl = metas[tvar].kind
                if ylabel is None:
                    ylabel = lbl
                elif ylabel != lbl:
                    ylabel = ''
            if ivar == 0:
                ylabel = metas[tvar].description
            if ylabel:
                _, unit = sdat.scale(1, metas[tvar].dim)
                if unit:
                    ylabel += ' ({})'.format(unit)
                axes[iplt].set_ylabel(ylabel)
            if vplt[0][:3] == 'eta':  # list of log variables
                axes[iplt].set_yscale('log')
            axes[iplt].set_ylim(bottom=conf.plot.vmin, top=conf.plot.vmax)
            if ivar:
                axes[iplt].legend()
            axes[iplt].tick_params()
        _, unit = sdat.scale(1, 's')
        if unit:
            unit = ' ({})'.format(unit)
        axes[-1].set_xlabel('Time' + unit)
        axes[-1].set_xlim((tseries['t'].iloc[0], tseries['t'].iloc[-1]))
        axes[-1].tick_params()
        misc.saveplot(fig, '_'.join(fname))

def _plot_time_list(sdat, lovs, tseries, metas, times=None):
    """Plot requested profiles"""
    if times is None:
        times = sdat.time
    for t in times:
        _plot_time(sdat, lovs, tseries, metas, t)

def rename_with_prefix(self, prefix="", new_path=None, in_place=True, remove_desc=True):
        """Rename every sequence based on a prefix."""
        # Temporary path #
        if new_path is None: prefixed = self.__class__(new_temp_path())
        else:                prefixed = self.__class__(new_path)
        # Generator #
        def prefixed_iterator():
            for i,read in enumerate(self):
                read.id = prefix + read.id
                if remove_desc: read.description = ""
                yield read
        # Do it #
        prefixed.write(prefixed_iterator())
        prefixed.close()
        # Replace it #
        if in_place:
            os.remove(self.path)
            shutil.move(prefixed, self.path)
        return prefixed

def rename_with_prefix(self, prefix="", new_path=None, in_place=True, remove_desc=True):
        """Rename every sequence based on a prefix."""
        if new_path is None:
            new_path = self.path
        if not in_place:
            new_path = new_path.replace(".txt", "_renamed.txt")
        if not os.path.exists(new_path):
            os.makedirs(new_path)
        for seq in self.sequences:
            seq.rename(prefix, new_path, remove_desc)
        self.path = new_path

def post_article_content(self, content, url, max_pages=25):
        """
        POST content to be parsed to the Parser API.

        Note: Even when POSTing content, a url must still be provided.

        :param content: the content to be parsed
        :param url: the url that represents the content
        :param max_pages (optional): the maximum number of pages to parse
            and combine. Default is 25.
        """
        if not content:
            raise ValueError('content cannot be empty')
        if not url:
            raise ValueError('url cannot be empty')
        if max_pages < 1:
            raise ValueError('max_pages must be greater than 0')

        data = {
            'content': content,
            'url': url,
           'max_pages': max_pages
        }
        return self.post(data)

def initialize(self):
        """
        Initialize the handler before requests are called
        """
        if not hasattr(self.application, 'event_listener'):
            log.debug('init a listener')
            self.application.event_listener = EventListener(
                self.application.mod_opts,
                self.application.opts,
            )

        if not hasattr(self, 'saltclients'):
            local_client = salt.client.get_local_client(mopts=self.application.opts)
            self.saltclients = {
                'local': local_client.run_job_async,
                # not the actual client we'll use.. but its what we'll use to get args
                'local_async': local_client.run_job_async,
                'runner': salt.runner.RunnerClient(opts=self.application.opts).cmd_async,
                'runner_async': None,  # empty, since we use the same client as `runner`
                }

        if not hasattr(self, 'ckminions'):
            self.ckminions = salt.utils.minions.CkMinions(self.application.opts)

def ensure_ndarray_or_sparse(A, shape=None, uniform=None, ndim=None, size=None, dtype=None, kind=None):
    r""" Ensures A is an ndarray or a scipy sparse matrix and does an assert_array with the given parameters

    Returns
    -------
    A : ndarray
        If A is already an ndarray, it is just returned. Otherwise this is an independent copy as an ndarray

    """
    if isinstance(A, np.ndarray):
        if shape is not None:
            assert_array(A, shape=shape, uniform=uniform, ndim=ndim, size=size, dtype=dtype, kind=kind)
        return A
    elif isinstance(A, scipy.sparse.spmatrix):
        if shape is not None:
            assert_array(A, shape=shape, uniform=uniform, ndim=ndim, size=size, dtype=dtype, kind=kind)
        return A.toarray()
    else:
        raise TypeError("A is not an ndarray or a scipy sparse matrix")

def _get_file_name(self, contentDisposition,
                       url, ext=".unknown"):
        """ gets the file name from the header or url if possible """
        if self.PY2:
            if contentDisposition is not None:
                return re.findall(r'filename[^;=\n]*=(([\'"]).*?\2|[^;\n]*)',
                                  contentDisposition.strip().replace('"', ''))[0][0]
            elif os.path.basename(url).find('.') > -1:
                return os.path.basename(url)
        elif self.PY3:
            if contentDisposition is not None:
                p = re.compile(r'filename[^;=\n]*=(([\'"]).*?\2|[^;\n]*)')
                return p.findall(contentDisposition.strip().replace('"', ''))[0][0]
            elif os.path.basename(url).find('.') > -1:
                return os.path.basename(url)
        return "%s.%s" % (uuid.uuid4().get_hex(), ext)

