def _get_file_name(self, contentDisposition,
                       url, ext=".unknown"):
        """ gets the file name from the header or url if possible """
        if contentDisposition:
            return contentDisposition.filename
        else:
            return url.split("/")[-1] + ext

def render(self, container, rerender=False):
        """Flow the flowables into the containers that have been added to this
        chain."""
        if rerender:
            container.clear()
            if not self._rerendering:
                # restore saved state on this chain's 1st container on this page
                self._state = copy(self._fresh_page_state)
                self._rerendering = True
        try:
            self.done = False
            self.flowables.flow(container, last_descender=None,
                                state=self._state)
            # all flowables have been rendered
            if container == self.last_container:
                self._init_state()    # reset state for the next rendering loop
            self.done = True
        except PageBreakException as exc:
            self._state = exc.flowable_state
            self._fresh_page_state = copy(self._state)
            raise
        except EndOfContainer as e:
            self._state = e.flowable_state
            if container == self.last_container:
                # save state for when ReflowRequired occurs
                self._fresh_page_state = copy(self._state)
        except ReflowRequired:
            self._rerendering = False
            raise

def render(self, container, rerender=False):
        """Flow the flowables into the containers that have been added to this
        chain."""
        # TODO: this is a bit of a hack, but we need to make sure that the
        # first container is always the first one to be rendered.
        if not rerender:
            self.containers = [container] + self.containers
        for container in self.containers:
            container.render(self)

def thread_exists(self, thread_id):
        """Check if a thread exists or has 404'd.

        Args:
            thread_id (int): Thread ID

        Returns:
            bool: Whether the given thread exists on this board.
        """
        return self._requests_session.head(
            self._url.thread_api_url(
                thread_id=thread_id
                )
        ).ok

def extract(self, item, list_article_candidate):
        """Compares the extracted authors.

        :param item: The corresponding NewscrawlerItem
        :param list_article_candidate: A list, the list of ArticleCandidate-Objects which have been extracted
        :return: A string, the most likely authors
        """
        if len(list_article_candidate) == 1:
            return list_article_candidate[0].authors
        elif len(list_article_candidate) == 0:
            return None
        else:
            # If there are multiple candidates, we have to compare them
            # We do this by comparing the number of authors in the article candidate with the number of authors in the
            # item. If the number of authors in the item is smaller, we return the authors of the article candidate.
            # If the number of authors in the item is larger, we return the authors of the item.
            # If the number of authors in the item is equal, we return the authors of the article candidate.
            if len(item['authors']) < len(list_article_candidate[0].authors):
                return list_article_candidate[0].authors
            elif len(item['authors']) > len(list_article_candidate[0].authors):
                return item['authors']
            else:
                return list_article_candidate[0].authors

def replace_command(command, broken, matched):
    """Helper for *_no_command rules."""
    new_cmds = get_close_matches(broken, matched, cutoff=0.1)
    return [replace_argument(command.script, broken, new_cmd.strip())
            for new_cmd in new_cmds]

def replace_command(command, broken, matched):
    """Helper for *_no_command rules."""
    if broken:
        return command.replace(matched, '')
    else:
        return command.replace(matched, 'no'+ matched)

def cut_edges(graph):
    """
    Return the cut-edges of the given graph.

    A cut edge, or bridge, is an edge of a graph whose removal increases the number of connected
    components in the graph.

    @type  graph: graph, hypergraph
    @param graph: Graph.

    @rtype:  list
    @return: List of cut-edges.
    """
    recursionlimit = getrecursionlimit()
    setrecursionlimit(max(len(graph.nodes())*2,recursionlimit))

    # Dispatch if we have a hypergraph
    if 'hypergraph' == graph.__class__.__name__:
        return _cut_hyperedges(graph)

    pre = {}    # Pre-ordering
    low = {}    # Lowest pre[] reachable from this node going down the spanning tree + one backedge
    spanning_tree = {}
    reply = []
    pre[None] = 0

    for each in graph:
        if (each not in pre):
            spanning_tree[each] = None
            _cut_dfs(graph, spanning_tree, pre, low, reply, each)

    setrecursionlimit(recursionlimit)
    return reply

