def search_records(self, domain, record_type, name=None, data=None):
        """
        Returns a list of all records configured for the specified domain that
        match the supplied search criteria.
        """
        if name is None and data is None:
            raise ValueError("Must specify either name or data")

        if name is not None and data is not None:
            raise ValueError("Must specify either name or data, not both")

        if name is not None:
            name = name.strip()
            if not name:
                raise ValueError("Name cannot be empty")

        if data is not None:
            data = data.strip()
            if not data:
                raise ValueError("Data cannot be empty")

        if record_type not in self.record_types:
            raise ValueError("Invalid record type")

        if domain not in self.domains:
            raise ValueError("Invalid domain")

        if name is not None:
            return self.records.get((domain, record_type, name), [])

        if data is not None:
            return [r for r in self.records.values() if r.data == data]

        return []

def __find_rows(self, find_url, **attributes):
        """
            :param find_url: URL of the find api
            :type find_url: string
            :return: The Response returned by requests including the list of documents based on find_url
            :rtype: Response object
        """
        req = self.url + find_url

        # Add range and sort parameters
        params = {
            "range": attributes.get("range", "all"),
            "sort": attributes.get("sort", [])
        }

        # Add body
        data = {
            "query": attributes.get("query", {})
        }

        try:
            return requests.post(req, params=params, json=data, proxies=self.proxies, auth=self.auth, verify=self.cert)
        except requests.exceptions.RequestException as e:
            raise TheHiveException("Error: {}".format(e))

def validate_token(self, token):
    """retrieve a subject based on a token. Valid means we return a participant
       invalid means we return None
    """
    try:
        payload = jwt.decode(token, self.secret, algorithms=[self.algorithm])
        return payload
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

def num_examples(self):
        """The number of examples this subset spans."""
        if self.is_list:
            return len(self.list_or_slice)
        else:
            start, stop, step = self.slice_to_numerical_args(
                self.list_or_slice, self.original_num_examples)
            return stop - start

def num_examples(self):
        """The number of examples this subset spans."""
        return len(self.indices)

def package_info(self):
        """Collect built libraries names and solve flatc path.
        """
        self.cpp_info.libs = tools.collect_libs(self)
        self.cpp_info.includedirs = [os.path.join("include", "flatbuffers")]
        if self.settings.os == "Windows":
            self.cpp_info.libs.extend(["ws2_32", "userenv"])
        elif self.settings.os == "Linux":
            self.cpp_info.libs.extend(["pthread"])
        elif self.settings.os == "Macos":
            self.cpp_info.libs.extend(["c++"])

