def _int_size(x):
    """Return the smallest size int that can store the value"""
    if -0x80 <= x <= 0x7F:
        return 1
    elif -0x8000 <= x <= 0x7FFF:
        return 2
    elif -0x80000000 <= x <= 0x7FFFFFFF:
        return 4
    elif long(-0x8000000000000000) <= x <= long(0x7FFFFFFFFFFFFFFF):
        return 8
    else:
        raise RuntimeError("Cannot represent value: " + str(x))

def _int_size(x):
    """Return the smallest size int that can store the value"""
    if x < 0:
        return 1
    elif x < 2**8:
        return 1
    elif x < 2**16:
        return 2
    elif x < 2**32:
        return 4
    else:
        return 8

def parse_systemd_ini(content):
    """
    .. warning::
        This function is deprecated, please use :py:class:`SystemdConf` instead.

    Function to parse config format file, the result format is dictionary.
    """
    if not content:
        return {}
    result = {}
    for line in content.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('['):
            section = line[1:-1]
            result[section] = {}
        else:
            key, value = line.split('=', 1)
            result[section][key] = value
    return result

