def update(self, payload):
        """Updates the queried record with `payload` and returns the updated record after validating the response

        :param payload: Payload to update the record with
        :raise:
            :NoResults: if query returned no results
            :MultipleResults: if query returned more than one result (currently not supported)
        :return:
            - The updated record
        """
        try:
            result = self.get_one()
            if 'sys_id' not in result:
                raise NoResults()
        except MultipleResults:
            raise MultipleResults("Update of multiple records is not supported")
        except NoResults as e:
            e.args = ('Cannot update a non-existing record',)
            raise

        if not isinstance(payload, dict):
            raise InvalidUsage("Update payload must be of type dict")

        response = self.session.put(self._get_table_url(sys_id=result['sys_id']), data=json.dumps(payload))
        return self._get_content(response)

def update_record(self, common_name, **fields):
        """Update fields in an existing record"""

        record = self.get_record(common_name)
        if fields is not None:
            for field, value in fields:
                record[field] = value
        self.save()
        return record

def update_record(self, common_name, **fields):
        """Update fields in an existing record"""
        self.update_records([common_name], **fields)

def kill_process(procname, scriptname):
    """kill WSGI processes that may be running in development"""
    try:
        pid = int(subprocess.check_output(['ps', '-A', '-o', 'pid,command']))
    except subprocess.CalledProcessError:
        return
    for line in pid.split('\n'):
        if procname in line and scriptname in line:
            pid = line.split()[0]
            os.kill(int(pid), signal.SIGKILL)

def folding_model_gradient(rvec, rcut):
    r"""computes the potential's gradient at point rvec"""
    rnorm = np.linalg.norm(rvec)
    if rnorm == 0.0:
        return np.zeros(rvec.shape)
    r = rnorm - rcut
    if r < 0.0:
        return -5.0 * r * rvec / rnorm
    return (1.5 * r - 2.0) * rvec / rnorm

def folding_model_gradient(rvec, rcut):
    r"""computes the potential's gradient at point rvec"""
    rcut = np.array(rcut)
    rvec = np.array(rvec)
    r = np.linalg.norm(rvec)
    if r > rcut:
        return np.zeros(3)
    else:
        return -2.0 * rvec / r

def _get_output_path(self):
        """Checks if a base file label / path is set. Returns absolute path."""
        if self.Parameters['-o'].isOn():
            output_path = self._absolute(str(self.Parameters['-o'].Value))
        else:
            raise ValueError("No output path specified.")
        return output_path

def _get_output_path(self):
        """Checks if a base file label / path is set. Returns absolute path."""
        if self.base_file_label:
            return os.path.join(self.output_dir, self.base_file_label)
        else:
            return self.output_dir

def rename_get_variable(mapping):
    """
    Args:
        mapping(dict): an old -> new mapping for variable basename. e.g. {'kernel': 'W'}

    Returns:
        A context where the variables are renamed.
    """
    def custom_getter(getter, name, *args, **kwargs):
        splits = name.split('/')
        basename = splits[-1]
        if basename in mapping:
            basename = mapping[basename]
            splits[-1] = basename
            name = '/'.join(splits)
        return getter(name, *args, **kwargs)
    return custom_getter_scope(custom_getter)

def rename_get_variable(mapping):
    """
    Args:
        mapping(dict): an old -> new mapping for variable basename. e.g. {'kernel': 'W'}

    Returns:
        A context where the variables are renamed.
    """
    return tf.contrib.slim.arg_scope(
        [slim.variable],
        **{
            'collections': [tf.GraphKeys.GLOBAL_VARIABLES],
            'trainable': True,
            'initializer': tf.contrib.layers.xavier_initializer(),
           'regularizer': tf.contrib.layers.l2_regularizer(0.0005),
           'reuse': None,
            'name': lambda name, **kwargs: rename_variable(name, mapping)
        }
    )

def __write_k_v(self, k, v, top=False, bot=False, multi=False, indent=False):
        """
        Write a key value pair to the output file. If v is a list, write multiple lines.
        :param k: Key
        :param v: Value
        :param bool top: Write preceding empty line
        :param bool bot: Write following empty line
        :param bool multi: v is a list
        :return none:
        """
        if top:
            self.noaa_txt += "\n#"
        if multi:
            for item in v:
                if indent:
                    self.noaa_txt += "\n#     {}: {}".format(str(k), str(item))
                else:
                    self.noaa_txt += "\n# {}: {}".format(str(k), str(item))
        else:
            if indent:
                self.noaa_txt += "\n#     {}: {}".format(str(k), str(v))
            else:
                self.noaa_txt += "\n# {}: {}".format(str(k), str(v))
        if bot:
            self.noaa_txt += "\n#"
        return

def copy(self, release):
        """Copy the workfile of the given release to the releasefile location

        This is inteded to be used in a action unit.

        :param release: the release with the release and workfile
        :type release: :class:`Release`
        :returns: an action status
        :rtype: :class:`ActionStatus`
        :raises: None
        """
        if not self.releasefile:
            raise ValueError("No releasefile defined")
        if not release:
            raise ValueError("No release given")
        if not release.workfile:
            raise ValueError("No workfile defined for release")
        if not release.release:
            raise ValueError("No release defined for release")
        if not release.releasefile:
            raise ValueError("No releasefile defined for release")
        if not release.releasefile.startswith(self.releasefile):
            raise ValueError("Releasefile does not start with releasefile")
        if not release.workfile.startswith(self.workfile):
            raise ValueError("Workfile does not start with workfile")
        if not release.workfile.endswith(".zip"):
            raise ValueError("Workfile does not end with.zip")
        if not release.releasefile.endswith(".zip"):
            raise ValueError("Releasefile does not end with.zip")
        if not os.path.exists(release.workfile):
            raise ValueError("Workfile does not exist")
        if os.path.exists(release.releasefile):
            raise ValueError("Releasefile already exists")
        shutil.copy(release.workfile, release.releasefile)
        return ActionStatus(status=True)

def scroll_up(self):
        """
        Returns the previous command, if any.
        """
        self._index += 1
        nb_commands = len(self._history)
        if self._index >= nb_commands:
            self._index = nb_commands - 1
        try:
            return self._history[self._index]
        except IndexError:
            return ''

def scroll_up(self):
        """
        Returns the previous command, if any.
        """
        if self.index > 0:
            self.index -= 1
            return self.history[self.index]
        else:
            return None

def addRelationships(
        self,
        data: list,
        LIMIT: int = 20,
        _print: bool = True,
        crawl: bool = False,
        ) -> list:
        """
        data = [{
            "term1_id", "term2_id", "relationship_tid",
            "term1_version", "term2_version",
            "relationship_term_version",}]
        """
        if _print:
            print("Adding relationships...")
        if crawl:
            self.crawlRelationships(data, LIMIT)
        else:
            self.addRelationshipsFromData(data, LIMIT)
        return self.getRelationships(LIMIT)

