def list_jobs(tail):
    """Show info about the existing crawler jobs."""
    query = (
        db.session.query(models.CrawlerJob)
        .order_by(models.CrawlerJob.id.desc())
    )
    if tail != 0:
        query = query.limit(tail)

    results = query.yield_per(10).all()
    _show_table(results=results)

def list_jobs(tail):
    """Show info about the existing crawler jobs."""
    jobs = get_jobs()
    if not jobs:
        print("No crawler jobs found.")
        return
    print("Found %d crawler jobs:" % len(jobs))
    for job in jobs:
        print("  %s" % job)
        if tail:
            print("    %s" % get_job_tail(job))

def close(self):
        """Close and remove hooks."""
        if not self.closed:
            self._ipython.events.unregister('post_run_cell', self._fill)
            self._box.close()
            self.closed = True

def rename(self, dn: str, new_rdn: str, new_base_dn: Optional[str] = None) -> None:
        """
        rename a dn in the ldap database; see ldap module. doesn't return a
        result if transactions enabled.
        """
        if self.transactions:
            self.transaction_rename(dn, new_rdn, new_base_dn)
        else:
            self.ldap.rename_s(dn, new_rdn, new_base_dn)
